quests[526] = { id = 526, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lightforge Ingots", description = "You might have found one lightforge ingot in that chest, but that's not enough to craft anything decent!\n\nYou should go back there and look for more.  Maybe the murlocs around that wrecked ship have lightforge ingots on them.", sourceObjective = "Gather 5 lightforge ingots, then return to Glorin Steelbrow in the Wetlands.", progress = "Did you find the lightforge iron you need?", completion = "Ah, you found them!  Now let's get this lightforge iron hammered into something useful, eh?", sourceObjectiveStatus = "unverified-source-field" }
quests[527] = { id = 527, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle of Hillsbrad", description = "Stand at attention while addressing me, {class}.\n\nI am under direct command of Varimathras.  We are to quell the human infestation until our apothecaries can develop the new plague.\n\nOur information leads us to believe that the town of Hillsbrad is vulnerable to attack.  Your first assignment is aimed at disrupting their food supply and infrastructure.\n\nTravel west.  Raid the northernmost farms of Hillsbrad Fields.  Make sure that the landowners, Farmer Ray and Farmer Getz, are executed as well.", sourceObjective = "Kill 6 Hillsbrad Farmhands, 6 Hillsbrad Farmers, Farmer Ray and Farmer Getz and report back to Darthalia in Tarren Mill.", progress = "As High Executor of Tarren Mill, under the direct command of Varimathras and the Dark Lady, you are subject to follow my command.\n\nPerhaps you take this war with the Alliance lightly?  If such is the case I should behead you right here and now.  Otherwise, travel west to the town of Hillsbrad and wage battle against the humans, as ordered.\n\nDismissed.", completion = "At ease, {class}.  I see you have returned from battle.  My sources tell me you performed well on the Hillsbrad front.", sourceObjectiveStatus = "unverified-source-field" }
quests[528] = { id = 528, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle of Hillsbrad", description = "Word of the attack on the northern farms has the townsfolk panicked.  Most excellent.\n\nOur Deathstalkers report peasants fleeing to the fields in southern Hillsbrad.  The fools think they can hide in the orchards and escape their doom.\n\nProve them wrong, {name}.  Return to Hillsbrad Fields and seek out the cowering peasants.  Lay waste to them in the name of our Dark Lady.\n\nDismissed!", sourceObjective = "Kill 15 Hillsbrad Peasants and report back to Darthalia in Tarren Mill.", progress = "You have your orders, {class}.  Quit dawdling here in Tarren Mill when there is work to be done elsewhere.", completion = "The grip of death is tightening around the town of Hillsbrad.  The battle goes well.", sourceObjectiveStatus = "unverified-source-field" }
quests[529] = { id = 529, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle of Hillsbrad", description = "The humans of Hillsbrad have been putting up unexpected resistance.  The problem appears to be that the townsfolk are being armed by the local blacksmith.  We need to shut down all supply lines.\n\nYour mission will be to execute Blacksmith Verringtan.  Slay his apprentices as well.  While there, bring back a shipment of iron from their stockpile.  The supplies will come in handy when we are done with the conquering of Hillsbrad and begin razing Southshore.", sourceObjective = "Kill Blacksmith Verringtan and 4 Hillsbrad Apprentice Blacksmiths.\n\nRetrieve a shipment of iron and report back to Darthalia in Tarren Mill.", progress = "Were you able to carry out your orders, {class}?  Did you dispose of Verringtan and his assistants?  And where is that iron shipment?", completion = "Mission accomplished, {class}.  And carried out quite skillfully, I might add.", sourceObjectiveStatus = "unverified-source-field" }
quests[530] = { id = 530, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Husband's Revenge", description = "Valdred, once my good friend, was my wife's murderer.  Although I am incapable of grieving, I do yearn for revenge.  If you kill Valdred and bring me his cursed hands, then I will reward you.\n\nI last heard he was at the Greymane Wall in southern Silverpine, trying to flee into the kingdom of Gilneas.", sourceObjective = "Kill Valdred Moray.\n\nBring his hands to Raleigh Andrean in the Undercity.", progress = "Do you have those hands, {name}?", completion = "Ah, good.  These hands killed my wife, Deliah.  Revenge for her murder was my only care, and you were the instrument of that revenge.\n\nHere, take the ring you returned earlier.  Deliah has been dead to me for so long, her ring is a bauble I no longer care to keep.  Instead, I will keep these hands as a remembrance of my friend's betrayal.", sourceObjectiveStatus = "unverified-source-field" }
quests[531] = { id = 531, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vyrin's Revenge", description = "Light! Don't bring things like that into the Lodge... it's unsanitary, unspeakable, un... un... unsanitary!\n\nJust get it out of here, will you? No one wants to see your bloody little trophy, really!", sourceObjective = "Bring Ol' Sooty's head to Vyrin Swiftwind at the Farstrider Lodge.", progress = "Great job, {name}! We really showed him! Here, give me the head and I'll take care of it.", completion = "Thanks for helping me out with my little plan, {name}. I've been itching for months to get back at that snooty, stuck-up boy, and I'd say we did a pretty good job! Here, have this, you've earned it.", sourceObjectiveStatus = "unverified-source-field" }
quests[532] = { id = 532, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle of Hillsbrad", description = "The town of Hillsbrad is in disarray and we believe it will soon fall.  We must, however, persist in our ruthlessness until the human scum are wiped from the foothills for eternity.\n\nDespite their overwhelming losses, the humans rally around their leadership and keep fighting.  We must eliminate their leader, Magistrate Burnside, as well as the town council.  Destroy their revered political document as well, the Hillsbrad Proclamation.  And while you're at it, steal the town registry.", sourceObjective = "Kill Magistrate Burnside and 4 Hillsbrad Councilmen. Destroy the Hillsbrad Proclamation. Steal the Hillsbrad Town Registry. Report back to Darthalia in Tarren Mill afterwards.", progress = "What news have you?", completion = "News of your glories in Hillsbrad traveled fast.  You have done well, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[533] = { id = 533, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infiltration", description = "At last we begin to hear word and rumor, find evidence of Gol'dir's whereabouts. The humans have been moving him around, but we are narrowing down our search and focusing on the large Syndicate camp just north of here.\n\nGo there, {name}, and bring back whatever information you can get your hands on.", sourceObjective = "Retrieve information about Gol'dir's whereabouts for Krusk in Tarren Mill.", progress = "Have you found anything? I fear Gol'dir's prospects grow worse by the day...", completion = "Finally, we know where Gol'dir is being held. The camp in question is not too far from here, and hopefully they will not be as well prepared as they were when they captured us the first time.", sourceObjectiveStatus = "unverified-source-field" }
quests[535] = { id = 535, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valik", description = "Urrgh... Injured and dying and confronted with the enemy.\n\nNo doubt you'll kill me anyway, but if you bring me some Southshore stout--your kind does drink, don't they?--I'll tell you what you want to know.", sourceObjective = "Bring a mug of Southshore Stout to Valik in the Syndicate camp.", progress = "Did you bring me something to drink or did you just come back to finish the job?", completion = "Given my impending death, I think I can safely say that this is the sweetest tasting thing ever... Here, take this, won't do me any good when I'm dead.\n\nWell, get on with it!", sourceObjectiveStatus = "unverified-source-field" }
quests[536] = { id = 536, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Down the Coast", description = "Transferred from the Stormwind city guard to Southshore, a town that should be abandoned by the looks of it... Smell of the harbor day and night.\n\nNot to mention ol' Redpath... Wants me to take care of the murlocs. Ha! \n\nI can barely rouse myself to go out to some of the pockets of the overgrown fish down the Western Strand. If you would go in my place and take care of them, I'd appreciate it.", sourceObjective = "Kill 10 Torn Fin Tidehunters and 10 Torn Fin Oracles for Lieutenant Farren Orinelle in Southshore.", progress = "Another ale, please, the last one just seemed to have disappeared!\n\nLight, how much longer am I going to be stuck out here?\n\nOh, it's you, {name}. Have you killed those murlocs yet?", completion = "I hope this will be enough to convince Redpath that I've--ha!--been carrying out his orders and ridding Southshore of the terrible and horrible menace of the dreaded murlocs! For there could be no greater evil than the ravages of overgrown fish!", sourceObjectiveStatus = "unverified-source-field" }
quests[537] = { id = 537, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Council", description = "The letter you brought me was written by a being who calls himself Nagaz, a member of the Argus Wake.  I don't know what this Argus Wake is, but if they're in alliance with the Syndicate then they must be a threat.\n\nI want you to find Nagaz and the Argus Shadow Mages mentioned in that letter.  I want you to find them, and kill them.\n\nSearch in the Uplands, where the Syndicate is strongest.  It is north of Strahnbrad.\n\nWith luck, you'll find these envoys of the Argus Wake there.", sourceObjective = "Kill 4 Argus Shadow Mages.\n\nBring the Head of Nagaz to Magistrate Maleb in Southshore.", progress = "Did you find the envoys of The Argus Wake?", completion = "Well done, {name}.  The Argus Wake does not sound like a group we want running the Syndicate.\n\nAnd although you may have destroyed their leader here, Nagaz was merely the servant of another.  The Argus Wake might run deep through the continent of Azeroth.\n\nOr even the world.", sourceObjectiveStatus = "unverified-source-field" }
quests[538] = { id = 538, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Southshore", description = "{name}.  If you don't mind a long journey then I have a task for you, to again help Stormwind fill its library.\n\nThe old kingdom of Alterac fell after the great war, and it had a large collection of books.  It's a tragedy that the city is ruined, but even more tragic is all of their knowledge lost!  We must recover what we can.\n\nSouthshore is the closest town to the Ruins of Alterac.  Go there and speak with Loremaster Dibbs.  He can direct you to the ruins, and to what books may be found there.", sourceObjective = "Speak with Loremaster Dibbs in Southshore.", completion = "Ah yes, I remember Milton.  A bookworm, no doubt.  Bless him.\n\nAnd he's right.  The Ruins of Alterac still hold stores of knowledge in danger of being lost!\n\nOgres now dwell in Alterac, and they don't care much for higher learning.", sourceObjectiveStatus = "unverified-source-field" }
quests[539] = { id = 539, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle of Hillsbrad", description = "The Hillsbrad Town Registry indicates that the Azureload Mine is under Alliance control.  Furthermore, the mine is a prime source of iron ore for the Alliance armories.\n\nEven though we've struck a decisive blow to the town of Hillsbrad, the Alliance still supports and protects the Azureload Mine fervently.\n\nThe mine lies due south of Hillsbrad.  Go there and slay the foreman, a human by the name of Bonds.  Kill his miners as well.  That should send a clear message to the Alliance.", sourceObjective = "Kill Foreman Bonds and 10 Hillsbrad Miners and report back to Darthalia in Tarren Mill.", progress = "You were given direct orders to attack the Azureload Mine.  Your reasons for loafing about Tarren Mill better be good or I will behead you for treason.", completion = "The Dark Lady will be pleased when she learns that she has a new mine from which she can arm her soldiers.", sourceObjectiveStatus = "unverified-source-field" }
quests[540] = { id = 540, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preserving Knowledge", description = "Those beastly ogres now reside within Alterac's ruins, and I shudder to think what they're doing with the precious books still there.  You must recover what you can!\n\nEnter the Ruins of Alterac and search for tomes looted by the ogres.  Get whatever you can find and bring them to me, but also seek out one book in particular: The Arm of Gri'lek.  It contains ancient troll lore that I must learn, and the Ruins of Alterac was the last known location of an intact copy of this book.", sourceObjective = "Bring 5 Recovered Tomes and the Worn Leather Book containing The Arm of Gri'lek to Loremaster Dibbs in Southshore.", progress = "I wish I could search the ruins too, but I fear these bones wouldn't hold me during my climb up the mountains.  However, how does your hunt for knowledge progress, {name}?", completion = "Oh, you got them!  Splendid!  I must begin studying the Arm of Gri'lek immediately!", sourceObjectiveStatus = "unverified-source-field" }
quests[541] = { id = 541, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle of Hillsbrad", description = "Dwarves aiding the humans?  Damn those filthy little beasts.\n\nWe shall test the strength of the so-called Alliance.  We'll see how anxious those little ankle-bashers are to help the humans once they feel our wrath.  We know exactly where their stronghold is in this territory.\n\nThey have established a barracks in southeastern Hillsbrad along Thoradin's Wall called Dun Garok.  The final mission of this battle is to lay siege on Dun Garok, {class}.  Captain Ironhill, their leader, must die.", sourceObjective = "Travel to Dun Garok and kill 8 Mountaineers, 4 Riflemen, 2 Priests and Captain Ironhill and report back to Darthalia in Tarren Mill.", progress = "Dun Garok proves to be too much of an obstacle for you, {class}?  And here I thought you had established yourself valiantly in Hillsbrad.\n\nIf you're not up to handle the mission assigned to you, I will find another who can produce better results.  As for you, well, I am sure the Dark Lady could always use more grave diggers back in Tirisfal Glades.", completion = "Your actions on the battlefield are worthy of the highest praise.", sourceObjectiveStatus = "unverified-source-field" }
quests[542] = { id = 542, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Milton", description = "I need to spend some time studying the Arm of Gri'lek book you brought me, though I'm sure Milton is eager to get the other recovered books into Stormwind's collection.\n\nHere are the books you gathered from the Ruins of Alterac, packed and catalogued.  Take them back to Milton Sheaf in Stormwind and I'm sure he'll be grateful.", sourceObjective = "Bring the Tomes of Alterac to Milton Sheaf in Stormwind.", progress = "{name}, you've returned!  How did your foray into Alterac go?  Did you bring anything back with you?", completion = "My oh my!  Look at these!  I can't believe they survived the ruination of Alterac.  And all those ogres too!\n\nThank you, {name}.  Thank you so much!  You have helped preserve human knowledge, and you add to the grandeur of the Royal Library of Stormwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[543] = { id = 543, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Perenolde Tiara", description = "The Perenolde Tiara is an old heirloom of the Perenolde \"nobles\" - the ruling family of Alterac before that kingdom fell to ruin.  It is said to have been crafted by master jewelers in Ironforge, and fitted with the finest of emeralds.\n\nWhen Alterac was destroyed the Tiara was lost, but there are rumors that an Ogre Mage, Grel'borg the Miser, found the tiara and now wanders the Ruins of Alterac searching for more treasures.\n\nWe would have you acquire the tiara for us.", sourceObjective = "Bring the Perenolde Tiara to Remington Ridgewell in Stormwind.", progress = "Salutations, {name}.  Do try to avoid stepping on my pant cuffs.  This outfit is newly tailored.", completion = "Ah, this is splendid.  This will have to be cleaned of course, but you really outdid yourself, {name}.  I will have someone prepare the tiara and place it within our collection posthaste.\n\nAs I'm sure you will agree, our gratitude is as grand as our collection.", sourceObjectiveStatus = "unverified-source-field" }
quests[544] = { id = 544, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prison Break In", description = "I came to Tarren Mill to research, but now must resolve a crisis.  You see, four Forsaken fled the Undercity a few months ago.  They turned their backs on their brethren, but what's worse...they stole from the Dark Lady.\n\nThese thieves broke into a secure vault and stole four artifacts, items our apothecaries required in certain studies.  Sylvanas would have these artifacts returned.\n\nThe thieves fled the Undercity to Dalaran, and those wizards quarantined them in the Lordamere Internment Camp.", sourceObjective = "Find the traitors and recover their artifacts, then return to Magus Voidglare in Tarren Mill.", progress = "Did you find the thieves?  And more importantly, did you find what they stole?", completion = "You have done a great service for the Forsaken, {name}.  These artifacts have been sorely missed.\n\nAnd it is good to hear that Kegan and the other betrayers have found justice.", sourceObjectiveStatus = "unverified-source-field" }
quests[545] = { id = 545, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dalaran Patrols", description = "The wizards of Dalaran constructed a vast, magical dome around the heart of their city.  Some believe it was for protection from the violence of these times, while others say they merely wanted solitude, to study and plot.\n\nI don't care what the reason was.  I do care that the ruined outskirts of their city, outside the dome, may hide valuable magical treasures.\n\nBut the area is patrolled by the wizards and their elemental slaves.\n\nSo hunt them, and return when their numbers are sufficiently reduced.", sourceObjective = "Kill 6 Dalaran Summoners and 12 Elemental Slaves, then return to Magus Voidglare in Tarren Mill.", progress = "Have you yet thinned the Dalaran patrols around their ruins?", completion = "Very good.  Those ruins should now be safe enough to search, if one is careful.\n\nThank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[546] = { id = 546, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Souvenirs of Death", description = "I hear you were enlisted by Darthalia to wage war on the humans of Hillsbrad.  So jealous I am. . .\n\nWhile you're off having all the fun -- slaying humans, pillaging the town, terrorizing innocent people -- I am stuck standing guard here in Tarren Mill.\n\nPerhaps you'll take pity on an old Deathguard like myself?  You see I am collecting human skulls.  And you will be fighting humans for quite some time.  Over the course of your long battle, bring me 30 skulls and I will make it worth your while.", sourceObjective = "Deathguard Samsa of Tarren Mill wants 30 Hillsbrad Human Skulls.", progress = "So the lucky {name} returns?  How many humans have you slaughtered today?  Hundreds I do hope!\n\nHave you any skulls for me?", completion = "Precious skulls!  So beautiful!  I owe you as promised, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[547] = { id = 547, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Humbert's Sword", description = "High Executor Darthalia sent me to keep watch of Dun Garok from a distance.  I had set up camp just out of sight.  But when morning came and I had to boil water, I left to gather firewood.\n\nWhen I returned to camp, I discovered my gear was missing.\n\nApparently some dwarven scouts from Dun Garok had passed by and made off with it.  I need my sword!  If you can get it back for me I would be so grateful.  So many dwarves there...it will be quite difficult to find the dirty little thief who stole it.", sourceObjective = "Retrieve Deathguard Humbert's sword from Dun Garok and return it to him in Tarren Mill.", progress = "Were you able to retrieve my sword, {name}?  High Executor Darthalia will hang me from the rafters if she discovers my folly.", completion = "You found it!\n\nAh, I feel so complete with my precious sword back in my hand.  Many thanks to you!", sourceObjectiveStatus = "unverified-source-field" }
quests[549] = { id = 549, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Syndicate Personnel", description = "By the authority of Lady Sylvanas, all members of the organization known as the Syndicate are wanted dead. Those brought into custody or taken prisoner will be summarily executed. They are currently known to be amassing in the ruins of Durnholde Keep, to the southeast of Tarren Mill.\n\nA handsome reward is offered to all who bring proof of their deeds to High Executor Darthalia.", sourceObjective = "Kill 10 Syndicate Rogues and 10 Syndicate Watchmen. Return to High Executor Darthalia in Tarren Mill for your reward.", progress = "Do you have nothing better to do than stand here before me, {class}? As High Executor, I have more pressing matters than to stare at your rotting visage.", completion = "Excellent, {class}. At this rate, the Syndicate pest will be rid from the land in no time.", sourceObjectiveStatus = "unverified-source-field" }
quests[550] = { id = 550, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle of Hillsbrad", description = "Because you fought with such valor and perseverance in the Battle of Hillsbrad, I have written this commendation, extolling your heroics in combat for the high command to recognize.\n\nTake this sealed commendation to Varimathras in the Undercity.  Go with pride, {class}.", sourceObjective = "Take Darthalia's Sealed Commendation to Varimathras in the Undercity.", progress = "What brings a {class} all the way to the Undercity from the battlefield?", completion = "So you are the infamous {class} who struck such a decisive blow against the Alliance forces in the Hillsbrad Foothills?  Word of your glorious exploits traveled quickly to the Undercity.\n\nYou have quite a future in the Dark Lady's ranks if you continue to show such leadership and expertise in battle.\n\nWhile our primary threat is the Lich King's Scourge army descending from the north, the human \"problem\" continues to impede our battle plans.  You, however, have shown that the humans can and will fall.", sourceObjectiveStatus = "unverified-source-field" }
quests[551] = { id = 551, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ensorcelled Parchment", description = "This parchment is enchanted with a spell, rendering it indecipherable.  But one word at the top of the paper can be read:\n\n\n      Nagaz", sourceObjective = "Take the Ensorcelled Parchment to Loremaster Dibbs in Southshore.", progress = "Oh.  You have something you'd like me to look at?  Some scrap of lore gathered from up in the mountains, I hope...", completion = "More encrypted notes?\n\nI wish I had the talents to decrypt all the strange bits of writing that trickle down from Alterac.  But I'm afraid I lack the knowledge.", sourceObjectiveStatus = "unverified-source-field" }
quests[552] = { id = 552, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helcular's Revenge", description = "Master Helcular was almost complete with his transformation into a Lich when a human lynch mob discovered his ritual lair in the hills and brutally killed him.  To make matters worse they buried his corpse in the Southshore cemetery.\n\nSuch disregard for the great wizard is unacceptable.  As his apprentice I shall see to it that the rains of vengeance fall upon the town of Southshore.\n\nWe will need Helcular's Rod first.  Yeti overtook his ritual lair.  Undoubtedly one of the beasts has it.", sourceObjective = "Retrieve Helcular's Rod from the Yeti and bring it back to Novice Thaivand in Tarren Mill.", progress = "Have you recovered Helcular's Rod yet?  There are so many Yeti in this region, it will be very difficult to locate.  But we must have it in order to proceed.", completion = "You found it!  Most excellent, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[553] = { id = 553, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helcular's Revenge", description = "Here, take the Rod of Helcular. You will need it.\n\nHelcular fashioned 3 ceremonial pyres as part of his most powerful spell.  The Flame of Azel and the Flame of Veraz lie within the Foothill Caverns. The Flame of Uzel lies in a cave above the caverns, further north in the mountains.\n\nThe Rod of Helcular must be charged from each of the three flames. Once the ritual is complete, drive the rod into Helcular's grave in Southshore, the heavily guarded human town to the south.  Vengeance shall be ours!", sourceObjective = "Charge the Rod of Helcular with the powers of the Flame of Azel, Flame of Veraz and the Flame of Uzel.\n\nDrive the charged rod into Helcular's grave in Southshore.", progress = "Helcular's grave teems with a mystical energy.", completion = "A great rumbling emanates from the ground.", sourceObjectiveStatus = "unverified-source-field" }
quests[554] = { id = 554, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormpike's Deciphering", description = "Prospector Stormpike is a master of decryption and deciphering.  If you take the parchment you found to him, then with luck he can make sense of it.  Stormpike is currently studying in the Prospector headquarters in Ironforge.\n\nAnd when you see him tell him you spoke with me - I've been sending him quite a lot of business lately.", sourceObjective = "Take the Ensorcelled Parchment to Prospector Stormpike in Ironforge.", progress = "More interruptions?\n\nAh, this parchment is covered with a very intricate, finely woven spell.  I can untangle it, of course, but it's going to take time.  And time is very valuable to me...\n\nPerhaps I will just purchase it from you?", completion = "A wise decision.  I don't believe there is a scholar other than myself with the skills to translate this scroll.  And if its contents prove interesting, fear not.  I will send for you.", sourceObjectiveStatus = "unverified-source-field" }
quests[555] = { id = 555, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soothing Turtle Bisque", description = "If there's one thing you'll learn about Southshore it's that we have some of the best cuisine north of Stormwind!\n\nTake my secret recipe for Turtle Bisque, for example. I've known folks to travel from as far as Darkshire just to enjoy a bowl.  Speaking of which, I haven't been able to make any lately.  I used to head up past Dalaran to Lake Lordamere myself to hunt Snapjaws but it's just too dangerous now. If you bring me some Turtle Meat from the Snapjaws up north and Soothing Spices, I'll whip some up!", sourceObjective = "Bring 10 pieces of Turtle Meat and some Soothing Spices to Chef Jessen in Southshore.", progress = "Any luck finding the ingredients?  I'll tell you, this territory isn't the peaceful place it once was.  Ah, if only this unrest never occurred. . .", completion = "Everyone will be so pleased: Chef Jessen's Soothing Turtle Bisque is served once again!", sourceObjectiveStatus = "unverified-source-field" }
quests[556] = { id = 556, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stone Tokens", description = "A notable talent of the wizards of Dalaran is their familiarity with elementals: powerful creatures from other dimensions.  The wizards use magical tokens as a means to control these elementals.  Magus Voidglare would like some of these tokens to study.\n\nEnter the territories of the Dalaran wizards, west of Hillsbrad, and gather the tokens.\n\nYou might find the tokens on any citizen of Dalaran, but I suggest hunting at the internment camp.  It's safer than Dalaran itself.", sourceObjective = "Bring 10 Worn Stone Tokens to Keeper Bel'varil in Tarren Mill.", progress = "Do you have the Worn Stone Tokens, {name}?  The Magus is eager to unlock their secrets.", completion = "These will do nicely.  Although it looks like their magic is faded, it would be best if the Magus' initial experiments were on inert specimens such as these.\n\nThank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[557] = { id = 557, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bracers of Binding", description = "The Magus will be busy studying those stone tokens you gathered, but I know he'll eventually want examples of their counterpart: bracers of binding.  These are set around the wrists of actual elementals, and bind them into the mage's service.\n\nHunt elementals in the ruins of Dalaran and gather their Bracers of Earth Binding, and the Magus will be pleased.", sourceObjective = "Bring 4 Bracers of Earth Binding to Keeper Bel'varil in Tarren Mill.", progress = "Hello, {name}.  Elementals are tough quarry, but I know you're up to the task.  Do you have those bracers of binding?", completion = "You found them.  I trust the elementals from which you removed these bracers were amenable?\n\nHm...death has not only stopped my heart, but robbed me of my comedic timing, it seems.\n\nWell thank you, {name}.  You serve the Magus, and hence the Dark Lady, well.", sourceObjectiveStatus = "unverified-source-field" }
quests[558] = { id = 558, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jaina's Autograph", description = "They say that Lady Jaina Proudmoore in Theramore is one of the greatest heroes the Alliance has ever had.  When I grow up, I wanna be a hero of the Alliance too!\n\nDo you know Jaina, {name}?  Could you do me a favor, please?  Could you get her autograph for me?  I dunno how to ask her, and she'd probably be too busy for someone like me... but you!  You're an adventurer just like she is!  I bet she'd give you her autograph easy!\n\nPlease?", sourceObjective = "Travel to Theramore to see about getting Lady Jaina Proudmoore's autograph for your ward.", progress = "Someday, I wanna be a hero just like Jaina... well, a boy hero that is.", completion = "WOW!  You got Lady Jaina's autograph for me!  Thank you very much!  And wow... she wrote a personal message on here - to me!  I knew she'd be totally cool, and maybe someday I'll thank her myself... when I become a hero of the Alliance!\n\nYou're the best, {name}.  Thank you for being so nice to me.", sourceObjectiveStatus = "unverified-source-field" }
quests[559] = { id = 559, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Farren's Proof", description = "Would you believe it, {name}? Redpath wasn't satisfied with all the murlocs we killed--oh now, don't be modest, you had some hand in it. Now he wants me to bring proof of the dead, hacking off cold, slimy murloc heads to submit for his approval.", sourceObjective = "Collect 10 Murloc Heads from the murlocs on the Western Strand for Lieutenant Farren Orinelle in Southshore.", progress = "Did you get those heads for me, {name}?", completion = "Oh for the Love of the Light... they're dripping on the ground.\n\nCan't stand touching those things, myself. Fish are all well and good, but when they grow legs and start walking around... Haven't eaten a fish in weeks, let me tell you, and in Southshore, that means you aren't eating much.", sourceObjectiveStatus = "unverified-source-field" }
quests[560] = { id = 560, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Farren's Proof", description = "You know, {name}, I'd really rather not take these heads... Since you've already got a handle on them, would you mind delivering them to Redpath for me?", sourceObjective = "Deliver the sack of murloc heads to Marshall Redpath in Southshore.", progress = "Greetings, citizen. Have you come to lend your arm to upholding the safety of Southshore?", completion = "Farren's errand boy, are you?\n\nIf you assisted Farren in procuring these heads, then thank you. Southshore needs hard workers and effort to maintain its protection.", sourceObjectiveStatus = "unverified-source-field" }
quests[561] = { id = 561, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Farren's Proof", description = "Please inform Lieutenant Orinelle that I would like him to refocus his efforts on the naga infesting the Eastern Strand. When he has results, tell him to report to me in person.", sourceObjective = "Speak with Lieutenant Farren Orinelle in Southshore.", completion = "The naga, eh? Redpath must have just received the same information as me... Ha! He'll not receive a promotion from my toil. Let me explain.", sourceObjectiveStatus = "unverified-source-field" }
quests[562] = { id = 562, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormwind Ho!", description = "My former mentor in the Stormwind city guard sent a message to me that Alliance High Command is becoming concerned with the threat posed by the naga. From what he's heard, there's good chances for promotion--or at least reassignment--for anyone who proves valuable in this regard.\n\nThere's just one small problem... I can't handle the naga, {name}. Oh sure, I could break up a drunken barroom brawl, or haul off a belligerent beggar, but the naga are too much for me. You've got to help me, {name}!", sourceObjective = "Kill 10 Daggerspine Shorehunters and 10 Daggerspine Sirens for Lieutenant Farren Orinelle in Southshore.", progress = "I've a letter ready to go to Major Samuelson in Stormwind. All I need are the results.", completion = "With the naga put down in Southshore, I'll be a shoe-in to be reassigned. I'll get to see Stormwind again... get away from this Light-forsaken port.", sourceObjectiveStatus = "unverified-source-field" }
quests[563] = { id = 563, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reassignment", description = "It shouldn't be a problem getting my report seen. The new captain of the guard, Major Samuelson, was my mentor while I was stationed in Stormwind. It should give him more than enough excuse to have me transferred back to the city. I'll need you to carry my report to him, though... wouldn't want ol' Redpath to catch on.", sourceObjective = "Deliver Farren's report to Major Samuelson in Stormwind Keep.", progress = "Greetings, citizen. May the Stormwind city guard be of assistance?", completion = "What's this? Ah... so my attentive pupil has applied himself to the problem of the naga in Southshore. Thank you for bringing this to me, I will certainly take it into account when I review personnel assignments in the next month.", sourceObjectiveStatus = "unverified-source-field" }
quests[564] = { id = 564, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Costly Menace", description = "Ain't nothin' that irks me more than losin' these here beautiful horses.  And believe me, we've lost quite a few between them pesky undead creeps, the dang Syndicate gang and all the other good-for-nothin' scoundrels pokin' about these parts.\n\nBut I swear on my ol' grand-daddy's grave there ain't no bigger menace to our horses here than them Mountain Lions up in Alterac.  Always comin' down from the hills and makin' my life difficult!\n\nYou fancy yourself a hero?  Go and do somethin' about it then!", sourceObjective = "Darren Malvew of Southshore wants you to kill 8 Mountain Lions and 10 Hulking Mountain Lions.", completion = "Ain't that great news!  Should-a gone and found me a regular ol' war hero from day one to take care of them beasts.  You'd-a made your pappy proud, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[565] = { id = 565, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bartolo's Yeti Fur Cloak", description = "I, the great Bartolo, shall make for you the world famous, Alliance renowned, Yeti Fur Cloak!\n\nTravel the planet and find yourself a better cloak, I dare you.  Oh wait, what is that, little {race}?  \"Bartolo, there is no finer cloak!\"  Yes, yes!  That, I have heard before.\n\nBartolo requires a Bolt of Wool, a Hillman's Cloak made by a skilled leatherworker, Fine Thread and Yeti Fur, of course!  Bring to me these items and you shall be a happy customer!", sourceObjective = "Bring Bartolo Ginsetti of Southshore a Bolt of Wool, a Hillman's Cloak, Fine Thread and 10 clumps of Yeti Fur.", progress = "So you have returned to the great Bartolo.  Perhaps you have finished gathering the materials needed for your Yeti Fur Cloak?  Or maybe you just enjoy basking in the greatness of me, Bartolo!", completion = "Now it is time for the great Bartolo to work his magic!  I require no wizard's staff, no mage's rod.  For I, the great Bartolo, work magic with a mere needle and thread!", sourceObjectiveStatus = "unverified-source-field" }
quests[566] = { id = 566, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Baron Vardus", description = "By order of High Executor Darthalia, the human known as Baron Vardus is wanted for crimes against the Forsaken. Vardus is known to be a high-ranking member of the organization known as the Syndicate.\n\nHe was last spotted in the Uplands in the Alterac Mountains, north of Tarren Mill.\n\nHe is wanted dead. Bring evidence of his demise to High Executor Darthalia to claim the reward.", sourceObjective = "Kill Baron Vardus and deliver his head to High Executor Darthalia in Tarren Mill.", progress = "Ah, {name}. Perhaps you've come to collect the bounty on the head of Baron Vardus?", completion = "Productive work you do, {name}. With Baron Vardus dead, the number of Syndicate leaders grows smaller. Their resistance and irritation will be short-lived.", sourceObjectiveStatus = "unverified-source-field" }
quests[567] = { id = 567, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dangerous!", description = "Dangerous!\n\nThe following humans of Hillsbrad have been deemed dangerous and are marked for bounty by High Executor Darthalia:\n\nClerk Horrace Whitesteed.  Wanted for the murder of Deathguard Toma.\n\nCitizen Wilkes.  Wanted for the murder of Apothecary Eli.\n\nMiner Hackett.  Wanted for the murder of Deathstalker Fry.\n\nFarmer Kalaba.  Wanted for the ambush of supplies from the Undercity.\n\nAll of these enemies are hiding and will be hard to find.  A reward will be granted upon notice of their death.", sourceObjective = "High Executor Darthalia of Tarren Mill is offering a bounty on Clerk Horrace Whitesteed, Citizen Wilkes, Miner Hackett and Farmer Kalaba.", progress = "Yes?", completion = "You are quite the bounty hunter, {class}.  Well done.", sourceObjectiveStatus = "unverified-source-field" }
quests[568] = { id = 568, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Defense of Grom'gol", description = "Throm'ka, {class}!\n\nYour arrival at Grom'gol is timely, indeed.  As commander of the Warchief's base camp here in the jungle I am bound by honor to ensure the safety of all members of the Horde.  Our mission to provide a safe chain of supply to Stonard is being hampered by some of the local inhabitants.\n\nI am putting you in charge of thinning out the raptor population outside of Grom'gol.  Once you have made significant progress, report back to me for reassignment.", sourceObjective = "Commander Aggro'gosh of the Grom'gol base camp wants you to kill 15 Lashtail Raptors.", progress = "Our supply efforts are still being hampered by the indigenous raptor population, {class}.", completion = "Your duty was performed with honor, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[569] = { id = 569, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Defense of Grom'gol", description = "When we first arrived in this jungle we did not intend to wage war on the local tribes.  Our mission to supply Stonard is of the highest priority.  But complications have arisen.  A local band of ogres has occupied the Mizjah Ruins to the southeast of Grom'gol.  Despite warnings, they continue to ambush our supply caravans.\n\nI am putting you in charge of dealing with these uncooperative ogres.\n\nTravel to the ruins and attempt to drive them from the area.  At the very least it will send a firm message.", sourceObjective = "Commander Aggro'gosh of the Grom'gol base camp wants you to kill 10 Ogre Brutes and 5 Ogre Witch Doctors.", progress = "Have you made any progress with the ogres of the Mizjah Ruins yet, {class}?", completion = "Well done.  You have served the Warchief with honor.", sourceObjectiveStatus = "unverified-source-field" }
quests[570] = { id = 570, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mok'thardin's Enchantment", description = "The power of the jungle's magic must be realized and then harnessed by the Horde.  My rituals have proven successful so far.  I can cast very powerful enchantments.  For you, brave {class}, I shall make a special item indeed.\n\nBring to me some Shadowmaw Panther claws along with a Tigress fang.  Not just any fang will do.  It must be in pristine condition.\n\nThe beasts lurk throughout the jungle but you will find some close by, just across the river from Mizjah Ruins to the southeast.", sourceObjective = "Far Seer Mok'thardin at the Grom'gol base camp wants 8 Shadowmaw Claws and a Pristine Tigress Fang.", progress = "What news do you bring?", completion = "Your knowledge of the jungle is strong, {name}.  These specimens will be perfect.  I will thank the spirits for sacrificing such fine beasts for the cause of the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[571] = { id = 571, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mok'thardin's Enchantment", description = "What I need from you now will be very difficult to obtain.\n\nTo hold all these feathers, claws and the pristine fang in place I require a magical tether.  Only an aged gorilla sinew will work.\n\nYou will only be able to find one on an Elder Mistvale Gorilla.  They are known to forage to the east of Booty Bay.\n\nThe sinew must be perfect.  It might take quite a few kills for you to find exactly what I need but it will be well worth the hunt.", sourceObjective = "Bring an Aged Gorilla Sinew to Far Seer Mok'thardin in Grom'gol.", progress = "Has fortune been on your side, {name}?  Were you able to obtain an aged gorilla sinew?", completion = "A most ideal sinew, {name}.  Your efforts will pay off soon.", sourceObjectiveStatus = "unverified-source-field" }
quests[572] = { id = 572, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mok'thardin's Enchantment", description = "The items you gathered from the feline beasts of the Vale are only the first requirement for a powerful enchanted item.  These jungle trinkets combined with my shamanistic ritual will provide you with a very useful tool in assisting the Horde and the Warchief.\n\nBut now you must gather for me some Jungle Stalker Feathers.  The feathers are traditionally worn by the beasts on their armbands.  You will find a tribe of the raptors directly south of Grom'gol, not far from the great arena.", sourceObjective = "Bring 10 Jungle Stalker Feathers to Far Seer Mok'thardin at the Grom'gol base camp.", progress = "Did your gathering efforts prove fruitful?", completion = "Most excellent.  I will prepare these at once.", sourceObjectiveStatus = "unverified-source-field" }
quests[573] = { id = 573, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mok'thardin's Enchantment", description = "There is but one final reagent needed to complete the enchantment.\n\nIn the south, towards the western coast, high above the bluffs, lies a Holy Spring.  This spring is the subject of great conflict amongst religious and mystical scholars.  Every race in Azeroth claims that the spring waters were made divine for their people.\n\nMy final request of you: bring to me Holy Spring Water.  Be warned.  An expedition of naga explorers have advanced upon the spring.  They will need to be dealt with as well.", sourceObjective = "Far Seer Mok'thardin of Grom'gol needs Holy Spring Water. He also wants you to kill 10 Naga Explorers.", progress = "I am almost ready to complete the enchantment.  Have you performed my bidding?", completion = "With this Holy Spring Water the ceremonial choker is ready for enchantment.\n\nWear this with pride, {name}, in the name of the Warchief and in defense of the mighty Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[574] = { id = 574, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Special Forces", description = "Now that many of his regular troops are reduced, you must face his highly trained forces.  When they're not in the wilderness slaughtering our rebel soldiers, they are found deep in the back of the Kurzen Compound, in a cave they call the Stockpile.\n\nI know many of Kurzen's troops personally, and I know they are skilled, loyal, and cruel.  This is no easy task I set before you, {name}.\n\nAfter you defeat them, report to Lieutenant Doren, my commanding officer.  He will want your report firsthand.", sourceObjective = "Kill 10 Kurzen Commandoes and 6 Kurzen Headshrinkers.\n\nReport to Lieutenant Doren at the Rebel Camp.", progress = "Sergeant Yohwa tells me you are skilled and brave, {class}.  Do you have something to report?", completion = "{name}.  Sergeant Yohwa trusted your abilities, and I trust her.  The defeat you brought to Kurzen's forces is almost too much to hope for.  I had feared we rebels were alone, and alone we could never stand up against the Colonel's brilliance.\n\nPerhaps hope of our survival yet remains.", sourceObjectiveStatus = "unverified-source-field" }
quests[575] = { id = 575, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supply and Demand", description = "\"The finest leathercrafter of the South Seas and the worlds old and new.\" That's what they call me. Me! Drizzlik! The finest lea... Ahem. Well.\n\nMy leather goods are known far and wide as the most exquisite, a connoisseur's choice!\n\nI've just received an order from Director Riddlevox of the Tinkers' Union for a dozen of his favorite Excelsior-line boots. Our best sellers, actually.\n\nTo start on the basic shape, I'll need crocolisk skins from the crocs along the river in northern Stranglethorn.", sourceObjective = "Bring 2 Large River Crocolisk Skins to Drizzlik in Booty Bay.", progress = "My equipment is all ready to go, {name}, I just need those skins. We don't want to keep Riddlevox waiting, that's for sure.\n\nIt's not a good idea for anyone to keep the chief inventor of the Tinkers' Union unsatisfied.", completion = "These skins should do. Their quality isn't too important, given that they'll make up the inside layer of the boots, but it's still important that they're comfortable.\n\nIf they're a bit too rigid, I'll use some tiger blood to soften it up. Tricks o' the trade, you know?", sourceObjectiveStatus = "unverified-source-field" }
quests[576] = { id = 576, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keep An Eye Out", description = "Avast!  Who goes there?\n\nArgh, I am but useless without me special enchanted eye.  Bad enough to have lost me eyes in battle in the first place!  But by some stroke o' luck we docked in Menethil and a traveling wizard enchanted a special glass eye that let me see again.\n\nLast night I ended up gettin' jumped by some Bloodsail Buccaneers on me way out.  Took me eye, they did!  Seems those blokes have found their way to Booty Bay.\n\nHelp an old sea dog out by gettin' me eye back?", sourceObjective = "Dizzy One-Eye in Booty Bay wants you to retrieve his eye from the Bloodsail Buccaneers.", progress = "Ahoy, me bucko!  Might not be able to see but I can smell ye from halfway across port.\n\nCould really use me eye back.  Captain's going to keelhaul me when he finds out me peeper is in the hands of them dirty Bloodsail Buccaneers.\n\nWhat good is a lookout who can't see?  The crow's nest used to be me home...without me deadlights I'd be lucky to scrub the bilge.", completion = "Shiver me timbers and timber me shivers!  Ye found me beautiful eye!  Let's see if she still fits.\n\n{name} ho!  Blimey, I can see!!", sourceObjectiveStatus = "unverified-source-field" }
quests[577] = { id = 577, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Some Assembly Required", description = "Well, I've got the basic shape of the boots worked out, and they're coming along fine, but the skins you brought aren't going to be quite enough for the inner layers.\n\n\"What are we going to do, Drizzlik?\" No doubt the question on your lips, and well, isn't it lucky you're talking to Drizzlik, because he's going to tell you what we're going to do!\n\nThe inner layers will never really be seen, so we'll just get some of the thicker, cheaper skins from the crocs around Lake Nazferiti to fill the boots out.", sourceObjective = "Bring 5 Snapjaw Crocolisks Skins to Drizzlik in Booty Bay.", progress = "Drizzlik's Excelsior leather boots, finest workmanship, one-hundred percent high quality saltwater crocolisk skin boots. None finer!\n\nCan't beat a glowing description like that, can you?\n\nExcept, maybe, if you have those skins for me?", completion = "My boots... they're like sausages, {name}. Look great, taste great. I tell you they're filled with nothing but the finest ingredients and meats, and you eat it, and you love it.\n\nIt's safer--and more enjoyable--if you just trust me, and don't ask too carefully what's really inside.", sourceObjectiveStatus = "unverified-source-field" }
quests[578] = { id = 578, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Stone of the Tides", description = "If there is indeed a goblin mage and water elementals haunting the island, it could mean the Stone of the Tides can be mine!\n\nI want you to locate this haunted island... find out what's going on. Oh, and if you perhaps want to find out more about the Stone of the Tides, take this scrip to the Stormwind Library, they should be able to find you a copy of the book I first came across the legend in.\n\nCould it be that Gazban actually discovered the Stone...?", sourceObjective = "Find the haunted island for Baron Revilgaz in Booty Bay.", completion = "So the stories were true! Incredible!\n\nHowever, we will need to figure out a way to defeat the curse of the Stone of the Tides, if we are to retrieve it. The curse is magical business, we'll need one of those wizards to help us out.", sourceObjectiveStatus = "unverified-source-field" }
quests[579] = { id = 579, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormwind Library", progress = "King Anduin has placed great importance on learning, and thus has provided funds for making copies of various tomes and writings available to the public. It's very simple. You bring me a library scrip, and I can give you a copy of one of the available books.", completion = "Do any of these titles interest you, {name}?" }
quests[580] = { id = 580, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whiskey Slim's Lost Grog", description = "We was splicin' the mainbrace somethin' fierce off of the Overlook Cliffs, ol' Hinterlands just in the distance.  Thought the seas was goin' to swallow us whole.\n\nOl' Slim knows all about liquid courage!  Cap'n had a crate of Pupellyverbos Port we commandeered from a privateer en route to Stormwind.\n\nSo when that storm off of Hinterlands hit, I busted into the grog.  Big wave hit and tossed them bottles overboard.  Cap'n is goin' to give me a taste o' the cat if ye don't help me get 'em back though!", sourceObjective = "Whiskey Slim in Booty Bay wants you to bring him the bottles of Pupellyverbos Port he lost.", progress = "Sink me!  I'm almost outta booze here!  Cap'n is goin' to weigh anchor and Ol' Slim will be caught dry as the Tanaris Desert.  And once he discovers his port is missing. . . blimey!", completion = "Shiver me timbers!  Ye found the Cap'n's grog!\n\nI owe ye big time, friend.\n\nSeems like a storm is a brewin' outside.  Maybe I'll just keep warm with one o' these here bottles while we wait for it to pass....", sourceObjectiveStatus = "unverified-source-field" }
quests[581] = { id = 581, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunt for Yenniku", description = "A doom, there is.  A doom on my chief's youngest son, Yenniku.  As is a custom with our people, he was given to the Gurubashi Trolls of Zul'Gurub, but after my tribe, the Darkspear tribe, left with the orc Thrall, poor Yenniku was lost to us.  I was sent from distant Orgrimmar, back to Stranglethorn, to search for my chief's son.\n\nAnd I believe the Bloodscalp tribe has him.\n\nIf you would help me, then hunt the Bloodscalps.  You may find them to the north.  Gather their tusks and return to me.", sourceObjective = "Bring 9 Bloodscalp Tusks to Nimboya at the Grom'gol Base Camp.", progress = "{class}.  Show me you have made prey of the Bloodscalp tribe.\n\nShow me your trophies.", completion = "These are good tusks, {name}.  You prove that you have the strength to hunt the Bloodscalps.\n\nAnd that is good, because you are not done hunting them.", sourceObjectiveStatus = "unverified-source-field" }
quests[582] = { id = 582, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Headhunting", description = "We must find if Yenniku is dead.\n\nSlay the Bloodscalp Headhunters and take from them their Shrunken Heads.  You must gather many, many heads, and I will inspect them to make sure Yenniku's head is not among them.\n\nAnd if Yenniku was killed by the Bloodscalps, then may a 600-year curse fall on the spirit of their chief, Gan'zulah!\n\nGo, {name}.  You may find many Headhunters at the ruins of Zuuldaia and Zul'Kunda, along the coast to the north.", sourceObjective = "Bring 20 Shrunken Heads to Nimboya at the Grom'gol Base Camp.", progress = "{name}.  I fear for our chief's son.  Do you have the shrunken heads so I may inspect them?", completion = "Thank you, {name}.  I will inspect these heads to ensure poor Yenniku was spared the headhunter's axe.", sourceObjectiveStatus = "unverified-source-field" }
quests[583] = { id = 583, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome to the Jungle", description = "Welcome to Stranglethorn!\n\nPerhaps you're not aware of this, but that dwarf over there is the son of the one and only Hemet Nesingwary, renowned war hero of the Alliance and master big game hunter.  Like his father, he's not one for welcoming strangers into his camp, but you look like you've seen quite a bit of action in your day, {class}.\n\nGo and speak with him.  He's a chip off the old block, so perhaps he can give you some hunting pointers.", sourceObjective = "Speak with Hemet Nesingwary Jr.", completion = "Jolly nice to make your acquaintance, {name}. Haven't seen a {class} around these parts for some time.\n\nI situated myself with this expedition for one purpose: to hunt a great and elusive beast. Seeing that you're a hero of sorts I am willing to let you take part in the hunt, but you must first prove yourself.\n\nI shall teach the ways of raptor killing to you. Ajeck will train you with tiger hunting. And Sir Erlgadin is a master of panther tracking.\n\nProve your skill and I'll let you in on the big hunt.", sourceObjectiveStatus = "unverified-source-field" }
quests[584] = { id = 584, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloodscalp Clan Heads", description = "Yenniku was not among the heads, and I thank the Great Serpent for it.  But we are no closer to finding him.\n\nWe must know the truth, and I fear that only the Bloodscalp chief and his witchdoctor know it.  They are the enemies of the Darkspear tribe and will not speak freely, so we must force the truth from their dead lips!\n\nBring me the heads of Gan'zulah and Nezzliok the Dire and place them within this cauldron.\n\nThey are deep within Zul'Kunda.  Bring their heads...we will then make them talk.", sourceObjective = "Bring Gan'zulah's Head and Nezzliok's Head to the bubbling cauldron at the Grom'gol Base Camp.", progress = "The greenish broth within the cauldron bubbles.", completion = "You place the heads of Gan'zulah and Nezzliok within the cauldron...", sourceObjectiveStatus = "unverified-source-field" }
quests[585] = { id = 585, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speaking with Nezzliok", description = "<The head of Nezzliok speaks.>\n\nIt is true.  I know where the child of the Darkspears was taken.  You have bested me and bound my spirit, but I will say nothing without appeasement!\n\nThe Bloodscalps war with the Skullsplitters.  To gain my favor, steal from the Skullsplitters 3 of their trophy skulls and place them here with us, so that my spirit will have slaves in the Nether.  One skull must be from their trophy pile in Balia'mah, another from Ziata'jai, and the last from Zul'Mamwe.", sourceObjective = "Bring a Balia'mah Trophy, a Ziata'jai Trophy and a Zul'Mamwe Trophy to the Bubbling Cauldron at the Grom'gol Base Camp.", progress = "I await the skulls...", completion = "Yes.  These will serve me well.  When my spirit is freed, I will enter the Nether with three fine servants!\n\nYou are a credit to your {race} clan, and you have appeased me.", sourceObjectiveStatus = "unverified-source-field" }
quests[586] = { id = 586, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speaking with Gan'zulah", description = "<The head of Gan'zulah speaks.>\n\nCurse you!  And curse your ancestors!!\n\nOnly blood and revenge can cool my rage, so if that is your wish, then... do this:\n\nThrow yourself into the heart of the Skullsplitters to the east.  Slay the fiercest among them, and if you survive...then break yourself against their chief, Ana'thek the Cruel.  Hah!  Bring me his shattered armor if you can!\n\nMay he tear off your limbs and leave you to rot and be eaten by carrion.", sourceObjective = "Kill 8 Skullsplitter Hunters, 6 Skullsplitter Headhunters, and 4 Skullsplitter Berserkers.\n\nBring the Broken Armor of Ana'thek to the Bubbling Cauldron at the Grom'gol Base Camp.", progress = "Although my own flesh boils off my skull, I can still smell your fear.\n\nHah!  You will never complete my task...", completion = "I do not want to believe it, but I cannot deny what you have done.  And my rage eases, now that Ana'thek is defeated.  \n\nYour might will drive you to great deeds, {name}.  But one day...I will see you in the Nether and we will again match strength.\n\nI will be waiting.", sourceObjectiveStatus = "unverified-source-field" }
quests[587] = { id = 587, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Up to Snuff", description = "Ah, the sea life.  I ain't gonna say it's the good life, but it's my life.\n\nWhen I get into port I like to find me a good bottle of grog and some high quality snuff.  Nasty habits but what's a pirate without his vices, right?\n\nSo you can imagine how heartbroken I was to find out the herbalist here in town has gone and sold out of the stuff.  Says his shipment got hijacked by those damned Bloodsail Raiders.\n\nI bet a fearless {class} like you could convince 'em to share the goods, eh?", sourceObjective = "Deeg in Booty Bay wants you to bring him 15 shares of Snuff.", progress = "Any luck finding the goods, matey?", completion = "Good show, {name}!  And just before I need to ship out too!  Can't thank you enough, old friend.", sourceObjectiveStatus = "unverified-source-field" }
quests[588] = { id = 588, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fate of Yenniku", description = "<Nezzliok speaks.>\n\nYou have appeased myself and my chief, so I will tell you that which you seek to discover...\n\nYoung Yenniku is lost to his clan.\n\nHe was taken by the witchdoctor Zanzil the Outcast.  Now Zanzil controls him, body and soul, and only the most potent magic could set him free.\n\nA magic that you do not have, {class}.\n\nPerhaps your Darkspear allies can offer a hope of Yenniku's salvation.  But that, I doubt.", sourceObjective = "Speak with Kin'weelay.", completion = "Zanzil the Outcast??\n\nIf Yenniku is held by that troll, a vile and powerful witchdoctor, then I fear that only a faint hope remains.  Faint.  And tiny as the smallest insect.\n\nBut still, it is hope.", sourceObjectiveStatus = "unverified-source-field" }
quests[589] = { id = 589, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Singing Crystals", description = "Legends tell of a jewel, hidden deep in the heart of Stranglethorn.  We call it the Mind's Eye, and it has great powers.  If you gain this Eye then, perhaps, we can use it to bring lost Yenniku back from the darkness.\n\nI will consult with the spirits of the jungle to find the Mind's Eye.  While I do this, you enter the Crystalvein Mine, southeast of here, and gather Pulsing Blue Shards from Ironjaw Basilisks.  The shards are rare, but we will need their magic to bend the Mind's Eye to our will.", sourceObjective = "Bring 3 Pulsing Blue Shards to Kin'weelay at the Grom'gol Base Camp.", progress = "Do you have the shards, {name}?  They are needed for my final ritual, after we have the Mind's Eye.", completion = "You have done well, {name}.  These shards are well formed.  Already I hear them sing to me.\n\nAnd while you were gone, I spoke with the spirits of the jungle.  I know where the Mind's Eye rests...\n\n...And who guards it.", sourceObjectiveStatus = "unverified-source-field" }
quests[590] = { id = 590, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Rogue's Deal", description = "What?\n\nWhat?!\n\nYou want money? I don't owe you any money.\n\nLetter? What letter? Oh, you wanna fight then? All right, mate... let's do this! Owe you any money...", sourceObjective = "Defeat Calvin Montague in Deathknell.", progress = "Not bad, mate... not bad at all.", completion = "Incredible! What skill!\n\nThought you'd be easy prey, {name}. Got me good, you did.\n\nHere's the coin I promised... not as much as I said it'd be, but that's on a count o' me lying to ya in the first place.", sourceObjectiveStatus = "unverified-source-field" }
quests[591] = { id = 591, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mind's Eye", description = "The Mind's Eye is held by an ogre mage, east of here and deep within the Mosh'Ogg ogre mound.  His name is Mai'Zoth.  I know him from when the Darkspears dwelt in Stranglethorn - he is vicious, and his magic is strong.\n\nAnd if he has the Mind's Eye, then his magic will be stronger still.\n\nYou must face Mai'Zoth and wrest from him the Mind's Eye.  It is a perilous task, but it is the only hope we have of saving Yenniku.", sourceObjective = "Bring the Mind's Eye to Kin'weelay at the Grom'gol Base Camp.", progress = "Greetings, {name}.  The spirits sing praise of your bravery, yet they tell me no tales of your quest against Mai'Zoth.\n\nDo you have the Eye?", completion = "You retrieved the eye!  Your might is the stuff of legends, {name}!\n\nAnd in getting the Eye, you must have defeated Mai'Zoth and sent him to the Nether.  That is why the spirits would not mention him before.\n\nIt is good that he is gone from the world of flesh and bone, but now that he is in the realm of spirits...I fear he will begin a new reign.\n\nBut that is a worry for another time.  Now, I must perform a ritual to bend the Mind's Eye to our needs...", sourceObjectiveStatus = "unverified-source-field" }
quests[592] = { id = 592, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saving Yenniku", description = "I have reshaped the Mind's Eye into a Soul Gem.  Its purpose is twofold: you must use it to stun Yenniku, and once stunned place it upon his head to entrap his soul.\n\nThen, bring the gem to Nimboya.\n\nYenniku dwells with Zanzil the Outcast, at the Ruins of Aboraz, along the Crystal Shore on the distant Cape of Stranglethorn.", sourceObjective = "Bring the Filled Soul Gem to Nimboya.", progress = "{name}.  Kin'weelay told me you set out to capture Yenniku.\n\nIs it true?  Do you have him?", completion = "You've done it!  You freed Yenniku from the will of Zanzil, and completed the mission I had thought was so desperate.\n\nOur tribe will remember your name in songs, {name}, and we will etch your tale in stone so that it will live forever.", sourceObjectiveStatus = "unverified-source-field" }
quests[593] = { id = 593, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Filling the Soul Gem", progress = "Yenniku stands stunned before you, his mind in another place...", completion = "You place the Soul Gem upon his forehead.  He shudders as his soul is sucked in, leaving his body, a mindless husk, behind." }
quests[594] = { id = 594, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Message in a Bottle", description = "The note reads, in fairly good handwriting:\n\nTo any that can aid me-\n\nPlease, my need for help is dire. A great Skymane holds me captive on an island in the South Seas.\n\nThe stars at night are foreign to me and obscured by the jungle trees, but on the clearest days I see Wild Shore to the northwest, and what seem to be large sailing ships to the southwest.\n\nI beg of you, my would-be savior, please help me.", sourceObjective = "Find the author of the message in a bottle.", completion = "Have you come to free me?", sourceObjectiveStatus = "unverified-source-field" }
quests[595] = { id = 595, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bloodsail Buccaneers", description = "You sure seem eager to work, matey.  Not sure why some land-loving {race} {class} is offering help to the Blackwater Raiders, but I'm not going to turn you away.\n\nOur ship just docked here in Booty Bay and word has it that our rivals--those damned, dirty Bloodsail Buccaneers--have been spotted all over southern Stranglethorn.\n\nAll the boys are too busy hitting the grog and looking for ladies!  What I need is a scout.\n\nCheck the cove just north of Booty Bay along the Savage Coast and see what you find.", sourceObjective = "First Mate Crazz wants you to check the cove north of Booty Bay.", completion = "On top of the barrel, you discover a map with some hastily written text on it along with some coins.", sourceObjectiveStatus = "unverified-source-field" }
quests[596] = { id = 596, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloody Bone Necklaces", description = "I was sent to Grom'gol  to aid Nimboya on his quest, but... I too have reasons for being here.\n\nThe Bloodscalp tribe is enemy to our tribe.  Collecting trophies of our enemies gives us power over them.  You may aid our tribe by hunting our enemies.\n\nThey dwell to the north.  Slay Bloodscalp trolls and take from them their bloody bone necklaces.  Collect many, and your reward will be great.", sourceObjective = "Bring 25 Bloody Bone Necklaces to Kin'weelay at the Grom'gol Base Camp.", progress = "The Bloodscalps will one day be crushed by the Darkspears!  Do you have the necklaces of our doomed foe?", completion = "Ah, very good.  I will boil these, and leech them, and the spirits of their owners will weaken as I render their necklaces to paste!\n\nHere, {name}.  This will repay my debt to you.", sourceObjectiveStatus = "unverified-source-field" }
quests[597] = { id = 597, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bloodsail Buccaneers", description = "The map shows Booty Bay with a red \"X\" drawn precisely at the spot at which you are standing.\n\nThe scribbled text reads:\n\n\"You men are to secure a camp at this location and keep quiet.  Wait for the signal from the southern command post before attacking.  If anyone approaches you, kill them.\"", sourceObjective = "Report your findings to First Mate Crazz in Booty Bay.", completion = "Sure, I remember you, {class}.  Back from scouting I see....", sourceObjectiveStatus = "unverified-source-field" }
quests[598] = { id = 598, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Split Bone Necklace", description = "Now that you have gathered Bloodscalp trophies, I have another task for you.  The Skullsplitter tribe of trolls live to the southeast, and for years we have warred with them.  Although the Darkspears no longer dwell in Stranglethorn, we are bound to our conflict with the Skullsplitters.\n\nSo, hunt them.  Gather their Split Bone Necklaces and return to me.  Aid us in our war, and you will earn the friendship of the Darkspears.", sourceObjective = "Bring 25 Split Bone Necklaces to Kin'weelay at the Grom'gol Base camp.", progress = "The Skullsplitters will curse the day they brought us to war!  Is your task complete?", completion = "Your strength is great to have gained these necklaces, {name}.  The Skullsplitters fall to you like young saplings stomped to earth by a Basilisk!\n\nYour deeds are a boon to us.", sourceObjectiveStatus = "unverified-source-field" }
quests[599] = { id = 599, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bloodsail Buccaneers", description = "Shiver me timbers!  So the Bloodsail Buccaneers are planning some sort of attack on Booty Bay?  Why, the nerve of those scoundrels.  Booty Bay will always be run by the Blackwater Raiders!\n\nThis is bigger than I thought.  Report what you have learned to Fleet Master Seahorn at once!  The ol' sea dog is around town somewhere....", sourceObjective = "Report the planned Bloodsail attack to Fleet Master Seahorn.", completion = "Bloodsail Buccaneers attacking Booty Bay?  They might as well throw themselves off the Overlook Cliffs.  Nonetheless, by bringing me this information you have done my fleet of swashbucklers a great service.  The Blackwater Raiders thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[600] = { id = 600, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Venture Company Mining", description = "The Venture Company has a string of operations through Stranglethorn which keeps hard-working goblins, like me, from making honest gold!  Please, you must help me!\n\nThe Venture Company is mining near the Crystalvein Mine to the north.  They can't get into the mine because of all the basilisks, but they're still able to dig up Singing Crystals from the surrounding hills.\n\nTake their crystals from them, and show them they don't have the run of the jungle.\n\nAnd... um... bring me those crystals as proof!", sourceObjective = "Bring 10 Singing Blue Crystals to Crank Fizzlebub in Booty Bay.", progress = "Do you have those crystals??  I need them!!\n\nI mean...I need to know the evil Venture Company is losing ground in Stranglethorn.  Because, you know, we honest folk have to make a living!", completion = "Great!  Wonderful!  I can get a bundle for these!!\n\nThat Venture Company sure picked the wrong jungle to mine in, didn't they?  We'd all be in better shape if they moved out of here.\n\nThank you, {name}.  You've done a good deed this day.", sourceObjectiveStatus = "unverified-source-field" }
quests[601] = { id = 601, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Water Elementals", description = "The water elementals were no doubt summoned by Gazban, the goblin wizard rumored to have discovered the Stone of the Tides. As you may know, the Stone of the Tides curses its bearer, causing him to fade in and out of existence...\n\nPerhaps we can find a way to counteract the curse. We can have a mage of Dalaran analyze the magical residue of one of the water elemental's bracers. I need you to go back to the island and retrieve a few specimens.", sourceObjective = "Acquire 6 Water Elemental Bracers for Baron Revilgaz in Booty Bay.", progress = "Have you had any luck, {name}?", completion = "Hm, I haven't the eye to examine these bracers to see if any of them will be of any use, but I'm sure at least one of them will be able to help. Take them to Dalaran and have a mage look at them.\n\nAfter all, I can't very well leave Booty Bay just to chat with those tiresome old mages.\n\nNot that I'm worried anyone would try to elbow their way into being the new baron. No one crosses Revilgaz and lives to tell of it.", sourceObjectiveStatus = "unverified-source-field" }
quests[602] = { id = 602, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magical Analysis", description = "From what I've heard, the mages of Dalaran are busy with the reconstruction of their destroyed city, I'm sure you can find one of them who will spare some time to look at the bracers. If there's anything I know about mages, they can't resist a magical puzzle.\n\nTake the bag of water elemental bracers and see if they can shed any light on the Stone's curse.  Look for the Archmage Ansirem Runeweaver in particular.  I've dealt with him before, and his knowledge is vast.", sourceObjective = "Bring the water elemental bracers to Archmage Ansirem Runeweaver in Dalaran.", progress = "If you wouldn't mind, I am rather busy right now.", completion = "The Stone of the Tides? Most interesting. It might surprise you to know that I wrote a tome--several years ago--pertaining to the legends of the Gurubashi Empire. I do know quite a bit about the Stone.\n\nAt least one of these bracers appears to have some magical residue I can analyze.\n\nLet's see what I can see...", sourceObjectiveStatus = "unverified-source-field" }
quests[603] = { id = 603, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ansirem's Key", description = "The mage that is in possession of the Stone is amplifying its power through some focal point... an altar of some sort. You should be able to disrupt it by overpowering it.\n\nAs it happens, I know just the thing: an ancient dagger, another troll relic. There's just one... little problem.\n\nYou see, I found the dagger while researching in Stranglethorn, but I gave it to my willful daughter, Catelyn, who ran off to Booty Bay to become a pirate.", sourceObjective = "Talk to Catelyn in Booty Bay.", completion = "My dagger? What are you, some sort of comedian?\n\nWhat? Do you just want me to repeat the story of how I've gone from the best knife fighter in Booty Bay to the laughing stock of piratedom!\n\nI lost a knife fight to one of the Bloodsail Buccaneers--bunch of right bastards they are!--and he took my blade as spoils.\n\nIt's not as though I can get by as a knife fighter with insults and a sharp tongue alone...", sourceObjectiveStatus = "unverified-source-field" }
quests[604] = { id = 604, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bloodsail Buccaneers", description = "Crazz speaks highly of your dedication to the Blackwater Raiders.  I am going to trust you with a mission of extreme importance to the fleet.\n\nInfiltrate the so-called southern command post the Bloodsail Buccaneers have established on the Wild Shore.  Raid the encampment.  Bring me their charts along with their written orders.  We shall see exactly what those scum are up to.", sourceObjective = "Fleet Master Seahorn in Booty Bay wants you to kill 10 Bloodsail Swashbucklers and bring back the Bloodsail Charts and the Bloodsail Orders.", progress = "Ahoy, {name}.  What word do you bring of the Bloodsail encampment to the south?", completion = "Perfect, {name}.  Now that we know their plan, it's just a matter of time.\n\nAnd to think the fools have dropped anchor just off the cape....", sourceObjectiveStatus = "unverified-source-field" }
quests[605] = { id = 605, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Singing Blue Shards", description = "The Singing Crystals are unique to Stranglethorn, and are very valuable to certain parties.  I can move those crystals, but the cursed Venture Company makes it hard for an honest entrepreneur like myself to gather any!\n\nI'd like to hire you.\n\nThe basilisks in Stranglethorn eat the crystal.  This gives them their hardened skin, and sometimes decent quality crystal can be harvested from it.\n\nYou can get it from any basilisk, but the less nasty ones are along the shores south of Zul'Kunda, to the north.", sourceObjective = "Bring 10 Singing Crystal Shards to Crank Fizzlebub.", progress = "Do you have those shards yet?  I'll give you a decent cut from the profits!", completion = "Aha!  These will do nicely, {name}.  Yes, quite nicely!\n\nHere is your cut, and...it was a pleasure doing business with you.", sourceObjectiveStatus = "unverified-source-field" }
quests[606] = { id = 606, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scaring Shaky", description = "If there's one thing I can't stand, it's people who don't pay their gambling debts!  And there are a lot of people who owe me. Think you can help me collect?\n\nFirst, there's \"Shaky\" Phillipe down by the docks.  He owes me plenty after last week's game and I want my due!  But to get it, we'll have to scare him.\n\nGo out of town and hunt Elder Mistvale Gorillas.  Find a nice selection of giblets, then take them to Shaky.  Don't let on that they're from an animal; let him think the worst.", sourceObjective = "Bring 5 Mistvale Giblets to \"Shaky\" Phillipe in Booty Bay.", progress = "Hey!  I don't like the look you're giving me, mister.", completion = "Ack!  Where'd you get these?  No, don't tell me. I don't want to know!\n\nWho sent you?  Sea Wolf?", sourceObjectiveStatus = "unverified-source-field" }
quests[607] = { id = 607, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to MacKinley", description = "Here, take this pouch and give it to Sea Wolf.  And tell him I meant to pay him back!  I swear!!\n\nI just got a little drunk and lost my way, and...you know how things are.  He'll understand - you don't have to get rough!", sourceObjective = "Bring Shaky's Payment to \"Sea Wolf\" MacKinley.", progress = "Here here, {name}.  Did you get Shaky's payment?", completion = "Heh heh, well done!  And when you showed Shaky those giblets, how hard did he shake?\n\nHah!  He's so easy to read, when I play cards with him I can't help but win!\n\nThanks for your help, {name}.  Now it's your turn to get paid...", sourceObjectiveStatus = "unverified-source-field" }
quests[608] = { id = 608, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bloodsail Buccaneers", description = "Blast the nerve of Firallon!  He couldn't sail a skiff through Crystal Lake let alone lead an entire fleet against us.\n\nThe Bloodsail Buccaneers will pay for their carelessness.  Now that we know their plan of attack, we can counter before they know what hit them.\n\nBut why send the entire fleet to do the work of one brave adventuring party?  {name}, take some of your most skilled comrades out to Firallon's landing spot and assassinate the Bloodsail leadership.  Their fleet will sink soon after....", sourceObjective = "Fleet-Master Seahorn in Booty Bay wants you to kill Captain Stillwater, Captain Keelhaul and Fleet Master Firallon.", progress = "What's the problem, {name}?  We need to attack before the Bloodsail Buccaneers do!", completion = "Ah, what a great day for the Blackwater Raiders!  Three cheers to you, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[609] = { id = 609, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voodoo Dues", description = "My list is shortening, but there are still people who owe me.\n\nNext, we have Maury \"Club Foot\" Wilkins, Jon-Jon the Crow, and Chucky \"Ten Thumbs.\"\n\nThese scurvy dogs' debts are months outstanding and I thought they skipped town to avoid paying up!  Later, I heard they're cursed and bewitched and now wander the jungle ruins.  But I don't care what their fate is - I want what's mine!\n\nThey're at the Ruins of Aboraz and the Ruins of Jubuwal, northeast of here.  Find them, and collect.", sourceObjective = "Bring Maury's Clubbed Foot, Jon-Jon's Golden Spyglass, and Chucky's Huge Ring to \"Sea Wolf\" MacKinley in Booty Bay.", progress = "{name}, did you find those three dogs?  Did you collect their valuables?", completion = "Great!  I can get a good price for these, especially for what's inside Maury's foot!  Thanks much, {name}!\n\nI hope those three learned their lesson: don't bet something you can't afford to lose.\n\nAnd maybe it's too late for them, but...they should be careful of who they gamble with.", sourceObjectiveStatus = "unverified-source-field" }
quests[610] = { id = 610, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "\"Pretty Boy\" Duncan", description = "My FATHER sent you? I'd have thought that old codger would have given up on me by now.\n\nIt wasn't really his fault I ran off, he just shouldn't have expected I'd be willing to live a boring life, reading over musty books and associating with grey-haired, stiff-backed, stuffy mages!\n\nIf you need my dagger, you'll have to get it back from \"Pretty Boy\" Duncan, one of the Bloodsail Buccaneers. Put something 'tween his shoulders and I'm sure he'll give it up.", sourceObjective = "Get Catelyn's dagger from \"Pretty Boy\" Duncan.", progress = "I'd never been beat before, you know, {name}? Sure I'd been cut, can't get in a knife fight without that, but he just smacked me on the side of the head, blacked me out. When I came to my blade was gone.\n\nAs much as my nickname might indicate, I still need a knife to fight, and for me, it has to be that one.", completion = "You beat Duncan? I guess you aren't as wet behind the ears as you looked at first glance.\n\nI suppose that also means I shouldn't challenge you to a fight any time soon!", sourceObjectiveStatus = "unverified-source-field" }
quests[611] = { id = 611, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Curse of the Tides", description = "So you're looking for an altar of some sort? Well, I'm no expert on troll ruins like my father, but I have heard about a sunken troll city out near that island you're looking for. Maybe you should try there.\n\nYou got my knife back for me, so I guess you can borrow it... but I want it back when you're done!", sourceObjective = "Destroy the Altar of the Tides with Catelyn's Blade, kill Gazban and bring the Stone of the Tides and Catelyn's Blade back to Baron Revilgaz.", progress = "Have you retrieved the Stone of the Tides for me, {name}? I've already cleared out a space and purchased a fine stand for it.", completion = "Amazing! The Stone of Tides! It shall have a place of prominence in my collection of ancient troll artifacts. Did you see how it almost seems as though a tide is trapped within its surface? Magnificent!", sourceObjectiveStatus = "unverified-source-field" }
quests[613] = { id = 613, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cracking Maury's Foot", description = "Curses!  That swab Maury put a lock on his foot, and I can't open it!  His loot's inside the foot, and that's what he owes me!\n\nWe need to find the key to open the lock.  Maury was known to gamble with the Mosh'Ogg ogres, at their mound to the northeast.  And he told me, when he was still alive, that the last time he went to the mound he was chased off after winning too much.  Maybe the Ogres there have his key.\n\nBut if they do, you might have to kill a load of them to find the right one...", sourceObjective = "Bring Maury's Key to \"Sea Wolf\" Mackinley in Booty Bay.", progress = "Ahoy, {name}!  Have you yet found Maury's Key?", completion = "You found it!  Thanks a million, {name}.  You've been a big help to me!\n\nHere you go - you earned this!", sourceObjectiveStatus = "unverified-source-field" }
quests[614] = { id = 614, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Captain's Chest", description = "I used to sail a ship from here all the way to Ratchet, in Kalimdor.  I was a successful captain with a sterling reputation.\n\nUntil...\n\nThose cursed sea giants ruined me!  They smashed my ship, killed my crew, and set me on a lifeboat to Booty Bay.  And one of the giants, Gorlash, stole my Captain's Chest.  He said he wanted it for a snuffbox.  The nerve!\n\nI hear Gorlash wanders the coast east of here.  Find him and get back my chest!  Do that, and you'll have earned a captain's gratitude.", sourceObjective = "Bring Smotts' Chest to Hecklebury Smotts in Booty Bay.", sourceObjectiveStatus = "unverified-source-field" }
quests[615] = { id = 615, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Captain's Cutlass", description = "After I lost my first ship to those giants, I bought another.  Named Smotts' Revenge, I filled it with supplies and crew, and set out to find the villains.  I found them, but...they beat me.  They smashed Smotts' Revenge, killed my second crew and set me on another lifeboat.\n\nThis time another of the giants, Negolash, stole my cutlass.\n\nFace Negolash and bring me my cutlass!\n\nSpeak with Sprogger.  He was my cook on the Smotts' Revenge, and survived the last attack.  He can help you find the giant.", sourceObjective = "Speak with Sprogger.After I lost my first ship to those giants, I bought another. Named Smotts' Revenge, I filled it with supplies and crew, and set out to find the villains. I found them, but...they beat me. They smashed Smotts' Revenge, killed my second crew and set me on another lifeboat.\n\nThis time another of the giants, Negolash, stole my cutlass.\n\nFace Negolash and bring me my cutlass!\n\nSpeak with Sprogger. He was my cook on the Smotts' Revenge, and survived the last attack. He can help you find the giant.", sourceObjectiveStatus = "unverified-source-field" }
quests[616] = { id = 616, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Haunted Isle", description = "Baron Revilgaz has had me keep an ear out for rumors of the strange and out-of-place in Booty Bay and Stranglethorn. I don't usually put much stock in ghost stories, but I heard some sailors in the tavern talking about a haunted island off the coast. Water elementals and a raving goblin ghost, they say.\n\nIf you're going to go talk to Revilgaz, could you relay that story to him?", sourceObjective = "Speak with Baron Revilgaz in Booty Bay.", completion = "Interesting. Some time ago, I seem to remember reading a book once that suggested...\n\nAh, of course, a troll legend it was. If what Krazek reports is true, perhaps I will soon be able to add the Stone of the Tides to my collection of ancient artifacts and relics.", sourceObjectiveStatus = "unverified-source-field" }
quests[617] = { id = 617, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Akiris by the Bundle", description = "You looking fer work, {name}? I might have some if you're up for a little challenge.\n\nI got a friend named Groy who makes a killing selling what the naga call akiris reed: it's some kind of valuable ocean reed. Not too sure what it's for, but he pays well for bundles of the stuff.\n\nYa bring me ten stalks of the stuff, and we'll have business to do. The naga were last seen along the beach to the north of here.", sourceObjective = "Bring 10 Bundles of Akiris Reed to Privateer Bloads in Booty Bay.", progress = "If ya got no business with me, then move along, {name}.", completion = "Well done, {name}. 10 stalks of akiris reed wasn't too much a challenge after all, huh? No offense to the naga, but hey, everybody's gotta make a living.", sourceObjectiveStatus = "unverified-source-field" }
quests[618] = { id = 618, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Facing Negolash", description = "Negolash is a hungry giant.\n\nWhen the giants destroyed our ship, Negolash went straight for my kitchen.  He wasn't hungry for crew like the other giants.  Negolash wanted wine...and my Barbecued Buzzard Wings.  They're my specialty, and I had to go all the way to the Badlands for the recipe!\n\nIf you want to lure the giant, then get some wine and a heap of buzzard wings.  Put them in our old lifeboat, southeast of here along the coast.  When Negolash smells all that food, he'll come for sure!", sourceObjective = "Bring 10 Barbecued Buzzard Wings and 5 bottles of Junglevine Wine to Captain Smotts' Lifeboat.\n\nKill Negolash, and bring Smotts' Cutlass to Captain Smotts in Stranglethorn.", sourceObjectiveStatus = "unverified-source-field" }
quests[619] = { id = 619, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enticing Negolash", progress = "This is an abandoned lifeboat.  Printed along its side in scratched, faded paint are the words:\n\n\"Smotts' Revenge\"", completion = "You pile food and drink upon the raft..." }
quests[620] = { id = 620, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Monogrammed Sash", description = "This fine sash has the letters \"HS\" embroidered along its hem.", sourceObjective = "Return the Monogrammed Sash to its owner.", sourceObjectiveStatus = "unverified-source-field" }
quests[621] = { id = 621, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zanzil's Secret", description = "Zanzil the Outcast dwells with his followers in the Jubuwal and Aboraz Ruins, northeast of Booty Bay.  He is exiled from his tribe.  Why? Well...\n\nZanzil has methods of bending the minds of others, and his leaders fear him.  He uses a mixture of jungle plants on his followers to suppress their will and strengthen their bodies.\n\nHis mixture would be worth much to those who wish to control others.\n\nBring me samples of his mixture, and I will find a use for them.", sourceObjective = "Bring 12 samples of Zanzil's Mixture to Crank Fizzlebub in Booty Bay.", progress = "Do you have the samples of Zanzil's Mixture??", completion = "Ah, very good!  Here is your pay.\n\nAnd here is a little something extra... for your discretion.", sourceObjectiveStatus = "unverified-source-field" }
quests[622] = { id = 622, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Corporal Kaleb", description = "While you were gone I fixed the pot you brought me.  I even added an extra steam whistle, and look!  There's a new chopper at the bottom that'll cut through leg bones!\n\nYes yes, Krazek's Crock Pot is a 100% cook pleaser!  I'm sure its owner will be satisfied.", sourceObjective = "Bring Krazek's Fixed Pot to Corporal Kaleb at the Rebel Camp.", progress = "Hello, {name}.  Did you make it to Booty Bay?  Did the goblin Krazek fix my pot??", completion = "It's fixed!  This is great, now I can get dinner started!  Thanks so much, {name}.\n\nI hope you were okay in Booty Bay.  That place can get pretty rough, and... I heard rumors that the goblins will sometimes drag drunk sailors to their slave boats and take them to who-knows-where... to do who-knows-what...", sourceObjectiveStatus = "unverified-source-field" }
quests[623] = { id = 623, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Akiris by the Bundle", description = "{name}, since I have you here, I got a message from Groy while you were gone. He mentioned bein' satisfied with the last shipment that arrived and has a client that wants some more of the stuff right away.\n\nI won't be headin' to Theramore for a week, but if you're willin' to make the journey, there's no reason you can't take the stuff for me.\n\nFeeling adventurous? You do know where Dustwallow Marsh is, doncha? I'd be careful though, Theramore can be dangerous if you're the wrong kind of crowd.", sourceObjective = "Bring a Bundle of Akiris Reeds to Privateer Groy in Theramore.", progress = "Yeah?", completion = "What?! I got a lot better things to do then talk to the likes of you, {class}. Make it worth my while or get outta my face.\n\nHuh? Bloads sent ya, huh? Well, whaddaya got for me?\n\n\n\nNot bad, not bad at all. Another bundle will make my client quite happy.\n\nI suppose yer next question's gonna be about money, huh, {class}? Of course it is!\n\nHere, take this coin and some advice: get off my docks.", sourceObjectiveStatus = "unverified-source-field" }
quests[624] = { id = 624, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cortello's Riddle", description = "There is an ornate, well-traveled bridge\nEast of Deadwind and south of Redridge\nUnderneath there waits something for you\nSome call it a hint, others a clue\nThere it will lie for endless tomorrows\nBiding its time in the Swamp of Sorrows", sourceObjective = "Solve the riddle!", completion = "The soggy parchment contains the next clue....", sourceObjectiveStatus = "unverified-source-field" }
quests[625] = { id = 625, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cortello's Riddle", description = "A far off land in Kalimdor awaits\nWhere peril has dashed hopes and fates\nEast of Barrens the weather is harsh\nGloom and danger pock Dustwallow Marsh\nBut there lies a clue for those up to the test\nWaiting to be found in a cave in the southwest", sourceObjective = "Solve the riddle!", completion = "You find a musty scroll.", sourceObjectiveStatus = "unverified-source-field" }
quests[626] = { id = 626, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cortello's Riddle", description = "To Lordaeron! The great land of turmoil\nWhere brave soldiers with death do toil\nFind your way through the great unrest\nThere you will find the end to this quest\nAlong the coast of the Hinterlands, at the base of the great falls\nUnderneath the water there does your treasure call!", sourceObjective = "Solve the riddle!", completion = "You open the chest to discover....", sourceObjectiveStatus = "unverified-source-field" }
quests[627] = { id = 627, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Favor for Krazek", description = "There is a mountain cave in Drywhisker Gorge, far to the north in the Arathi Highlands.  In that cave is rare ore: bloodstone.  The bloodstone in this cave is not of the highest grade, but even low-quality bloodstone is valuable... to those with the knowledge to use it.\n\nI would like some.\n\nI will fix your crock pot, but while I work on it... bring me samples of bloodstone.  Bring me enough, and I'll even give you a bonus.\n\nOh, and if you don't have the skill to mine it... find someone who does!", sourceObjective = "Bring 4 loads of Lesser Bloodstone Ore to Krazek in Booty Bay.", progress = "Hello, {name}.  Did you have luck getting the bloodstone?", completion = "Ah, splendid!  That was a big favor you did for me.\n\nHere is your payment...", sourceObjectiveStatus = "unverified-source-field" }
quests[628] = { id = 628, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Excelsior", description = "With the inside finished, all that's left is to add the outer layer. For this, I use only the best elder croc skins. They are more durable and a better canvas--if you will--for adding the designs and accents that make Drizzlik's Excelsior line.\n\nIt's hard to find that perfect skin though, the only one that fits my plan is the skin of an elder saltwater crocolisk. The elders only come out to defend the other saltwater crocs, so you might need to kill a few to draw one out.", sourceObjective = "Bring an Elder Crocolisk Skin to Drizzlik in Booty Bay.", progress = "I read somewhere that the saltwater crocolisks are slowly dying out... bad news for my business, isn't it?\n\nAnyways, I hope you have that elder saltwater crocolisk skin for me!", completion = "Great! Thanks to your help I'll have this order filled and sent off to Director Riddlevox on the next boat to Undermine. Ahead of schedule, even!\n\nFor all your hard work, here, I made some extras, so take a pair. It's on Drizzlik.\n\nAnd remember, there's no boot so fine as one of Drizzlik's Excelsior line!", sourceObjectiveStatus = "unverified-source-field" }
quests[629] = { id = 629, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Vile Reef", description = "Long ago, a great shudder of the earth sunk an old troll city beneath the waters of the Savage Coast to the northwest.  We call that place the Vile Reef, for murlocs now reside in the ruins of the city, attacking any who draw close.\n\nThere is an old tablet among those ruins that tells the ancient tale of Gri'lek, a hero of troll legends.  The tale is sacred to the Darkspear tribe, and although the tablet is too large to move, I want a shard of it to enshrine in our new home in Orgrimmar.", sourceObjective = "Bring a Tablet Shard to Kin'weelay at the Grom'gol Base Camp.", progress = "I await the Tablet Shard, {name}.", completion = "This is good.  When I return to Orgrimmar I will place this shard in a sacred place.  It will remind us of the might and honor of Gri'lek.\n\nThank you, {name}.  Your deeds mark a growing friendship with the Darkspear tribe.", sourceObjectiveStatus = "unverified-source-field" }
quests[630] = { id = 630, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Message in a Bottle", description = "{name}, I put my faith in you and anyone you can muster to help free me. The great Skymane King Mukla is my captor. He commands the beasts of this island, and they keep me here against my will with the aid of this chain. If you can slay him and find the key to this shackle, I shall be indebted to you greatly.\n\nI often hear him to the southeast side of the island, but please be careful: he is not to be trifled with.", sourceObjective = "Slay King Mukla and return to Princess Poobah with the Key to free her.", progress = "I thank my ancestors someone has come to aid me. Do you have the key that will free me?", completion = "{name}, you have saved me from a great dishonor. If it was within my power, I would offer you a place among my tribe. But for now, all I can only offer you is this token for the courage and nobility you have shown.", sourceObjectiveStatus = "unverified-source-field" }
quests[631] = { id = 631, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Thandol Span", description = "A tremendous explosion roared through the hills.  'Twas horrible, I tell you!\n\nGood soldiers died defending the Thandol Span.  Longbraid says we'll take revenge on the Dark Irons before all is said and done.\n\nWe're in a world of hurt though and I don't see any reinforcements in sight.  Longbraid sent Ol' Rustlocke to scout the eastern bridge to see if we could secure it.\n\nThat was days ago.  We haven't the manpower to search for him with Dun Modr under siege.\n\nPerhaps you can find him...", sourceObjective = "Rhag Garmason wants you to locate Ol' Rustlocke.", completion = "You search the tiny, dwarven corpse.  Engraved into the helmet you can clearly read: Ebenezer Rustlocke.", sourceObjectiveStatus = "unverified-source-field" }
quests[632] = { id = 632, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Thandol Span", description = "It seems as though poor Ol' Rustlocke ran into a Dark Iron ambush.  You notice a parchment next to his clenched fist.\n\nReport the grim news to Rhag Garmason and show him what you found.", sourceObjective = "Report back to Rhag Garmason and show him the parchment you found on Rustlocke's corpse.", progress = "Any sign of Ol' Rustlocke, {name}?", completion = "Oh my, the news is grave....", sourceObjectiveStatus = "unverified-source-field" }
quests[633] = { id = 633, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Thandol Span", description = "Heavens no!  Poor Rustlocke.  'Tis quite a tragedy indeed.\n\nWe must not let his death pass in vain.  This parchment you discovered indicates that Kam Deepfury, the mastermind behind the original attack, arranged for a cache of explosives to be stashed just across the Thandol Span, in Arathi Highlands.\n\nIf those explosives make it to the bridge, our major supply line to the north will be severed!  The cache must be destroyed, {name}!  Return to me when your mission is complete.\n\nYou're our only hope.", sourceObjective = "Destroy the cache of explosives.", progress = "The cache of explosives must be destroyed!", completion = "The remaining bridge is saved!  You have done a great service to King Magni and the people of Khaz Modan.\n\nNow if we can only hold out long enough for reinforcements to show...", sourceObjectiveStatus = "unverified-source-field" }
quests[634] = { id = 634, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plea To The Alliance", description = "I ask of you one more small favor, {class}.  We await the reserves of Ironforge.  However, Roggo has knowledge of an Alliance camp to the north in Arathi Highlands at Refuge Pointe.\n\nTravel there and seek out Captain Nials.  Ask the good Captain if the Alliance can spare some soldiers to help us reclaim Dun Modr and the Thandol Span.", sourceObjective = "Seek out Captain Nials at Refuge Pointe.", completion = "My condolences go out to Longbraid and his brave soldiers.  The news of the Thandol Span tragedy and the fall of Dun Modr hangs heavy in my heart.\n\nBut Stromgarde has fallen!  Hence our presence here at Refuge Pointe.  We are faced with retaking our own great city.\n\nHonor and duty require that we do not leave the Highlands until Stromgarde raises the mighty banner of the King once again. I will send word to Longbraid that he is on his own...", sourceObjectiveStatus = "unverified-source-field" }
quests[635] = { id = 635, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crystal in the Mountains", description = "This shard pulses as you hold it...\n\nYou feel a sense of pleading coming from the shard, as if someone is trying to communicate, someone who desperately needs your help.\n\nA vision appears in your mind - of the northern mountains of Arathi, and of a brilliant crystal jutting from the earth there.\n\nYou feel drawn to that place.", sourceObjective = "Find the crystal from your vision.\n\nProvided item:", completion = "This crystal pulses, as if a living force is trapped within it.", sourceObjectiveStatus = "unverified-source-field" }
quests[637] = { id = 637, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sully Balloo's Letter", description = "The waterlogged and war-torn envelope dissolves in your hands, leaving you with a few pages of a letter in your grasp, written with painstaking care.\n\nThe letter is addressed to a Mrs. Sara Balloo of Ironforge and begins, \"My dear Sara....\"", sourceObjective = "Deliver Sully Balloo's Letter to Sara Balloo.", progress = "You look as though you have traveled a great distance and seen much turmoil in your time, {class}.  These times we live in are trying on the soul.  What news do you bring to me now?", completion = "You say you saw my Sully pinned beneath the icy waters?  Say it isn't so!\n\nLet me read what he wrote....", sourceObjectiveStatus = "unverified-source-field" }
quests[638] = { id = 638, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trollbane", description = "With Thoras Trollbane dead and Stromgarde in ruins, Vol'jin has instructed that we make every effort to spirit the legendary sword Trol'kalar from the humans' hands, so that we might use it in our coming battles against the trolls of Zul'Gurub.\n\nZengu, one of our seasoned hunters, was dispatched to Hammerfall in northeastern Arathi Highlands to oversee its procurement.", sourceObjective = "Travel to Hammerfall in the Arathi Highlands and speak with Zengu.", completion = "How you doing, {class}? The task set before us by Vol'jin will be a difficult one, and any assistance you might provide will be appreciated and necessary.", sourceObjectiveStatus = "unverified-source-field" }
quests[639] = { id = 639, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sigil of Strom", description = "In ancient times, trolls fought against the Arathorian Empire and our most capable adversary, Lord Ignaeus of Strom, named Trollbane. He rode into battle wielding Trol'kalar--troll slayer, in their ancient tongue.\n\nBut now the sons of Trollbane are weakened, their stronghold brought to ruin.\n\nThe sword is protected by several sigils that were divided among the survivors of Stromgarde, and we must retrieve them.\n\nThe first was taken by the Syndicate, one of their men in Stromgarde should have it.", sourceObjective = "Get the Sigil of Strom for Zengu in Hammerfall.", progress = "Have you located the first sigil yet? It is most likely carried on the person of one of the Syndicate agents in Stromgarde.", completion = "Excellent, mon. That's a good start to collecting the sigils we'll need to remove Trol'kalar from Trollbane's tomb.", sourceObjectiveStatus = "unverified-source-field" }
quests[640] = { id = 640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Broken Sigil", description = "Thoras Trollbane's tomb is protected by three sigils--the first of which you retrieved from the Syndicate. The other two will be harder to get, as they're held by the firmly entrenched Stromgarde militia.\n\nThe sigil of Thoradin was divided into five pieces by Thoras' son, Galen, and dispersed among the Stromgarde defenders. Retrieve the pieces and bring them to Tor'gan, the troll shaman, he will be able to bind them into the complete sigil.", sourceObjective = "Retrieve the 5 Sigil Fragments from the defenders in Stromgarde, and bring them to Tor'gan in Hammerfall.", progress = "Throm'ka, {class}. Zengu informed me that you required my assistance?", completion = "Ah, you need me to reconstruct this sigil? It shouldn't be too difficult... all the pieces seem to be here and the magical structure will be easy to reform.\n\nYou might want to close your eyes.", sourceObjectiveStatus = "unverified-source-field" }
quests[641] = { id = 641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sigil of Thoradin", description = "The reconstruction worked flawlessly. The sigil can now be used to unlock the seal on Trollbane's tomb. Return it to Zengu, no doubt he has additional tasks for you to complete.", sourceObjective = "Bring the restored Sigil of Thoradin to Zengu in Hammerfall.", progress = "{name}! Do you have the second sigil?", completion = "We're halfway to being able to remove Trol'kalar from Trollbane's tomb. We are not exactly sure where the third sigil is, as its holders seem to move around Arathi quite a bit, but I have faith that you'll be able to find it.", sourceObjectiveStatus = "unverified-source-field" }
quests[642] = { id = 642, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Princess Trapped", description = "My name is Myzrael.  I am a princess of the earth, and my captors, the giants, have trapped me deep beneath the Arathi Highlands.  These crystal shards are the only way I can speak with the surface world.\n\nPlease help me.  Allies of the giants, the Drywhisker Kobolds, have a shard like this one in their Drywhisker Gorge, to the east.  To power the cluster, you must gather Motes of Myzrael from the kobolds and apply them to it.\n\nI beg you, {name}, aid me!", sourceObjective = "Gather 12 Motes of Myzrael, then bring them to the Iridescent Shards in Drywhisker Gorge.", progress = "This cluster of shards looks much like the Shards of Myzrael.  But the same feeling of security does not pulse through them.", completion = "Ah!  You activated these shards.  Already I feel more myself!\n\nBut alas, I am still far from free...", sourceObjectiveStatus = "unverified-source-field" }
quests[643] = { id = 643, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sigil of Arathor", description = "Though they can barely be said to control Stromgarde, let alone the whole of Arathi Highlands, the human prince trots the remnants of his cavalry over the countryside. I can't understand why he does it, but who understands the way the humans think, hm?\n\nWhatever his reasoning, more importantly, he has given one of the sigils to Lieutenant Valorcall, their cavalry leader. Locate him and bring his sigil back to me.", sourceObjective = "Retrieve the Sigil of Arathor and return it to Zengu in Hammerfall.", progress = "Valorcall will not be easy to track down, {name}. Mounted on horseback, he can cover ground quickly. Nonetheless, we must have his sigil.", completion = "Losing their cavalry leader will prove a large blow to the Stromgarde defenders. Better yet, it means that we are only one sigil from being able to have Trol'kalar for ourselves.", sourceObjectiveStatus = "unverified-source-field" }
quests[644] = { id = 644, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sigil of Trollbane", description = "The final of the sigils needed to unlock the tomb of Thoras Trollbane is held by his son personally. He resides deep within Stromgarde, in a chapel in the militia-held districts. Prince Galen is well protected and no slouch of a warrior himself, so this task could prove most difficult.", sourceObjective = "Kill Prince Galen Trollbane and bring the Sigil of Trollbane to Zengu in Hammerfall.", progress = "You've returned, {name}. Is the line of Ignaeus Trollbane broken?", completion = "Quite a day this is, {class}. The blood of Trollbane will no longer haunt my people, and the sigils needed to take Trol'kalar are in our possession. Soon, very soon, we will strike against the hated trolls of Zul'Gurub.", sourceObjectiveStatus = "unverified-source-field" }
quests[645] = { id = 645, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trol'kalar", description = "What's this? With the four sigils brought together, they have formed together to create one sigil. There can be no doubt that this will be able to break the wardings placed upon Trollbane's tomb.\n\nTrollbane's remains are entombed in the Sanctum behind the chapel in Stromgarde. Retrieve Trol'kalar.", sourceObjective = "Retrieve Trol'kalar from Trollbane's tomb in Stromgarde.", progress = "Etchings in the stone upon the face of the tomb of Trollbane match the glowing lines of the Sigil of Ignaeus...", completion = "Matching the lines on the face of Trollbane's tomb with the glowing lines of the Sigil of Ignaeus, a flash of light consumes the Sigil, and the legendary sword Trol'kalar is released from the stone hands' grip.", sourceObjectiveStatus = "unverified-source-field" }
quests[646] = { id = 646, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trol'kalar", description = "The light slowly fades, the sword Trol'kalar, held within a stone sheath has been released.", sourceObjective = "Deliver Trol'kalar to Zengu in Hammerfall.", progress = "{name}! Have you taken the sword?", completion = "For generations, the forces of Strom and Arathor ravaged the trolls. Now their greatest weapon is in our hands. Our inching progress in the steamy forests of Zul'Gurub will be no more.\n\nYour assistance has been great, {name}, and the Darkspear trolls are indebted to you.\n\nI will be sure that the sword is delivered to Nimboya at Grom'gol.", sourceObjectiveStatus = "unverified-source-field" }
quests[647] = { id = 647, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "MacKreel's Moonshine", description = "Had quite a bit of the ol' Moonshine last night!  Longbraid would have my head if he knew that I passed out during my watch.\n\nThe noggin hurts something fierce.  Felt as though a whole brigade of siege engines passed overhead, all that rumbling.\n\nOh my, look at the time! I promised Brewmeister Bilger in Southshore that I'd repay my debt to him by sending some Moonshine.\n\nBut there are just 15 minutes left before I'm overdue!  Take him this batch, would you please?  And hurry!", sourceObjective = "Take MacKreel's Moonshine to Brewmeister Bilger in Southshore.", progress = "What's the good word, {race}?", completion = "Ah, nothing like Foggy MacKreel's Moonshine to warm you up on a brisk day!  And here I was thinking the little bugger was going to be overdue on his bills again. Thank you, friend!  Many thanks indeed!", sourceObjectiveStatus = "unverified-source-field" }
quests[648] = { id = 648, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rescue OOX-17/TN!", description = "The gnome's voice crackles once again from the robot:\n\n\"I need to move OOX-17/TN to an open, safe place so it can begin a lengthy take-off procedure.  It has built-in cloaking, but I need time on my end to make it operational again.  I need you to escort the robot from its current location to, let's say, Steamwheedle Port!  That should be a perfect place, and long enough, to get things on line!\"\n\n\"Escort it safely to the port, and then come talk to me in Booty Bay!  Oglethorpe Obnoticus - out!\"", sourceObjective = "Escort OOX-17/TN to Steamwheedle Port, then report to Oglethorpe Obnoticus in Booty Bay.", completion = "Oh, YOU'RE the great savior of OOX-17/TN!  I cannot even begin to express my thanks for your assistance!  My homing robot series needs more developing, but your recovery has saved me countless hours of rebuilding time, as well as many gold pieces in rebinding costs!\n\nPlease, take your choice of any of these items I have.  Hopefully, you will make good use of one of them.  Thank you again for your generous assistance, my robots and I are in your debt!", sourceObjectiveStatus = "unverified-source-field" }
quests[649] = { id = 649, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ripple Recovery", description = "I've got some salvage work for you, and if you're an aficionado of fine ripple like I am, then you'll love this task.  Ripple!\n\nIt's a drink, you dummy.\n\nAn abandoned Horde outpost has a stash of Hinterlands Honey Ripple from when they were in business.  You can't get fine ripple like that anymore!  One of Malton's dummy associates knows the shot, so you'll go out there and bring me a case of packaged ripple, and two for my own collection!  Talk to Malton, he'll fill you in on the details.", sourceObjective = "Talk to Malton Droffers in Orgrimmar.", completion = "Oh yeah, about the ripple dad wants!  He wants to sell the ripple to a tavern here in Orgrimmar, but we'll get more money if it is in its original packaging.  I know someone who can do that, and he's in the Hinterlands where the ripple is.  But he's, um, a high elf.\n\nWell, he's a good high elf, as he's not a part of the Alliance.  Well, he's not so much a good high elf as he is a drunken high elf.  He loves, and I mean LOVES the hooch.", sourceObjectiveStatus = "unverified-source-field" }
quests[650] = { id = 650, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ripple Recovery", description = "The elf you will need to talk to is Gilveradin Sunchaser.  He can name any wine, vintage and all, just by smell alone!  He can package up the ripple we need, so you'll need to talk with him.  We need six bottles for packaging, two for dad, and how ever many he'll want... and believe me, he'll want some.  When you've packaged the ripple and got dad's two bottles, come back here!\n\nGilveradin's camp is near some high elf lodge in the Hinterlands, and those high elves are not good.  Trust me.", sourceObjective = "Talk to Gilveradin Sunchaser; his camp is located in the Hinterlands.", completion = "Ah, so you know Malton?  He is an old drinking companion of mine.  You see, I have found something that transcends the boundaries of artificial treaties and alliances - alcohol.  Were we all to slake our thirsts on its blissful qualities, we all would be in a much better place spiritually.\n\nAlas, something tells me that your visit here is not to learn of alcohol's redeeming values, now is it.", sourceObjectiveStatus = "unverified-source-field" }
quests[651] = { id = 651, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stones of Binding", description = "Four Stones of Binding are scattered throughout Arathi.  These stones keep me pinned beneath the earth.\n\nTo unlock them you must unlock the strongest: the Stone of Inner Binding.  And to do that, you must gather keys from the other three.\n\nThese stones are watched by guardians, but if you are clever, or lucky, you may find ways to banish them.", sourceObjective = "Gather the Burning Key, the Cresting Key and the Thundering Key from the Stone of West Binding, the Stone of East Binding and the Stone of Outer Binding.\n\nBring them to the Stone of Inner Binding.", progress = "This is the Stone of Inner Binding.  It is the strongest of the binding stones and must be unlocked for the others to open.", completion = "<Myzrael speaks through the stone.>\n\nYou have done it!  You opened the Stones of Binding!  I can feel the shackles about me loosen, and freedom draws ever closer.\n\nYou are a noble {class}, {name}.  My rescuer!", sourceObjectiveStatus = "unverified-source-field" }
quests[652] = { id = 652, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking the Keystone", description = "Opening the Stones of Binding loosened much of my confinement, but a lock still holds me chained.  It is the Keystone you see among this circle of stones.  And the key is held by one of my captors, the stone watcher Fozruk.\n\nYou must obtain that key, which the stone watchers call the Rod of Order, from Fozruk and use it to open the Keystone.\n\n{name}, you have done so much to aid me.  Just a little more...and my gratitude will shake the very foundations of the earth!", sourceObjective = "Find and kill Fozruk. Bring the Rod of Order to the Keystone in the Arathi Highlands.", progress = "The Keystone is charged with tremendous geomantic energy.", completion = "You place the rod in the keystone.  And a shudder is felt beneath you...", sourceObjectiveStatus = "unverified-source-field" }
quests[653] = { id = 653, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Myzrael's Allies", description = "<Myzrael speaks.>\n\nFree!  I AM FREE!  I am free to gather strength, hidden from my captors.  For if they faced me now they would surely overpower and again imprison me.\n\nBut in time I will confront the giants, and they will regret their wardship of me!\n\nYou are a noble ally, {name}.  I will need your help again in time.  When I am ready, I will need you to summon me to the surface.\n\nSpeak with Gerrig Bonegrip.  He is in Ironforge, in a shop of the Forlorn Cavern.  He knows how I can be summoned.", sourceObjective = "Speak with Gerrig Bonegrip in the Forlorn Cavern of Ironforge.", completion = "The Lady told me of your coming, {class}.  You are welcome in my abode for you, like I, serve a higher cause.", sourceObjectiveStatus = "unverified-source-field" }
quests[654] = { id = 654, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tanaris Field Sampling", description = "Activating the power source makes the field testing kit start to glow and vibrate.  It would seem to be working as planned.\n\nAccording to Chief Engineer Bilgewhizzle, you now have two hours to collect the data you need in the Tanaris desert.  If you do not collect it within two hours, all the data will be lost and you will need to buy another power source from him.\n\nReturn to him when you have completed the task.", sourceObjective = "Acquire acceptable samples for 8 basilisks, 8 hyenas, and 8 scorpions. Bring the testing kit back to Chief Engineer Bilgewhizzle in Gadgetzan before the power source runs out.", progress = "Well, did you get everything you needed?  If you didn't and the power runs out, everything inside will be ruined and you'll have to start over.\n\nHey, don't look to me for sympathy; I'm all about the Gadgetzan Water Company making a profit, and if that means selling you power sources until we can afford to import water in from the icy springs of Dun Morogh, so be it!", completion = "All right then, it will take me just a second to remove the power source.  After that, you can do with it whatever you like now without having to worry about losing the data inside.", sourceObjectiveStatus = "unverified-source-field" }
quests[655] = { id = 655, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hammerfall", description = "It is still clear to me, like yesterday... So many years without hope, with wood and steel to bind me to this terrible place. Then finally, finally! There was the Warchief. Doomhammer in his midnight plate, his warhammer held high.\n\nIt was... too terrible... That the blow of a coward would strike down our greatest hero. From behind he charged on his horse, and then his lance ran him through... I fell to my knees. What hope was there? What hope is there...", sourceObjective = "Speak with Tor'gan in Hammerfall.", completion = "Ah, Gor'mul you speak of. Yes, from what he says, it seems he has never recovered from the death of Doomhammer.\n\nGor'mul was a captive here when Thrall and Orgrim fought to free the camp, but as the earth shook and our brethren escaped, he was left behind. He wandered alone and lost for years without direction or hope, until we returned to establish ourselves here in Hammerfall.", sourceObjectiveStatus = "unverified-source-field" }
quests[656] = { id = 656, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Summoning the Princess", description = "You must defeat Myzrael before she grows in strength.  If you do not, then once she has gathered enough power she will challenge her captors!  There are some who think they can control her, but if she can be controlled then why did the giants chain her in the first place??\n\nCrazy logic, eh?\n\nTo defeat her, summon her at the Shards of Myzrael where you first spoke with her.  Defeat her and gather her Eldritch Shackles, then bind them to the Shards of Myzrael.\n\nDo that, and she will again be trapped.", sourceObjective = "Go to the Shards of Myzrael, summon her and defeat her.\n\nGather her Eldritch Shackles and bind them to the Shards of Myzrael.", progress = "The Shards of Myzrael are now strangely quiet.", completion = "As the eldritch shackles are placed around the Shards, an unhuman wail is heard from far below.  The scream is followed by a roar.\n\nThe Shards of Myzrael no longer invoke feelings of warmth and security as they once did.  Now they pulse with an open menace... as if the thing beneath them holds ill will toward the surface.", sourceObjectiveStatus = "unverified-source-field" }
quests[657] = { id = 657, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hints of a New Plague?", description = "<Quae begins to go through the folder.>\n\nThis IS interesting. Seems Apothecary Jorell has been working on some deadly experiments here at Go'Shek. Not sure what that has to do with Hillsbrad, but Phin wouldn't like it if we let it continue.\n\nWe had a run-in with some orcs while you were gone, and I'm not in good enough shape to help Kinelory. If you're up for it, she's going to need some protection when she goes down to the farm to steal whatever research Jorell still hasn't sent to Tarren Mill.", sourceObjective = "Speak to Kinelory.", completion = "If it brings Phin peace, I'll destroy every single one of the Forsaken personally. He's done so much for us since the plague. We never thought we'd find friends or family again.\n\nWhen you're prepared, come let me know. We'll get started right away.", sourceObjectiveStatus = "unverified-source-field" }
quests[658] = { id = 658, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hints of a New Plague?", description = "So, Phin sent you to check on us? Not surprised--he worries too much.\n\nWe've been watching the farm for days, and Kin claims she saw a courier come out of that small house to the south not long ago.\n\nShe talks a lot, but I can always trust her senses when we're in dangerous areas.\n\nYou wouldn't happen to be a skilled tracker, would you? We think the courier might be carrying notes to Tarren Mill. If we could get our hands on those documents, it might shed some light on what's happening in Hillsbrad.", sourceObjective = "Find the Forsaken Courier and bring back her Sealed Folder to Quae near the Go'Shek Farm.", progress = "We appreciate your help in looking for that courier, {name}.\n\nWhile you were gone, Kin saw an apothecary come out of that same house to the south of here. I'm confident that they're up to no good--I just need proof of it before we go off and do something rash.\n\nHave you had any luck yet?", completion = "Excellent! \n\nLet's see what this is about...", sourceObjectiveStatus = "unverified-source-field" }
quests[659] = { id = 659, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hints of a New Plague?", description = "Hail, and well met, {name}. I lead a group of adventurers investigating odd happenings in this area.\n\nMy cousin in Hillsbrad recently put down his dog Stanley because the animal mystically grew to an immense size and savagely attacked anyone who came near him.\n\nI believe the undead are involved, and we're looking for signs to prove as much.\n\nTwo of my companions, Quae and Kinelory, headed to the Go'Shek Farm in the Arathi Highlands, and haven't checked in for days. Find them for me? I grow concerned.", sourceObjective = "Find Quae and Kinelory near the Go'Shek Farm in the Arathi Highlands.", completion = "Try and stay as quiet as possible, traveler.\n\nOrcs don't take too well to being spied on, and there is more to this farm than meets the eye.", sourceObjectiveStatus = "unverified-source-field" }
quests[660] = { id = 660, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hints of a New Plague?", description = "All right, {name}. I'm ready if you are.\n\nShall we?", sourceObjective = "Protect Kinelory until she returns to Quae.", progress = "The time for talk is done. Protect Kinelory if you care about the people of Hillsbrad at all.", completion = "You've done a great service for us, {name}. Thank you.\n\nI hope Kin wasn't too much of a handful down there. She's very friendly, but can be just as deadly when you're her enemy.", sourceObjectiveStatus = "unverified-source-field" }
quests[661] = { id = 661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hints of a New Plague?", description = "I've seen Kinelory look way worse after a night in the tavern than she does now. You obviously did a good job protecting her.\n\nThese items she brought back from the farm should at least let Phin get an idea of what's going on out here in Arathi. Just to make sure there's no retaliation after your attack, we're going to stay here for a bit longer. Would you be willing to head back to Southshore and talk to Phin?", sourceObjective = "Find Phin Odelic in Southshore.", completion = "So, the two troublemakers are all right after all? Haha, I'm glad to hear it. I thank you for bringing me news of their whereabouts and status--it pleases me greatly that they are still alive; the two of them are irreplaceable as friends and traveling companions.\n\nBut... it's more important I thank you properly for your help. Here. Take this along with my group's thanks.\n\nWith any luck, we'll figure out what the Forsaken are up to, and put an end to it.", sourceObjectiveStatus = "unverified-source-field" }
quests[662] = { id = 662, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deep Sea Salvage", description = "O'Breen led the ships into the cove.  We were certain this is where the treasure could be found.  The Harbinger docked safely but as the Maiden's Folly and Spirit of Silverpine approached the tides began to lower.  Strangest thing I've ever seen!\n\nThose two ships ran aground into something... some sort of temple in the reef.  They sank so quickly, was quite a tragedy.\n\nWe need to retrieve their Logs as well as their Charts before we leave.  We can't leave that information behind for prying eyes!", sourceObjective = "First Mate Nilzlix wants you to retrieve the Charts and Logs from the Maiden's Folly and the Spirit of Silverpine.", progress = "How goes the search and recovery mission, {name}?  We really need to get those Logs and Charts back from the Maiden's Folly and Spirit of Silverpine.\n\nIf the information from those sources were to fall into enemy hands, Fleet Master Seahorn would force us down the plank.\n\nThat is if we ever get out of this mess...", completion = "Knowing this information is secure will bring some ease to the command in Booty Bay.  Well done, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[663] = { id = 663, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Land Ho!", description = "Lolo sees a tiny {race}! Always on the lookout, Lolo is!\n\nWelcome to Faldir's Cove.  Captain O'Breen said we'd only be here for a few hours.  Just long enough to gather the treasure and get back to Booty Bay.\n\nBut Lolo thinks we're going to be here a lot longer than that.  We lost the other two ships from our formation.  Poor Spirit of Silverpine and Maiden's Folly.  On the bottom of the sea they rest now!\n\nLolo suggests you talk to Captain O'Breen if you plan on sticking around here.", sourceObjective = "Talk to Captain O'Breen in Faldir's Cove.", completion = "Ahoy, matey.\n\n'Twas a horrible mess. Seahorn will have my ship if he finds out what went down.\n\nOne of the Professor's contraptions indicated the lost treasure was near this cove. I brought the Harbinger in to dock and signaled for the Spirit of Silverpine and Maiden's Folly to follow suit.\n\nThen the sea rumbled. The tides lowered and the two ships crashed into the reef.\n\nIt's not just a reef. Something's down there....\n\nHelp my crew out and you'll be rewarded handsomely.", sourceObjectiveStatus = "unverified-source-field" }
quests[664] = { id = 664, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drowned Sorrows", description = "Argh, 'tis a horrible life. I should be in a watery grave right now, not sittin' here by the fire, breathin' fresh air.\n\nThe crew tried so hard to save my beautiful Maiden's Folly. Bless the boys, bless their hearts.\n\nO'Breen made it to shore safely but we weren't so lucky. The seas just sank on us, I swear.\n\nOne second we're afloat and the next water is rushin' in. And those beasts! Killed all the survivors. Horrible naga scum. I went black and ended up here, saved.\n\nI want those beasts dead.", sourceObjective = "Captain Steelgut in Faldir's Cove wants you to kill 10 Daggerspine Raiders and 3 Daggerspine Sorceresses.", progress = "Bah, maybe I should go kill those naga scum myself.  It's obvious you're not goin' to do it.\n\nMaybe I can find some knitting needles so you can keep yourself busy.", completion = "Nice work out there, {name}.\n\nThose scum deserved what they got. While nothin' will ever bring me ship or me crew back, the death of those naga gives me some solace.", sourceObjectiveStatus = "unverified-source-field" }
quests[665] = { id = 665, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sunken Treasure", description = "Now that we are full-fledged Blackwater Raiders it is our job to help Mr. O'Breen locate the lost elven treasure.\n\nIt is next to impossible to find the gems in the dark sea without aid. The doctor has constructed some goggles that will help. He needs the goggles charged with the energy derived from the enchanted stone in the cave just up the hill.\n\nBut the cave is cursed! When we get close, we get ambushed. Defend me and I can harness the energy from the stone into the goggles.", sourceObjective = "Escort Professor Phizzlethorpe to the cave and back.", progress = "This is no time to talk! The goggles need to be charged with the power of the stone!", completion = "The goggles work perfectly now! Well done, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[666] = { id = 666, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sunken Treasure", description = "The treasure has been on the sea floor so long that the gems have calcified into thick stone. But the power harnessed in these goggles will allow you to locate them easily.\n\nA little gnomish ingenuity goes a long way!\n\nSo borrow the Goggles of Gem Hunting, {name}, and see if you can collect some of the lost treasure for Captain O'Breen.\n\nI'd swim down there myself but...um...well, I have important scientific business to tend to up on the safe, dry land....er, yeah.", sourceObjective = "Doctor Draxlegauge in Faldir's Cove wants you to collect 10 Elven Gems and return the Goggles of Gem Hunting once you are done.", progress = "How did the goggles work? Did everything function properly? Adjustments can be made if necessary.\n\nOh, and I'll need those goggles back when you're done. I am sure Captain O'Breen will have many uses for them later on.", completion = "Most superb, {name}! The Captain will be very pleased! And just wait until word gets back to Fleetmaster Seahorn!", sourceObjectiveStatus = "unverified-source-field" }
quests[667] = { id = 667, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death From Below", description = "This is bad. It seems the Daggerspines are amassing for an attack.\n\nNaga are known for their ruthlessness in battle. They will keep attacking until I am dead.\n\nI don't value my own life above that of my crew members, but you must help to defend me. The crew will not be able to make it back to Booty Bay without my knowledge of the seas.\n\nThe naga will be coming from the sea. I need you to remain up here with me to fend off the attack. Man the cannon and drive them back.\n\nAre you ready, {name}?", sourceObjective = "Protect Shakes O'Breen during the attack.", progress = "To arms!", completion = "We survived the attack!\n\nWe could not have done it without you, {name}.\n\nWe'll be heading out as soon as the tide rises. If you weren't such a promising hero I'd offer you a place on my crew. But I can tell you have bigger fish to fry.\n\nEven if you are a puny {race}....", sourceObjectiveStatus = "unverified-source-field" }
quests[668] = { id = 668, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sunken Treasure", description = "Let's not leave Captain O'Breen waiting. He'll want to see these gems first hand. After all, that's why we're here!\n\nAnd after a few weeks of consorting with these pirates, the professor and I have realized the last thing that's good for our health is to be caught hanging on to their treasure.\n\nHere, {name}, take these to O'Breen.", sourceObjective = "Take the Elven Gems to Captain O'Breen.", progress = "Ahoy, {class}.  What brings you to the bridge?", completion = "So the little gnomes proved their worth after all? I knew we kept those ankle biters around for a reason!", sourceObjectiveStatus = "unverified-source-field" }
quests[669] = { id = 669, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sunken Treasure", description = "Fleet Master Seahorn will want to hear about our find at once.\n\nBut as you can see, we're not in much of a position to get out of here. Not only is the tide too low, but those damned creatures we disrupted are keeping a close eye on our movements.\n\nYou can be of great service to the Blackwater Raiders if you can get word to Fleet Master Seahorn in Booty Bay that we discovered the treasure and are working on extracting more.  Take him this sample as proof.", sourceObjective = "Take the Sample Elven Gem to Fleet Master Seahorn in Booty Bay.", progress = "What brings you to Booty Bay, {class}?", completion = "Ah, leave it to good old Shakes O'Breen! I knew that he was the right Captain for the mission!", sourceObjectiveStatus = "unverified-source-field" }
quests[670] = { id = 670, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sunken Treasure", description = "Say, {name}, you seem to be an adventurous type. My fleet is stuck in Booty Bay until we can restock.\n\nThere are some heavy things brewing here and abroad and I need to get some top secret correspondence to Shakes O'Breen who is tied up off the Arathi coast.\n\nCan I trust you to deliver this message safely and in confidence?", sourceObjective = "Deliver Seahorn's Letter to Shakes O'Breen in Arathi Highlands.", progress = "So was Seahorn impressed? I bet you his smile reached from Booty Bay to Ratchet.", completion = "Thank you for making such a long and perilous journey. You have the gratitude of the Blackwater Raiders.", sourceObjectiveStatus = "unverified-source-field" }
quests[671] = { id = 671, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foul Magics", description = "I have felt a strangeness in the air... a feeling that simmers in my blood. I had my suspicions. I set off to find the source of my unease and discovered to the west, at Northfold Manor, the residual traces of demonic summoning. As I got close, my blood began to boil and the rage within me grew.\n\nOn the ground I spied an amulet of bloodstone, used to assist in demonic summoning. The one I found was depleted, however. I'll need another to examine, but I dare not return to the manor. Can you bring me some?", sourceObjective = "Get 10 Bloodstone Amulets for Tor'gan in Hammerfall.", progress = "Once-cursed blood still runs through my veins, {name}. If someone... something is summoning demons, it must be stopped.", completion = "It will take some time for me to ascertain the true intentions of the Syndicate, but their obvious association with dark, demonic magic troubles me. I will tell you when I know more.", sourceObjectiveStatus = "unverified-source-field" }
quests[672] = { id = 672, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raising Spirits", description = "We tried to settle him in, cheer him up, telling him stories of our mighty city at Orgrimmar in Kalimdor, but nothing would move him.\n\nTales of our young Warchief, Thrall, who bears the armor and hammer of Orgrim... but, perhaps... Perhaps! A demonstration of our newly found shamanistic magic would give him new hope. It is worth a try!\n\nA small object we could make for him, yes... Bring me some raptor eyes, and I will see what I can do.", sourceObjective = "Acquire 10 Highland Raptor Eyes from Highland Striders and Highland Thrashers for Tor'gan in Hammerfall.", progress = "I will create an amulet that will give Gor'mul some of the strength of the raptors. Perhaps that will awaken some flame within him...", completion = "Excellent. The spirits of the raptors that gave these eyes will lend strength to the bearer of this amulet.", sourceObjectiveStatus = "unverified-source-field" }
quests[673] = { id = 673, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foul Magics", description = "There is no doubt in my mind that a powerful warlock resides within the walls of Stromgarde. From time to time, using an arcane magical relic, this warlock has summoned forth terrible demons in large numbers. We must remove the source of his energy.\n\nFind the warlock and kill him. Bring me whatever magical object you find on his person, and I will take steps to destroy it and see that its power is not used to taint this land any longer.", sourceObjective = "Retrieve Marez Cowl's Bloodstone Orb and bring it to Tor'gan in Hammerfall.", progress = "The burning in my blood... it grows by the day. The warlock must be stopped.", completion = "My restless nights will turn to peaceful slumber when I have destroyed this orb. Thank you, {name}. It is a chilling reminder of the terrible power the demons held over the orcs before Hellscream released them from their curse.", sourceObjectiveStatus = "unverified-source-field" }
quests[674] = { id = 674, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raising Spirits", description = "Here, take this amulet to Gor'mul, and see if the raptors' strength can awaken the flame of the warrior that once burned through his veins.", sourceObjective = "Give the Raptor Talon Amulet to Gor'mul.", progress = "What hope is there when the hand of a coward can slay the mightiest of the mightiest? What hope, I ask you!", completion = "What is this? Polished bone. What use have I for polished bone? Will a trinket restore the Horde to its glory?", sourceObjectiveStatus = "unverified-source-field" }
quests[675] = { id = 675, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raising Spirits", description = "<Gor'mul tosses the amulet into the ground.>\n\nTor'gan sent you, didn't he? Pah! Why he feels some mercy towards me I would not understand. Mercy was denied me when I was not allowed to die with my Warchief in battle. A cruel blow fate has dealt me...", sourceObjective = "Speak with Tor'gan.", completion = "It did not work, I see. Nonetheless, I feel that showing him the power of the shamans will eventually return Gor'mul to his once proud self. The amulet's power was not great enough to show him our newfound power.", sourceObjectiveStatus = "unverified-source-field" }
quests[676] = { id = 676, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hammer May Fall", description = "Weaklings... all of them. You, {class}, what are you looking at? Think you're something special, huh? Why not prove it?\n\nThe Hammerfall outpost in Arathi's under attack. Unless we send them help soon, their demise is imminent.\n\nBut before you go rushing off, you may want to test your skills first. Northeast of Stromgarde in Arathi is an ogre mound inhabited by the Boulderfist tribe. When you can handle the ogres and enforcers there, then report to Drum Fel in Hammerfall.", sourceObjective = "Kill 8 Boulderfist Ogres and 10 Boulderfist Enforcers, then find Drum Fel in the Hammerfall outpost in Arathi Highlands.", progress = "I have not the time to sharpen my axe, let alone leave the outpost to slay those beasts that would try and slay my kin.\n\nYou do not seem to have the experience of a grunt let alone a full-fledged {class}, what do you want, {name}?", completion = "So, you think you're strong enough to help Hammerfall? So be it.\n\nTallow either sent you to that ogre mound in the hopes that you would kill yourself or he thinks you're strong enough to aid us. Either way, you're here now and I am in need of more soldiers in our fight against the constant attacks.\n\nIf you plan on staying in Hammerfall then get some rest, and come speak to me again when you're ready. There's no shortage of fighting to be had.", sourceObjectiveStatus = "unverified-source-field" }
quests[677] = { id = 677, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms", description = "The Witherbark trolls and Boulderfist ogres of Arathi are working together to rid us from this land, but we shall not meet our fates at their, or anyone else's, hand. We will slay them and show them that we, too, have a home here. \n\nThe trolls turned their backs to us; the ogres would use us for food and bedding if we allowed them to--these things shall not be.\n\nWe start our attack on the Witherbark trolls to the south of here. Slay them in droves, and only return when their camps run thick with blood.", sourceObjective = "Slay 10 Witherbark Axe Throwers, 10 Headhunters and 8 Witch Doctors, and return to Drum Fel in the Hammerfall outpost.", progress = "If you have not yet completed my task, then perhaps you are a coward in heart as well as a tyro in war.", completion = "The signs of war are upon your garments, and sweat drips from your brow. Good, very good indeed.", sourceObjectiveStatus = "unverified-source-field" }
quests[678] = { id = 678, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms", description = "Your strength is evident, {name}. Now to see how you fare against a real enemy.\n\nThe Boulderfists have a lair to the southwest of here towards the dwarven bridge, and, if I'm not mistaken, the maulers and magi there shall present to you a greater challenge--they have done so to us thus far.\n\nSlay as many as you can and come to me in body when you are successful, or come to me in spirit when you fail. I shall give praise to your tenacity in battle either way.", sourceObjective = "Kill 10 Boulderfist Brutes and 4 Boulderfist Magi, and return to Drum Fel in the Hammerfall outpost.", progress = "You hesitate. Why? You have shown great strength thus far, {name}. Do not fail me now.", completion = "You are as strong as a kodo, and your lust for battle does your people proud.", sourceObjectiveStatus = "unverified-source-field" }
quests[679] = { id = 679, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms", description = "The head of the beast is ready to be taken off... with great force, {name}. You have shown every sign that you are able to help us with this final mighty blow. The leaders of these attacks have made their lair within the ruins of Stromgarde, a glaring symbol of human frailty.\n\nFind and slay those Boulderfist lords and their lackey shaman who would try and drive us from these lands.", sourceObjective = "Kill 7 Boulderfist Shaman and 3 Boulderfist Lords and return to Drum Fel in the Hammerfall outpost.", completion = "You do your people proud, {name}. The threat has been greatly lessened, and I am sure we will begin to thrive here in the Highlands.", sourceObjectiveStatus = "unverified-source-field" }
quests[680] = { id = 680, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Real Threat", description = "You serve my husband well, {class}, but he does not know why Hammerfall is under attack.\n\nOr'Kalar, Mug'thol's pawn in Stromgarde, has an intense hatred for my husband, and wishes nothing more than my husband's death for defeating him years ago.\n\nMy auguries tell me that Or'Kalar has laid a trap for my husband, so I have hidden signs of the ogre's presence from him.\n\nMy husband will rush off foolishly if he learns of the ogre's whereabouts and I would ask for your help in slaying the creature.", sourceObjective = "Slay Or'Kalar and bring his Head to Korin Fel in the Hammerfall outpost.", progress = "Near the Tower of Arathor--that is where you will find Or'Kalar. His death will stop the attacks on Hammerfall and protect my husband's life.\n\nI see in your eyes that you think me weak--even dishonorable--for my silence. Some day you will learn what it is to love as I do. Perhaps then you will understand a different kind of strength and honor.\n\nIn the meantime, do as I ask, and slay Or'Kalar.", completion = "You have done me a great service, {name}. Know that my husband's life and the safety of Hammerfall has been protected for another day because of your deeds. Please take this as a reward for your courage.", sourceObjectiveStatus = "unverified-source-field" }
quests[681] = { id = 681, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Northfold Manor", description = "We are fighting a war for Stromgarde, and we are losing.  The ogres, the Syndicate and we have divided our once great city, and each faction battles the other into a bloody stalemate.\n\nBut our forces dwindle while our enemy grows.\n\nWe need help from the town of Southshore, but supplies are difficult to receive while the Syndicate holds territory between us.\n\nGo to the Syndicate base in Northfold Manor and slay them.  Then, perhaps, pressure on our supply trains will lessen and more will get through.", sourceObjective = "Kill 10 Syndicate Highwaymen and 6 Syndicate Mercenaries.\n\nReturn to Captain Nials at Refuge Pointe.", progress = "{name}, with each passing hour our hold on Stromgarde grows more tenuous.  You must make haste or our city will surely fall.", completion = "Very good, {name}.  With the deaths of those Syndicate members we should have an easier time receiving supplies from Southshore.\n\nPerhaps our cause yet has hope.", sourceObjectiveStatus = "unverified-source-field" }
quests[682] = { id = 682, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stromgarde Badges", description = "The Syndicate in Stromgarde do battle with our contingent of militia there. In order to urge the rabble to fight our more disciplined troops, the Syndicate leaders have placed a bounty on our soldiers, awarding gold for each Stromgarde Badge gathered off killed militiamen.\n\nWe want those badges retrieved - we cannot allow the cutthroats to take trophies from our brave fallen!\n\nEnter the Syndicate-controlled area of Stromgarde and hunt them for our badges.", sourceObjective = "Bring 7 Stromgarde Badges to Captain Nials at Refuge Pointe.", progress = "Have you retrieved any Stromgarde Badges, {name}?  The Syndicate must learn they cannot profit from our dead.", completion = "Thank you, {name}.  We will inform the families of these fallen soldiers that they were killed in battle.\n\nIt will be grim news to bear, but it is better than the uncertainty of a missing loved one.", sourceObjectiveStatus = "unverified-source-field" }
quests[683] = { id = 683, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sara Balloo's Plea", description = "{name}, I have but a small request to ask of you.\n\nTake this note I have prepared to our great monarch of Ironforge, King Magni Bronzebeard. 'Tis a small task to ask of one such as yourself, someone who has shown great valor to the cause of the Alliance thus far.\n\nFor me to go before the King in my grief-ridden state would not serve the purpose of my cause.  Surely you understand.", sourceObjective = "Take Sara Balloo's note to King Magni Bronzebeard of Ironforge.", progress = "So you are {name} the {class}? News of your contributions to the Alliance has traveled quite far, you know?\n\nOn what business do you come before me today?", completion = "It will take but a moment for me to peruse this letter...", sourceObjectiveStatus = "unverified-source-field" }
quests[684] = { id = 684, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted! Marez Cowl", description = "A bounty has been placed on the head of Marez Cowl, a high-level advisor and operative of the Syndicate.  She was last seen within the Syndicate controlled territory of Stromgarde.\n\nBounty may be collected from Captain Nials.\n\nBe warned: Marez is a skilled and cunning Warlock, known for her trafficking with demons.  Extreme caution is advised when hunting her.", sourceObjective = "Bring Marez's head to Captain Nials at Refuge Pointe.", progress = "Greetings, {class}.  You have a report to make?", completion = "You took down Marez Cowl?  Well done, {name}.  Well done indeed!\n\nMarez menaced our Stromgarde defenders, and it is rumored she was an emissary between the Syndicate and some other, darker power.  We are glad to see that she'll no longer ply her powers against us.", sourceObjectiveStatus = "unverified-source-field" }
quests[685] = { id = 685, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted! Otto and Falconcrest", description = "The Stromgarde Militia has placed bounties on the heads of Lord Falconcrest, and his bodyguard Otto.  Falconcrest heads the Syndicate's efforts in the Arathi Highlands, and his death would cause a major disruption in those efforts.\n\nHis bodyguard Otto, although not a strategic target, is a fierce opponent and has killed dozens of our defenders.\n\nTheir bounties may be collected from Captain Nials.", sourceObjective = "Bring Otto's Head and Falconcrest's Head to Captain Nials at Refuge Pointe.", progress = "Hello.  Do you have a report to submit?", completion = "Falconcrest and Otto?  Wonderful!\n\nHere is your reward, {name}.  I am happy to pay it.", sourceObjectiveStatus = "unverified-source-field" }
quests[686] = { id = 686, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A King's Tribute", description = "I do not expect good dwarves like Mrs. Balloo to understand why the travesties of war must be endured for the greater good of our people. The loss of her husband, and the loss of every dwarf that fights in the name of the Alliance, weighs heavy on my soul.\n\nWhile I cannot bring her husband back from the Twisting Nether, I can pay tribute to him.\n\nI am going to commission a memorial to Sully Balloo to be built by Grand Mason Marblesten.\n\nSend word to him now, {class}. You shall be custodian of my bidding.", sourceObjective = "King Magni Bronzebeard wants you to speak with Grand Mason Marblesten.", completion = "So King Magni Bronzebeard himself sent ye?\n\nMy, my! This must be important!", sourceObjectiveStatus = "unverified-source-field" }
quests[687] = { id = 687, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Theldurin the Lost", description = "Theldurin the Lost was once a member of our order, the Twilight's Hammer.  But he lost his mind and scorned our teachings.  And before he fled from us, he stole the scroll of Myzrael!  We could not catch him, but rumors say he hides in the Badlands, gibbering and mad.\n\nTo bring the Lady back to us, you must find the scroll.  And to do that, you must find Theldurin.", sourceObjective = "Find Theldurin the Lost.", completion = "Hello.  Hello, hello hello hello hello HELLO!\n\nI'm sorry - wait, no I'm not!  Don't be rude!\n\nOh no...that was crazy talk.\n\nBut...sometimes being crazy is my only solace.", sourceObjectiveStatus = "unverified-source-field" }
quests[688] = { id = 688, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Myzrael's Allies", description = "<Myzrael speaks.>\n\nFree!  I AM FREE!  I am free to gather strength, hidden from my captors.  For if they faced me now they would surely overpower and again imprison me.\n\nBut in time I will confront the giants, and they will regret their wardship of me!\n\nYou are a noble ally, {name}.  I will need your help again in time.  When I am ready, I will need you to summon me to the surface\n\nSpeak with Zaruk in Hammerfall.  He knows how I can be summoned.", sourceObjective = "Speak with Zaruk in Hammerfall.", completion = "Welcome, {class}.  The Lady has informed me of your coming, and if we are to bring her back to the surface then we have much to discuss...", sourceObjectiveStatus = "unverified-source-field" }
quests[689] = { id = 689, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A King's Tribute", description = "So our good King would like a memorial built in honor of a soldier named Sully Balloo?  And you say the poor chap died during the Thandol Span tragedy?\n\nBah, will there ever be peace on Azeroth?\n\nNonetheless, any commission from the King is of utmost importance. To build a truly epic and lasting piece I want to work with one of the finest stones available. Travel to Darrow Hill in Hillsbrad and gather for me some Alterac Granite.", sourceObjective = "Grand Mason Marblesten of Ironforge wants 5 pieces of Alterac Granite.", progress = "{name}, {name}, {name}! Tell me you have enough Alterac Granite for me to begin my masterpiece in honor of Sully Balloo.", completion = "Perfect! Better than I could have imagined!\n\nAnd I have quite an imagination you know...", sourceObjectiveStatus = "unverified-source-field" }
quests[690] = { id = 690, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Malin's Request", description = "Greetings, {name}. You have the look of an adventurer about you, and I have a task that needs some tending to.\n\nArchmage Trelane, my original master, fled Stromgarde in the Arathi Highlands not too long ago, and he's asked me to help him in recovering some of the items he left behind.\n\nThe city fell under siege, and he attempted to defend the Tower of Arathor, but to no avail. I have agents in the Highlands already, but they've requested I send more aid. Are you interested?", sourceObjective = "Find Skuerto at Refuge Pointe in the Arathi Highlands.", completion = "So, Malin sent ye? I don't care if Muradin rose up from the dead and whisked ye here on a dragon. I'm busy! Talk to Kryten if you need somethin'.", sourceObjectiveStatus = "unverified-source-field" }
quests[691] = { id = 691, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worth Its Weight in Gold", description = "Archmage Malin sent Skuerto and I here to collect reagents for him. I was at a loss as to how I was going to collect the items, but now that you're here, I think my problem's solved.\n\nI need the following: Witherbark tusks, Witherbark medicine pouches and a shadow hunter knife.\n\nCould you find those for me? The Witherbark live to the southeast of Arathi.", sourceObjective = "Find 10 Witherbark Tusks, 4 Witherbark Medicine Pouches and a Shadow Hunter Knife for Apprentice Kryten at Refuge Pointe.", progress = "Have you had any luck so far, {name}?\n\n\n\nIf my research is correct, the tusks should come from any Witherbark troll. The medicine pouches come from the Witherbark witch doctors, and the strongest of the Witherbark shadow hunters should carry the special knife given to them after they've completed their rites of passage. There's no way to tell which shadow hunters will have the knife until you do battle.", completion = "Incredible! I can see why Malin asked you to come join us--very well done indeed!\n\nAt this rate, Skuerto and I will be headed back to Stormwind in no time at all.\n\nI believe my dwarven companion is back from scouting Boulderfist Hall; go speak to him when you're ready.\n\nIt looked as though he might have had a bit of a scuffle with the ogres. Don't mention that to him, though; he's very sensitive about criticisms to his skills at scouting.", sourceObjectiveStatus = "unverified-source-field" }
quests[692] = { id = 692, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Fragments", description = "The Scroll of Myzrael...the Scroll of Myzrael?!  You don't want that!  Its magic can pull Myzrael to the surface world and if you do that, we are in trouble!\n\nOr...maybe it's too late.  Maybe she already is free.  Maybe she's just gathering strength before unleashing herself upon us.  If so, then you'll NEED the scroll!\n\n...too bad it's destroyed.  Enraged elementals stole it and tore it up and now fight over the fragments.\n\nBut if you can gather those fragments, maybe we can fix it...", sourceObjective = "Bring the Torn Scroll Fragment, the Crumpled Scroll Fragment and the Singed Scroll Fragment to Theldurin the Lost.", progress = "Did you find those fragments?!?!  You'll need the Scroll of Myzrael if you want to trap her again, before it's too late!", completion = "Ah, you found them!  Good work, {name}! These might be the only chance we have against the evil of Myzrael!\n\nJust let me find my scrap-ratchet and see if I can re-attach these fragments...", sourceObjectiveStatus = "unverified-source-field" }
quests[693] = { id = 693, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wand over Fist", description = "Hey, {name}. Sorry to be so short with ye earlier... and no, that ain't a pun.\n\nI figured out where Trelane's first item ended up: Kor'gresh has it in Boulderfist Hall. An' by the way he was throwing down blasts of ice at his kin to keep them in line, he must be close to figurin' out how to use all of its powers.\n\nBoulderfist Hall's south of here an' then east of Thandol Span. Find the ogre an' get back that wand.\n\nWhile you're gone, I'll figure out what we're gonna do about Stromgarde.", sourceObjective = "Find Trelane's Wand of Invocation and return it to Skuerto at Refuge Pointe.", progress = "Our goal is the wand, {name}. Focus on that for now.", completion = "Brilliant, {name}. One item down an' three more to go, based on my list. The other three items are all in Stromgarde.\n\nTake a rest an' get your strength back--the next phase of my plan'll require a little more time an' effort. Come back to me after you've gotten a warm meal an' some rest.", sourceObjectiveStatus = "unverified-source-field" }
quests[694] = { id = 694, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trelane's Defenses", description = "All rested?\n\nHere's our next step: there're ogres all around the Tower of Arathor in Stromgarde. We're gonna need to activate the tower's defenses if you're gonna stand a chance against 'em an' still make it to the items alive. To do that, we're gonna need some gems the Boulderfist shaman have taken a liking to. They took 'em from the tower, but they're not gonna stay in their possession for long.\n\nGet one of them gems an' bring 'em to Kryten--he knows the spell to enchant 'em so they'll work as a key.", sourceObjective = "Find an Azure Agate and bring it to Apprentice Kryten at Refuge Pointe.", progress = "{name}, hello again. Have you found an azure agate yet?", completion = "You amaze me, {name}. Well done again.\n\nGive me a moment to cast the proper spell to enchant the gem, an' you'll be ready.", sourceObjectiveStatus = "unverified-source-field" }
quests[695] = { id = 695, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Apprentice's Enchantment", description = "Here you are, {name}. The gem only needs to be pressed against one of the pedestals near the base of the tower to activate its defenses. Use it when you're ready to enter the tower and find Trelane's remaining items. \n\nGood luck to you. I'll be awaiting your return here at the camp. Oh, and speak to Skuerto before you leave. He'll give you the rest of the details you'll need.", sourceObjective = "Speak to Skuerto.\n\nProvided item:", completion = "Good, good.\n\nIf there are no other delays, how about we get started?", sourceObjectiveStatus = "unverified-source-field" }
quests[696] = { id = 696, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Attack on the Tower", description = "Here's what your lookin' for: Trelane's phylactery, Trelane's orb, an' Trelane's ember agate.\n\nAll three should be in chests within the tower an' you shouldn't have a problem opening the chests on your own; you just have to be careful of the ogres.\n\nThe tower's defenses won't take care of 'em on their own; you'll need to have your weapons at the ready. Those ogres find out you're there and stealing from 'em, an' they'll be sure to put the hurt on you.\n\nBe careful, an' good luck.", sourceObjective = "Find Trelane's Phylactery, Trelane's Orb, and Trelane's Ember Agate, and return them to Skuerto at Refuge Pointe.", progress = "You do this, an' I'm sure Malin'll be more than pleased with you.", completion = "Malin couldn't've asked a worthier person to come here an' aid us, {name}. You've done a grand job!\n\nHe'll be pleased to see what an overwhelming success our mission's been.", sourceObjectiveStatus = "unverified-source-field" }
quests[697] = { id = 697, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Malin's Request", description = "Take this letter back to Stormwind and let Malin know that Kryten an' I'll be home soon. He'll reward you well for helping us here, {name}, of that I've no doubt.\n\nTravel safely.", sourceObjective = "Take the Sealed Letter to Archmage Malin in the Mage Quarter of Stormwind.", progress = "Yes? You look vaguely familiar. I do apologize, but have we met? I get so busy I lose track.", completion = "<Archmage Malin opens the letter, and his eyes grow wide.>\n\nBy the Light, you've done it. How wonderful. Trelane will be so pleased. I'm sure Kryten and Skuerto are just as excited as I am to have them on their way back to Stormwind.\n\nThank you, {name}. Please, take this to help you in your journeys.", sourceObjectiveStatus = "unverified-source-field" }
quests[698] = { id = 698, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lack of Surplus", description = "I'm working on getting some supplies together for our outpost near the beach to the east--Tok'kar does what he can, but between shifts of guard duty and cooking for his soldiers there's not much time left in the day.\n\nThey do enjoy cooking up some sawtooth meat when they can, but I haven't had time to get them another shipment. Would you mind helping them out?\n\nThe young sawtooths aren't as tasty as the older ones, so stay clear of those; give them a year or two to get to full size.", sourceObjective = "Bring 8 Unprepared Sawtooth Flanks to Tok'Kar in Swamp of Sorrows.", progress = "Lok'tar, {class}. Traveling through the swamps isn't a risk taken lightly. You're brave to test your mettle here.", completion = "Ah! Wonderful. Fresh meat for the fire tonight. Thank you, {name}.\n\nYou've helped make the coming nights more tolerable. The fire burns bright, and our stomachs will be full.\n\nIt's a pleasant surprise to have you bring us a shipment; Dar's not the most attractive orc anyone's laid eyes upon, but at least his attitude reeks far less than his smell.", sourceObjectiveStatus = "unverified-source-field" }
quests[699] = { id = 699, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lack of Surplus", description = "With the threat of murlocs along the coast, we're stationed out here to protect--or warn if the force is too large--of any coming threats to Stonard. It doesn't give us much time for relaxation, and we could use some more help if you're able.\n\nThe sawtooth snappers' claws make for fine weapons when properly prepared. Bring me some of their claws and I'll see you're rewarded with one of our weapons in thanks for the fresh meat and the good company.", sourceObjective = "Bring 6 Sawtooth Snapper Claws to Tok'Kar in the Swamp of Sorrows.", progress = "Good mead, a warm fire, an army of orcs and an arsenal of weapons... that's all we really need out here along the coast. I don't regret my position out here safeguarding Stonard, but it would be nice if we could one day get a burrow, or at least a tower.", completion = "Glad to see you're alive and well, {name}.\n\nThese claws should make do nicely. The more weapons we have at the ready for attacks against us, the better off we'll be.\n\nI'll get started on your weapon as soon as possible. It will only take a short time. I've become quite adept and quick at their production.", sourceObjectiveStatus = "unverified-source-field" }
quests[700] = { id = 700, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A King's Tribute", description = "Ah, such fine stone comes from Lordaeron.  Such a shame the land is in such shambles.\n\nBut the Memorial came out quite well! I should think the King will be most pleased with it.\n\nNow if you will, please send word to His Majesty that the Memorial is complete as requested.", sourceObjective = "Report to King Magni Bronzebeard.", completion = "The granite seems but a small token compared to a great dwarf's life. But no dwarf shall last on this planet for eternity.\n\nLet us just hope that the memorial stands as a reminder to those who will trod the great Azeroth of the future.  Lest we not forget it is for them that brave soldiers such as Sully Balloo so valiantly gave their lives.", sourceObjectiveStatus = "unverified-source-field" }
quests[701] = { id = 701, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guile of the Raptor", description = "With some additional objects, I will be able to create an item that will imbue Gor'mul with the guile of the raptor! With the power of the raptor flowing through him, Gor'mul will know our new power and rediscover the warrior that lies dormant!\n\nI will require raptor hearts to fashion the item and spell.", sourceObjective = "Acquire 12 Raptor Hearts from Highland Fleshstalkers for Tor'gan.", progress = "My preparations are made, all I require are the raptor hearts.", completion = "Yes, these will work perfectly. I will transfer their power and the spirit of the raptors into this orb. This orb will imbue Gor'mul with the fiery strength and intelligence of the raptor.", sourceObjectiveStatus = "unverified-source-field" }
quests[702] = { id = 702, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guile of the Raptor", description = "Take this orb and use its energy to give Gor'mul the essence of the raptor. Surely this will invigorate his spirit and give him new purpose in life. With him returned to normal, we can explain to him the current state of the Horde, and we will have a great warrior's assistance in our unceasing battles.", sourceObjective = "Give Tor'gan's Orb to Gor'mul.", progress = "Returned again have you? Indeed there is nothing more I could wish for now than more of Tor'gan's pity.\n\nWhat have you for me this time? Perhaps a piece of brightly colored string? Or a length of rope to end this misery of mine...", completion = "At least it is something interesting you bring to me this time. A strange power it emits...", sourceObjectiveStatus = "unverified-source-field" }
quests[703] = { id = 703, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Barbecued Buzzard Wings", description = "Oh yes, my barbecued buzzard wings are a favorite!  The sauce is rich and the meat is tangy.  And the smell will bring the hungry running from miles away!\n\nI have everything I need to cook up a batch.  Everything...except the buzzard wings!\n\nIf you want some then get me the buzzard wings.  Bring me enough, and I might even share the recipe with you!", sourceObjective = "Bring 4 Buzzard Wings to Rigglefuzz.", progress = "Hello, {name}.  Did you bring me my wings?", completion = "Ah, I'll get started on those wings right away.  I can almost taste them already!\n\nAnd here's the recipe in case you want to make them yourself!", sourceObjectiveStatus = "unverified-source-field" }
quests[704] = { id = 704, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agmond's Fate", description = "The last report I received from Agmond is troubling, more so now that he's dead!  He mentioned that his diggers uncovered \"ancient urns\" at the dig site outside Uldaman.  I fear that the urns he found at that site incited the troggs, just as did the idols I found here.\n\nI need you to get those urns for our studies.  Go to the Uldaman site, gather the urns, then return to me.", sourceObjective = "Bring 4 Carved Stone Urns to Prospector Ironband in Loch Modan.", progress = "Did you find those urns, {name}?  We must find the link between them and the troggs!", completion = "Well done!  With luck and diligence, we will find whatever link exists between the troggs and these ancient artifacts.  \n\nYou have done a great deed for the Prospectors, {name}.  Your efforts will not be forgotten.  And neither will Agmond.", sourceObjectiveStatus = "unverified-source-field" }
quests[705] = { id = 705, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pearl Diving", description = "The Badlands is a harsh place, filled with vicious predators and bold scavengers.  Scary, especially for a short little goblin.  To survive, I have to be tricky!\n\nI know the recipe for flash bombs.  I use those to scare away wildlife.  But I'm running low on one of the ingredients: crushed blue pearl powder.  Get me some and I'll make it worth your efforts.\n\nHeh, and I hope you have good boots on.  The Blue Pearls I need are found from clams at the Vile Reef.\n\nYep, the Vile Reef in Stranglethorn!", sourceObjective = "Bring 9 Blue Pearls to Rigglefuzz in the Badlands.", progress = "Did you get my pearls?  I'm almost out of flash bombs!", completion = "These will work great!  I just need to smash them into powder...then mix them with a little of this and a little of that.\n\nWatch out, scavengers!  Prepare to be flashed!", sourceObjectiveStatus = "unverified-source-field" }
quests[706] = { id = 706, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fiery Blaze Enchantments", description = "As an apprentice to Feranor Steeltoe, I learned his special technique for imbuing weapons with fiery enchantments. Last I heard of him, he was working at a smithy with a hunting party up in Lordaeron.\n\nI can't tell you too many of the details about the process, but I can tell you it requires blood from a rare, still-beating black drake whelp's heart. I don't have much to do waiting for word from Ironforge. If you bring me a heart from the whelps in Lethlor Ravine, I'll show you my skill!", sourceObjective = "Acquire a Black Drake's Heart for Sigrun Ironhew.", progress = "How goes the hunt, {class}?", completion = "Ah yes, this will do excellently. This will enable your weapons to strike with searing heat!", sourceObjectiveStatus = "unverified-source-field" }
quests[707] = { id = 707, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ironband Wants You!", description = "{name}.  I received reports from Prospector Ironband at his excavation site in Loch Modan--he needs some legwork done concerning another of our excavations.\n\nI don't have more details than that, but if you want to stretch your legs then go speak with Ironband.", sourceObjective = "Speak with Prospector Ironband at Ironband's Excavation Site in Loch Modan.", completion = "So Stormpike sent you, did he?  Good.\n\nI have a big task for you...", sourceObjectiveStatus = "unverified-source-field" }
quests[708] = { id = 708, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Black Box", description = "The surface of this metallic black box is heavily pitted, as if it had been immersed in acid - it must have been sitting in the giant condor's stomach for a long time.\n\nTurning the box over, a symbol is found stamped on its bottom.  Below the symbol are the words:\n\n\"Engine #19 - Ironforge Siege Brigade\"", sourceObjective = "Take the Corroded Black Box to the Hall of Arms in Ironforge.", sourceObjectiveStatus = "unverified-source-field" }
quests[709] = { id = 709, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Solution to Doom", description = "Oh my!  Oh my!  There is a doom approaching.  Mark me!  A doom!\n\nNo, I cannot speak of it...cannot utter their names or they may hear me!  But if we learn, yes, if we learn more of them...then maybe we can learn how to foil them!\n\nMaybe.\n\nGo into Uldaman.  No!  I said it!  You must find...find the tablet of...Ryun'eh.  Yes, find it!  And don't make me speak that name again!\n\nIt is deep in that place, in an ancient chest.  That's where it hides...in a chest crafted before the works of any dwarf.", sourceObjective = "Bring the Tablet of Ryun'eh to Theldurin the Lost.", progress = "Did you find the tablet?  It must hold secrets!  Secrets to save us!", completion = "Oh, fortune is with us!  Thank you!  We may yet be saved!", sourceObjectiveStatus = "unverified-source-field" }
quests[710] = { id = 710, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Study of the Elements: Rock", description = "Here in the Badlands I've stopped to work on my latest project: my shackles of elemental binding.\n\nWhen complete, they will allow mages to summon even more powerful elementals for use in even greater capacities. To start things off, I need small stone shards to test some of my newest offensive spells along with a few gizmos I've pieced together.\n\nThe shards are easily collected from the lesser rock elementals to the west of here. Could you bring me some?", sourceObjective = "Find 10 Small Stone Shards and bring them to Lotwil Veriatus in the Badlands.", progress = "This area's perfect for-- Could you hold these in place for a moment? Yes, just like that, along the vector normal. Now, what was I... Right. Perfect for testing my latest project. The raw materials, the open space... what more could an intelligent and enlightened practitioner of the arts ask for?", completion = "These shall do nicely, {name}. Thank you. Hmm, a bit more sand than I'd anticipated. Have to adjust the coefficient of friction. No, wait; it should still be negligible with the frost oil.", sourceObjectiveStatus = "unverified-source-field" }
quests[711] = { id = 711, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Study of the Elements: Rock", description = "{name}, you've already proven more able than all my apprentices combined.\n\nThe next parts I need require a little more strength. Large stone slabs can be found on rock elementals if you're careful enough. Their bodies are stronger and larger, and therefore more prone to having pieces large enough for my tests. You can find them further west of here or southeast along the mountains' edges.\n\nTake your time; I'll need a while to test these smaller pieces you brought me.", sourceObjective = "Bring 3 Large Stone Slabs to Lotwil Veriatus in the Badlands.", progress = "I'm most pleased, {name}. My spells affected the smaller pieces just as I predicted. If this experiment is as successful as I foresee, then the elementals I'll be able to control will put anything summoned prior to this to shame.", completion = "{name}, simply amazing! I would have thought it'd take half a dozen tauren to bring all these to me.", sourceObjectiveStatus = "unverified-source-field" }
quests[712] = { id = 712, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Study of the Elements: Rock", description = "{name}, there's one more part I need from the elementals here in the Badlands: the bracers of rock binding from the greater rock elementals. By my calculations, those bracers should be enough to gauge the strength of my own shackles.\n\nMy attempts at scrying the greater rock elementals showed a group of them southwest of here, near some ogres if I recall.\n\nBring me 5 of their bracers just so I have extras. Servo's notorious for misplacing my reagents and research.", sourceObjective = "Bring 5 Bracers of Rock Binding to Lotwil Veriatus in the Badlands.", progress = "The stone slabs you found were ideal, {name}. Lucien will be taking the extra ones back to Kharanos when we're done here. After all, they could prove useful again.\n\nFor instance, they'd be a nice basis for a handy little shelter once I start looking into a multidisciplinary approach to high-yield explosives...", completion = "{name}, have you ever considered becoming a research assistant? No? I'm not sure what I'll do without your abilities here. Intelligence, curiosity, and strength--all combined into one package.", sourceObjectiveStatus = "unverified-source-field" }
quests[713] = { id = 713, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Coolant Heads Prevail", description = "Let me tell you something about Frost Oil: nothing can keep an engine or gears from overheating quite like it.\n\nIts cooling properties are extraordinary, and its longevity as a lubricant without equal. That's not all: it also aids in retaining enchantments on magical items.\n\nI need a vial of it to increase the magical capacity of my shackles and make them powerful enough to stop our summoned friend from killing us all.\n\nBro'kin, a goblin friend of mine, can teach you to make it. He's in Alterac.", sourceObjective = "Find Frost Oil and bring it to Lotwil Veriatus in Badlands.", progress = "Have you found the oil I need? It would be so helpful if you were able to find some.", completion = "Stupendous! This should be the perfect coolant for my new bracers. If the enchantments don't last a century, then I'll give all my belongings to Servo.\n\nAll the mages of the Assembly will be in such awe after I finish this, {name}. You just wait and see.", sourceObjectiveStatus = "unverified-source-field" }
quests[714] = { id = 714, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gyro... What?", description = "{name}, you've done your job well beyond all standards.\n\n<Lotwil's obviously distracted by his work.>\n\nIf we ever meet in Kharanos, feel free to come apply for work.\n\nWhoops! Quick, grab the... yes, that. Thanks.\n\nNow I just need one more thing. It's a small part, but rather crucial, I'm afraid: a gyrochronatom.\n\nIf you could just go grab one and bring it to me, I should be ready to complete this.", sourceObjective = "Bring a Gyrochronatom to Lotwil Veriatus in the Badlands.", progress = "Yes, yes, yes. Just a moment.\n\n<Lotwil continues to work on some kind of contraption.>", completion = "HA!\n\n<Lotwil grabs the gyrochronatom from you.>\n\nPerfect... just about done. No, really. I AM almost done now. This project is my top priority... at the moment. Let me pop this into place, and you can see for yourself what you've helped me create. It'll just take me a few more minutes... maybe... possibly longer. Well, maybe a lot longer. We'll see...", sourceObjectiveStatus = "unverified-source-field" }
quests[715] = { id = 715, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liquid Stone", description = "I'm thinking those items you acquired for Lotwil are going to be the least of our worries, {name}. On the other hand, you've proven more than adept at the sciences Lotwil holds sacred, so how about helping me out?\n\nI need an invisibility potion and a healing potion; both might come in handy real soon if he pulls this off.\n\nIn return, I'll give you this recipe for a potion I've been developing while learning from Lotwil. It's based on some of the research he's been doing here in the Badlands.", sourceObjective = "Bring a Healing Potion and a Lesser Invisibility Potion to Lucien Tosselwrench in the Badlands.", progress = "He's getting closer to finishing. How are things going on your end?", completion = "YES!\n\nI mean, thank you, {name}. These will be helpful while traveling through the Badlands.", sourceObjectiveStatus = "unverified-source-field" }
quests[716] = { id = 716, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stone Is Better than Cloth", description = "I know how cheap Lotwil can be, {name}, so let me make you something for all your troubles. Maybe it'll even help protect you from the coming atrocity that is Lotwil's newest invention.\n\nI've been working with all the extra stones you collected for him, and I can make some nice bracers that you might want to use. They're enchanted, of course.\n\nI'll just need patterned bronze bracers crafted by a blacksmith so I can complete the bracers I'm making for you.", sourceObjective = "Bring some Patterned Bronze Bracers to Lucien Tosselwrench in the Badlands.", progress = "I wouldn't wait too long to get that bracer, {name}.\n\nWho knows what's going to happen next?", completion = "Here you go, {name}. Try these on.", sourceObjectiveStatus = "unverified-source-field" }
quests[717] = { id = 717, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tremors of the Earth", description = "It has become obvious that we cannot ensure that Blacklash and Hematus will remain imprisoned in Lethlor. That black dragons have taken up residence there, and that the ogres managed to steal the Sign indicates that more drastic measures will have to be taken.\n\nThe drakes' prison is maintained by three runestones that may only be retrieved using the Sign of the Earth. Those runestones can then be used to break the seal which imprisons them.\n\n{name}... assure that their dreams are eternal.", sourceObjective = "Use the Sign of the Earth to activate the Pillars of Amethyst, Opal, and Diamond and obtain the Runestones.\n\nPlace the runestones in the Seal of the Earth to free Blacklash and Hematus.\n\nSlay them and return Blacklash's Bindings, the Chains of Hematus, and the Sign of the Earth to Garek.", progress = "Strong magics and powers held the drakes' prison for so long, but we cannot allow any possibility that Blacklash and Hematus may be released.", completion = "No longer will the Kirin Tor need to worry over the prisoners of Lethlor. I will return to report success to my master. Krasus will no doubt be pleased.", sourceObjectiveStatus = "unverified-source-field" }
quests[718] = { id = 718, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mirages", description = "In our hurry to leave the Uldaman excavation site, we were forced to abandon many wagons and crates of supplies along the way. The local ogres from Camp Kosh have been on our abandoned equipment like vultures on a rotting corpse. Don't smell much better, either. Than the corpses, I mean.\n\nAnyways, they took the cart that was carrying all our weapons and such... so--well, this is a bit embarrassing--we haven't been able to get any food.\n\nWe're in a bit of a pickle here, suppose you could help us out?", sourceObjective = "Retrieve the Supply Crate for Sigrun Ironhew.", progress = "The desert's a bad place to be hungry, my friend, let me tell you that.\n\nHey... what's that over there...", completion = "Thanks so much, {name}. While you were gone, I... er... swallowed a mouthful of sand. It...\n\nWell, enough of that, we'll go out and get some food tonight. Eat like kings!", sourceObjectiveStatus = "unverified-source-field" }
quests[719] = { id = 719, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dwarf and His Tools", description = "Hey, {name}. Be careful 'round here. There be Dark Iron dwarves all around--looked like the Shadowforge clan.\n\nThey just attacked the excavation site I was workin' at--killed nearly everyone there, including my boss Hammertoe. I barely escaped with me life.\n\nThe site's just to the north of here, and I'm tryin' to plan a way to get some of our supplies back, especially me lucky pick.\n\nThink you'd be up to helpin' me out some? One of those damned Dark Iron must have my pick! Could be anyone of them.", sourceObjective = "Find Ryedol's Lucky Pick and return it to Prospector Ryedol south of Hammertoe's Dig Site.", progress = "Not sure what the Shadowforge were lookin' for, but they definitely had a purpose.", completion = "Ye're me savior, {class}. I'm glad someone could teach those Shadowforge a lesson or two. Thanks for yer help.", sourceObjectiveStatus = "unverified-source-field" }
quests[720] = { id = 720, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Sign of Hope", description = "<There is text roughly scribbled in chalk on the map.>\n\n\"Ryedol, \nThey're taking me to Uldaman. Send help.\n-Hammertoe\"", sourceObjective = "Find Prospector Ryedol and let him know Hammertoe Grez is alive.", completion = "Hammertoe's alive?! This is amazin', {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[721] = { id = 721, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Sign of Hope", description = "{name}, can ye find him? Can you find Hammertoe in Uldaman?\n\nIf those dirty Shadowforge are holdin' him hostage to figure out what he knows about the titan excavations, then all of Ironforge could be in huge trouble.\n\nFor a long time now those Dark Irons have been lookin' for magics to make more powerful golems. Hammertoe was doin' the same, of course, but only to stop them.\n\nThey're probably keepin' him alive until they learn what he knows.Ye've got to hurry if you're gonna save him!", sourceObjective = "Find Hammertoe Grez in Uldaman.", completion = "Yes? Ah'm sorry... <cough> Feel so weak. Can ye come closer, {class}?\n\nRyedol sent ye? Muradin be praised, that boy's not as slow in the head as I once thought.", sourceObjectiveStatus = "unverified-source-field" }
quests[722] = { id = 722, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amulet of Secrets", description = "Ye're brave... <cough>... to come into Uldaman fer me, {class}.\n\nIf ye're really here to help... ol' Hammertoe, then... <cough>... you'll need to find... me amulet.\n\nDeepshadow's got it... Magregan Deepshadow. He's 'round here... in the ruins fer sure. That amulet'll lead 'em... <cough>...  right to the scrolls if he ain't stopped. It's up to you, {name}. Please... get that amulet.\n\nThe scrolls will surely help the Dark Irons create even more powerful golems. I just know it. I can feel it in me bones.", sourceObjective = "Find Hammertoe's Amulet and return it to him in Uldaman.", progress = "The Shadowforge clan... <cough> is dangerous. Be careful. <cough> You must find the amulet.", completion = "Ha! <cough cough>\n\nAh knew you'd find me amulet, {name}.\n\n Well done indeed, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[723] = { id = 723, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prospect of Faith", description = "<Hammertoe holds his wounds and takes a moment to regain his composure before speaking again.>\n\nFind Ryedol, {name}. Bring 'im me amulet. <cough cough> He'll... <cough> figure out what to do. He knows I was seeking the origins of our people, and he... <cough>... knows it was also my mission to stop the Shadowforge clan. They must not be allowed to find the scrolls... <cough>", sourceObjective = "Take Hammertoe's Amulet to Prospector Ryedol in the Badlands.", progress = "I'd say it was a bad day, but this is the Badlands: every day's a bad day.", completion = "Hammertoe's amulet? I think my spirits were higher when I thought he was dead. Knowin' fer sure only makes the pain worse. This amulet was his life's work. I can't let his death be in vain.", sourceObjectiveStatus = "unverified-source-field" }
quests[724] = { id = 724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prospect of Faith", description = "Okay, okay... who would know what to do?\n\nHistorian Karnik! That's it!\n\nHe's in Ironforge. He'll be able to help. He and Hammertoe were workin' together to find the lost artifacts in Uldaman.\n\nGuess the Shadowforge found out the two of them knew more than they were lettin' on.\n\nTell Karnik what's happened to Hammertoe and give him the amulet--he'll tell you what needs to be done next.", sourceObjective = "Take Hammertoe's Amulet to Historian Karnik in Ironforge.", progress = "Ah, yes. Another traveler seeking something from the dwarves.\n\nSir, I'm truly sorry, but I've no time to answer meaningless questions right now.", completion = "Oh! Well, this is a different matter entirely. You probably don't realize the gravity of this matter yet, do you?\n\nI care deeply about Hammertoe's demise, but if he sent you here with his amulet, then he understood what's at stake.\n\nWe will have to take time to mourn his death later.\n\nLet me show you one of the reasons this amulet is so valuable.", sourceObjectiveStatus = "unverified-source-field" }
quests[725] = { id = 725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Passing Word of a Threat", description = "{name}, run and find Advisor Belgrum as quickly as you can. Tell him what you've witnessed and ask him how he wants us to proceed. This note will explain more to him.\n\nIn the meantime, I will take the time to speak to Hammertoe's spirit. Maybe he knows something that will help us put a stop to those Shadowforge cretins' activities in the Badlands. We can only pray.", sourceObjective = "Find Advisor Belgrum and give him his note.", progress = "Hmm? Yes, {class}.", completion = "Ah, word from Historian Karnik. Excellent.\n\nI always have time for his business.\n\n<Advisor Belgrum opens the note and begins to read.>", sourceObjectiveStatus = "unverified-source-field" }
quests[726] = { id = 726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Passing Word of a Threat", description = "<Advisor Belgrum reaches the end of the note, and his eyes widen for a moment.>\n\nOch, these are evil tidings.\n\n{name}, please return to Historian Karnik and tell him on the king's authority to act on this information swiftly and decisively. He must halt the Shadowforge's activities in the Badlands.", sourceObjective = "Speak to Historian Karnik.", completion = "You're treating this matter with an urgency I'd expect from the king himself, {name}.\n\nAll right, then. I know what'll bring the Shadowforge down.\n\nTheir presence in Uldaman can be slowed if we strike them at their base of operations: Angor Fortress.", sourceObjectiveStatus = "unverified-source-field" }
quests[727] = { id = 727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Ironforge for Yagyin's Digest", description = "The Tablet tells much.  But not enough!  Not nearly enough!\n\nThere is a book, a digest that Yagyin wrote in ages past.  The ... people I fled ... they keep this book in many places.  And their most learned study it.  It holds vast knowledge.  Knowledge to protect us!\n\nGo to Gerrig Bonegrip.  He is in a shop in Ironforge, in the Forlorn Cavern.  Show him this sigil and he'll think you one of them.  Ask him for Yagyin's Digest ... and bring it to me!", sourceObjective = "Give the Sigil of the Hammer to Gerrig Bonegrip in the Forlorn Cavern of Ironforge.", progress = "Hello.  Welcome to my shop, but watch what you touch.\n\nKnowledge can be deadly.", completion = "Oh.  Greetings, brother.\n\nAnd praise to the dwellers beneath.", sourceObjectiveStatus = "unverified-source-field" }
quests[728] = { id = 728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Undercity for Yagyin's Digest", description = "The tablet tells much.  But not enough!  Not nearly enough!\n\nThere is a book, a digest that Yagyin wrote in ages past.  The... people I fled from... they keep this book in many places.  And their most learned study it.  It holds vast knowledge.  Knowledge to protect us!\n\nGo to Keeper Bel'dugur in the Undercity of Lordaeron.  Show him this sigil and he'll think you one of them.  Ask him for Yagin's Digest...and bring it to me!", sourceObjective = "Bring the Sigil of the Hammer to Keeper Bel'dugur in the Undercity.", progress = "Ah, we have an eager {class}, I see.  Are you here to learn from my collection?  Good!\n\nBut be warned: just as knowledge gives power to the strong...it will drive the weak mad.", completion = "Be discrete with your signs, {class}. There are those who do not believe the righteousness of our pledge.\n\nAnd there are those who would see us fail if they knew of us.\n\nWe must always be careful.  And watchful.  And patient.", sourceObjectiveStatus = "unverified-source-field" }
quests[729] = { id = 729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Absent Minded Prospector", description = "What an honor it was when Master Greywhisker assigned me to work under the guidance of the great Prospector Remtravel. At the academy in Ironforge everyone knew of Remtravel's great discoveries.\n\nBut the prospector is rather... um... oblivious ...to his surroundings.\n\nWe had uncovered evidence of a great society. Horrible golems sprang forth from the ground and overran the site. Remtravel never seemed to notice. I ran back to Auberdine for help.\n\nPlease travel south and see if the prospector is okay!", sourceObjective = "Travel south and check on Prospector Remtravel.", completion = "Hollee, is that you? I need some help chiseling this stone. Hand me my stone brush, I think I see something.\n\nHey, you're not Hollee! Don't suppose you've seen my stone brush?\n\nNever mind that now! I promised the League I'd send the mysterious fossil I found. Where did Hollee go?\n\nSo much work to be done! Now where is that mysterious fossil... and my brush... and Hollee...\n\nAnd who are you... 'tis no matter, so long as you're here to help.\n\nLet me know when you're ready to start looking.", sourceObjectiveStatus = "unverified-source-field" }
quests[730] = { id = 730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble In Darkshore?", description = "How nice it is to see a {class} interested in the great archeological wonders of our world.\n\nOftentimes our work is dismissed as mere hobby by our friends in the Alliance. But what many fail to realize is that recent discoveries in Khaz Modan have proven that a great and powerful force threatens all of Azeroth, from Lordaeron to Kalimdor.\n\nI am most worried about my crew that I sent to Darkshore. They haven't sent word in weeks.\n\nTravel to Auberdine and look for a clue as to their whereabouts.", sourceObjective = "Travel to Auberdine and look for signs of the dwarven excavation team.", completion = "I'm so glad Chief Archeologist Greywhisker sent for us....", sourceObjectiveStatus = "unverified-source-field" }
quests[731] = { id = 731, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Absent Minded Prospector", description = "So then, Hollee... oh that's right, you are not Hollee. Where's Hollee?\n\nBah, that's beside the point. We must find that stone brush... I mean the mysterious fossil! We must find that fossil. The Explorers' League in Darnassus will want some indication as to what I've been doing.\n\nLet me know when you are ready and we will hunt down that brush.... I mean fossil! We shall find something in writing to satisfy the League.\n\nSo are you ready yet?", sourceObjective = "Protect Prospector Remtravel as he searches for the mysterious fossil, then return to Archaeologist Hollee in Auberdine.", completion = "Thank the stars Prospector Remtravel is safe! I told you he was absent minded. I can't believe he insisted on staying there with all of those horrible creatures lurking about.", sourceObjectiveStatus = "unverified-source-field" }
quests[732] = { id = 732, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tremors of the Earth", description = "I heard from Sigrun that you have been a great help to him. Perhaps I might enlist your help. I was sent here by my master, Krasus of the Kirin Tor, to put an end to the trouble brewing in Lethlor Ravine.\n\nI cannot divulge the exact nature of my assignment here or the tasks that I must undertake, but be assured it is of vital importance.\n\nA band of wandering ogres, sometimes seen near Camp Boff, stole an object called the Sign of the Earth; I must have it. Bring it to me, and I will tell you more.", sourceObjective = "Retrieve the Sign of the Earth for Garek.", progress = "The nomadic band of ogres travels between their camps across the Badlands; heat rising from the dry earth and the swirling winds will make it difficult to track their progress.  I have heard that sometimes they travel through Camp Boff.  If you are lost, you might try your search there.", completion = "Good tidings you bring bearing the Sign, {name}. The Sign of the Earth was created by the Dark Iron dwarves of Angor Fortress to bind two of Deathwing's ruthless lieutenants, the twins Blacklash and Hematus.", sourceObjectiveStatus = "unverified-source-field" }
quests[733] = { id = 733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scrounging", description = "It's going to be tough going here if I can't manage to scrounge up some materials to construct some defenses and other necessities. I've noticed that the ogres in the area seem to be well equipped with scrap metal. Maybe the stories of siege engines in the Badlands weren't so far off after all...\n\nAnyways, the Prospector's been getting worried about the state of our little camp, so I'd like to get working soon if I can.\n\nThe main ogre camp is at Dustbelch Grotto, a good trek to the west of here.", sourceObjective = "Get 7 pieces of Scrap Metal for Sigrun.", progress = "Well, I've made do with what I could, but... it's not much. Have you found any more supplies?", completion = "It's a start, {name}, and it'll have to do until we hear word from Ironforge or the Explorers' League.\n\nNow, if only I could find some salt somewhere for my quenching barrel...", sourceObjectiveStatus = "unverified-source-field" }
quests[734] = { id = 734, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Is Going to Be Hard", description = "Wonderful, wonderful.\n\n<Lotwil looks up at you for a moment before going back to his shackles.>\n\nGo speak to Lucien, {name}. I need a cog #5. Bring it to me, will you?", sourceObjective = "Speak to Lucien Tosselwrench in the Badlands.", completion = "Cog #5, huh? Yeah, this isn't going to be good.", sourceObjectiveStatus = "unverified-source-field" }
quests[735] = { id = 735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Star, the Hand and the Heart", description = "Yagyin's Digest, eh?  Are you starting a new chapter of us, somewhere?  Never mind, it is not my place to ask.\n\nI will help you, for I have an extra copy.  We must aid each other, yes?  That is how we flourish.\n\nI require three items of power.  Bring them to me and I will give you the digest.\n\nI will not speak their names.  Ears may be on us.  But here, I will write them down.", sourceObjective = "Return the items on the Bonegrip's Note to Gerrig Bonegrip in Ironforge.", progress = "Do you have the relics for which I asked?", completion = "You are resourceful, {class}.  If it truly is your charge to begin a new chapter of our order, then I believe you will run it well.", sourceObjectiveStatus = "unverified-source-field" }
quests[736] = { id = 736, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Star, the Hand and the Heart", description = "You need Yagyin's Digest?  Your plan, then, is to gather another flock?  Of course it is...and of course I will help you, <brother/sister>.\n\nBut you must help me too.\n\nI require three items of power.  Bring me these and the digest will be yours.\n\nI cannot utter the names of these items, but I will write them down.\n\nGet me the items on this list.  If you can do that, then you are truly worthy of opening your own chapter of our order.", sourceObjective = "Bring the items on Bel'dugur's Note to Keeper Bel'dugur in the Undercity.", progress = "How goes your mission, {class}.", completion = "I am impressed!  You possess great skill, or great fortune, to have gained these relics.  Either way, you are an asset to us.", sourceObjectiveStatus = "unverified-source-field" }
quests[737] = { id = 737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forbidden Knowledge", description = "I have the digest for you, {name}.  I need not tell you to take great care with it.  And to keep it far from unfriendly hands.  \n\nThis book holds many truths...\n\n...And the truth can burn.", sourceObjective = "Bring Yagyin's Digest to Theldurin.", progress = "Ho!  You were gone a long time.  Did you get the digest?", completion = "You got it!  Oh, hope glimmers!\n\nYour efforts may yet save us, {name}.  A monument they should make of you!  A shrine they should build!  May your name be praised until your grandchildren have grandchildren!\n\nUnless...THEY are freed and rise to the surface.   If that happens then you can forget about children.\n\nIf THEY are freed, then we're all worm food.", sourceObjectiveStatus = "unverified-source-field" }
quests[738] = { id = 738, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Find Agmond", description = "Prospector Agmond was in charge of our excavation sites in the Badlands, to the southwest.  I say \"was\" because...well, I haven't heard from him in weeks.  I need you to find Agmond so I can get his report.\n\nLast I heard Agmond was at the southernmost dig site in the Badlands--a tiny operation past the Angor Fortress.  I'd start your search for him there.", sourceObjective = "Find Agmond.", completion = "This skeleton must be the unfortunate remains of Agmond.  His body is broken and battered, and his bones picked clean.", sourceObjectiveStatus = "unverified-source-field" }
quests[739] = { id = 739, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Murdaloc", description = "Agmond's tracks lead from the west.  It is easy to tell from the bloody smears across rock and sand that the dwarf crawled some distance.\n\nAnd here he died.\n\nUpon close inspection, the word \"Murdaloc\" is roughly scrawled in a patch of Badlands sandstone.\n\nScrawled next to Agmond's dead hand.", sourceObjective = "Slay Agmond's killer, Murdaloc.\n\nSlay 12 Stonevault Bonesnappers.\n\nReport to Prospector Ironband in Loch Modan.", completion = "This is sobering news, {name}.  But Agmond had a strong arm and a fierce hammer-swing, and his skull was as thick as they come!  Although he was killed by those cursed troggs I'm sure he took a lot of them down with him.", sourceObjectiveStatus = "unverified-source-field" }
quests[741] = { id = 741, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Absent Minded Prospector", description = "So the prospector wants to send the mysterious fossil to the Explorers' League in Darnassus? I don't feel right leaving Darkshore without him.\n\nHere, {name}, deliver the mysterious fossil to Chief Archaeologist Greywhisker in Darnassus.", sourceObjective = "Take the mysterious fossil to Chief Archaeologist Greywhisker in Darnassus.", progress = "What can I do for you, {race}?", completion = "Oh my! Leave it to Prospector Remtravel to discover such a find!", sourceObjectiveStatus = "unverified-source-field" }
quests[742] = { id = 742, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ashenvale Hunt", description = "Attention, young adventurers!  The wilds of Ashenvale await you!\n\nThe Horde has established a strong presence in the lands north of the Barrens.  Our two outposts - Splintertree Post and the Zoram Strand Outpost - strive to bring glory to the Horde!  Those who would prove themselves should seek out guidance there.  Of note: Senani Thunderheart in Splintertree Post, directly north of the Barrens, seeks adventurers willing to take part in a great hunt of Ashenvale!", sourceObjective = "Speak with Senani Thunderheart at Splintertree Post, Ashenvale.", completion = "Welcome to the new frontier, {name}.  Ashenvale is a land of opportunity, one where a young {class} like yourself is able to find boundless chances to prove their mettle.  Look around the outpost here, and be sure to travel out to the Zoram Strand, as the Horde has another outpost there as well.\n\nYour presence here tells me that you've come to learn more about the hunt.  Listen close, and I will gladly share with you what you need to know.", sourceObjectiveStatus = "unverified-source-field" }
quests[743] = { id = 743, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dangers of the Windfury", description = "Thank you for taking the time to speak to me, {name}. I am Ruul, warrior and teacher.\n\nYou have obviously reached an age when you must prepare for your trials if you are to adventure much further out of Mulgore.\n\nIf you wish a test of your strength, start by seeking out the Windfury harpies to the southeast. They nestle along the mountain's edges away from the road.\n\nThey are one of our natural enemies here in Mulgore and will be a good gauge of your skill.", sourceObjective = "Bring 8 Windfury Talons to Ruul Eagletalon in Bloodhoof Village.", progress = "The Windfuries are deadly foes. Their strength in battle is only rivaled by their desire for fresh meat.", completion = "You have done well, {name}. You seem well prepared to travel onward. Let the wind always be at your back.", sourceObjectiveStatus = "unverified-source-field" }
quests[744] = { id = 744, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preparation for Ceremony", description = "{name}, my brother soon stands before Chief Bloodhoof, and it is my honor to make his headdress for him.\n\nI want to ask a favor of you while I finish tanning these leather straps. There is not time for me to find enough feathers, and I was wondering, would you gather more for me?\n\nYou can find feathers of the correct size from the harpies residing far to the north and northwest of Thunder Bluff. I need only 6 azure and 6 bronze feathers to complete the design.", sourceObjective = "Collect 6 Azure Feathers and 6 Bronze Feathers, and bring them to Eyahn Eagletalon in Thunder Bluff.", progress = "This headdress will certainly be a wonderful gift for my brother.", completion = "Thank you for your help, {name}.\n\nMy part in my brother's ceremony is almost complete. Giving him his headdress and witnessing the ceremony are all my duty requires of me.", sourceObjectiveStatus = "unverified-source-field" }
quests[745] = { id = 745, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sharing the Land", description = "{name}, there are many conflicts that wound this land. It is my hope that you will not bear witness to as many of them as I have. Yet there is one that I would ask you to seek out. It will give you some sense of how terrible, if left unchecked, even a small threat can be to the land.\n\nPalemane gnolls have settled to the south of Bloodhoof and in a cave to the west. They disrespect our attempts to communicate with them, and they slay the wildlife of Mulgore unbridled.\n\nWords are no longer the answer.", sourceObjective = "Kill 10 Palemane Tanners, 8 Palemane Skinners, and 5 Palemane Poachers, then return to Baine Bloodhoof in Bloodhoof Village.", completion = "{name}, it is good you've taken my task seriously. Respect of the land and its creatures is important. Death and life are a circle... a necessity. One cannot exist without the other. Take time to ponder this and do well to never forget it.", sourceObjectiveStatus = "unverified-source-field" }
quests[746] = { id = 746, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dwarven Digging", description = "There are dwarves preparing a dig site to the northwest.  They think secrets lie in the earth, and that is true, but hollowing and defiling the land is no way to earn its teachings.\n\nCollect the dwarven tools of digging, smash them, and return to me with the dwarves' broken tools.\n\nYou can smash the tools at a forge.  You will find one in Thunder Bluff, but any forge -- even a forge at the dwarven camp -- will suffice.", sourceObjective = "Collect 5 Prospector's Picks.\n\nAt a forge, smash the Prospector's Picks to create Broken Tools.\n\nBring 5 Broken Tools to Baine Bloodhoof in Bloodhoof Village.", progress = "Hello, {name}.  Do you have the Broken Tools?  The dwarves' digging will enrage the kodos of Mulgore.  This defilement must be stopped!", completion = "Thank you, {name}.  This will calm the beasts of Mulgore.  And, spirits willing, it will teach the dwarves that hollowing the land is not the path to knowledge.", sourceObjectiveStatus = "unverified-source-field" }
quests[747] = { id = 747, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hunt Begins", description = "You have a promising air about you, and will prove yourself to the tribe. Perhaps someday soon you will be welcomed into the great city of Thunder Bluff. But before that can happen you must prove yourself to my father, Chief Hawkwind.\n\nUp here on Red Cloud Mesa we pride ourselves on keen hunting skills. Tauren hunt out of necessity and for sport. Our supply of meats has run low and we require feathers for clothing. Hunt the nearby plainstriders and prove yourself by resupplying the village.", sourceObjective = "Grull Hawkwind in Camp Narache wants you to bring him 7 Plainstrider Feathers and 7 pieces of Plainstrider Meat.", progress = "Providing meat and feathers for the tribe is the first step in proving yourself as a hunter before the Chief.", completion = "The {race} of Narache thank you, {name}. You show much promise.", sourceObjectiveStatus = "unverified-source-field" }
quests[748] = { id = 748, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Poison Water", description = "Goblins and their servants have tainted our sacred water wells!  We cannot allow this.\n\nTo cleanse each well, I must create a cleansing totem, then you must bring the totem to the well and perform a cleansing ritual.\n\nFirst we will create a cleansing totem for the Winterhoof Water Well.  To do this, the land must offer its aid. Hunt prairie wolves for their paws and adult plainstriders for their talons.  They are to the southwest.\n\nReturn to me with the paws and talons, {name}.", sourceObjective = "Bring 6 Prairie Wolf Paws and 4 Plainstrider Talons to Mull Thunderhorn in Bloodhoof.", progress = "Do you have the paws and talons, {name}?", completion = "You have done well, {name}.  I will take these and bind their power into a totem of cleansing.", sourceObjectiveStatus = "unverified-source-field" }
quests[749] = { id = 749, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ravaged Caravan", description = "A few days ago, we found a Venture Co. caravan traveling under guard on the northern shore of Stonebull Lake. We'd lost two of our number in an earlier battle, so we were quick to attack and lay waste to the caravan.\n\nWe left their supply crates, thinking that our torches would destroy anything of value, but given that Venture Co. salvagers have been spotted near the burned wagons, maybe we were wrong.\n\nPerhaps you could go to the caravan and examine the contents of the crates.", sourceObjective = "Morin Cloudstalker wants you to examine the contents of a supply crate at the Ravaged Caravan.", completion = "All sides of the crate are stamped with the sign of the Venture Co. Mining Division. Notes printed carefully on the side of the carton indicate that the contents are due for processing at one of their central plants.", sourceObjectiveStatus = "unverified-source-field" }
quests[750] = { id = 750, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hunt Continues", description = "A tauren skilled in the ways of the hunt knows that his prey is not for mere trophy. The beasts of the plains provide us with a means of survival. You will make quite an impression on the elders if you can bring back some highly valued Mountain Cougar Pelts. You can find the beasts lurking in the hills to the south.\n\nOur children need clothing and our tents need mending.", sourceObjective = "Grull Hawkwind in Camp Narache wants you to bring him 10 Mountain Cougar Pelts.", progress = "If you can provide pelts for the tribe I will pass word along to my father, Chief Hawkwind, of your generous deeds.", completion = "The {race} of Narache thank you for these provisions, {name}. With your skill in the ways of the hunt you will surely be revered in Thunder Bluff someday.", sourceObjectiveStatus = "unverified-source-field" }
quests[751] = { id = 751, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ravaged Caravan", description = "Prying open the lid reveals a tightly packed assortment of ore and minerals, more evidence of the Venture Co.'s mining operation in Mulgore. On the top of the ore and minerals you remove a tightly bound sheaf of papers.\n\nUp in the foothills to the east, you can barely hear the sounds of work, and see smoke rising from a large fire.", sourceObjective = "Return the Venture Co. Documents to Morin Cloudstalker near Bloodhoof Village.", progress = "Hail, {name}. Have you learned anything new about the Venture Co.'s plans and operations in our homeland?\n\nIf they plan to exploit our lands as they have others, the Outrunners will be quick to put an end to it.", completion = "It does indeed appear that the Venture Co. is attempting to rob us of our natural resources. It is good to know this for true, and now it seems, we must do something about it.", sourceObjectiveStatus = "unverified-source-field" }
quests[752] = { id = 752, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Humble Task", description = "All members of the tribe share in the harmony of life. We live together and work together.\n\nOur commitment to one another carries with it a high degree of responsibility. I ask of you now a humble task.\n\nMy mother set out this morning to fetch water from the well to the southeast of Narache. It has been quite some time now. Perhaps you could check on her for me while I attend to tribal matters here?", sourceObjective = "Chief Hawkwind wants you to search for his mother near the water well to the southeast of Camp Narache.", completion = "You traveled all this way just to help an old woman? My my, aren't you a keeper?", sourceObjectiveStatus = "unverified-source-field" }
quests[753] = { id = 753, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Humble Task", description = "I have traveled many paths through life and these old legs lack the vigor they once had. I can still perform my duties to the tribe. Sometimes it just takes an old woman a little longer to do the task.\n\nBut you look like an eager {class}. Let's put some of that youthful vitality to the test. Take a water pitcher from the well and bring it to my son, the Chief, in Camp Narache.\n\nRemember that even the most humble task can gain the recognition of elders.", sourceObjective = "Take a Water Pitcher from the water well.\n\nReturn the pitcher to Chief Hawkwind in Camp Narache which is northwest from the water well.", progress = "You look as though you have returned from the plains. Do you have any word from Greatmother Hawkwind?", completion = "You carried this pitcher back at the Greatmother's bidding, I see.\n\nYour willingness to help others and provide for the {race} of Camp Narache leads me to believe you would make the tribe proud in Thunder Bluff someday.", sourceObjectiveStatus = "unverified-source-field" }
quests[754] = { id = 754, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winterhoof Cleansing", description = "I have crafted the totem to cleanse the Winterhoof Water Well.  Now, you must take it to the well and perform a cleansing ritual.  You will find it to the southeast, guarded by foul goblins!\n\nThis will not be an easy task, but you must do it if we are ever to use its waters again.\n\nFortune to you, {name}.", sourceObjective = "Use the Winterhoof Cleansing Totem at the Winterhoof Water Well, then return to Mull Thunderhorn.", progress = "Do not delay, {name}.  The Winterhoof Well's taint must be removed!", completion = "News of your deed reached me moments ago -- already the beasts near the well drink from it eagerly.\n\nYou have done a great thing for the land, {name}.  And you have done a great thing for the {race} people.", sourceObjectiveStatus = "unverified-source-field" }
quests[755] = { id = 755, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rites of the Earthmother", description = "Your willingness to perform a humble task for the tauren of Narache and your eagerness to learn are noble traits, {name}. I believe one day you will be heralded in Thunder Bluff as a {class} of greatness.\n\nBefore that you must embark on the Rites of the Earthmother, of which there are three.\n\nThe first test is the Rite of Strength. Travel to Seer Graytongue and tell him Chief Hawkwind has sent you.\n\nYou will find the seer's abode directly to the south of Camp Narache, tucked away in the hills.", sourceObjective = "Travel to Seer Graytongue who lives in the hills directly south of Camp Narache.", completion = "Chief Hawkwind sent you? Embarking on the Rites of the Earthmother is no small task...", sourceObjectiveStatus = "unverified-source-field" }
quests[756] = { id = 756, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thunderhorn Totem", description = "To create the Thunderhorn Cleansing Totem, you must gather the claws of the predators of the Mulgore plains.  Hunt prairie stalkers for their stalker claws and flatland cougars for their cougar claws, then return to me.\n\nYou will find the prairie stalkers and flatland cougars to the east and west.", sourceObjective = "Bring 6 Stalker Claws and 6 Cougar Claws to Mull Thunderhorn.", progress = "{name}, do you have the claws I sent you to gather?  The Thunderhorn Water Well grows more tainted with each passing hour!", completion = "Thank you, {name}.  The purity with which these beasts hunt is vital in the creation of the next cleansing totem.\n\nThe goblins will never learn the difference between contending with the land, and living in harmony with it.", sourceObjectiveStatus = "unverified-source-field" }
quests[757] = { id = 757, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rite of Strength", description = "The Rites of the Earthmother are the steps a young tauren needs to take to gain respect in Thunder Bluff.\n\nFirst you must pass the Rite of Strength. In this test you must prove your bravery by slaying enemies of the tribe.\n\nBristlebacks of Brambleblade Ravine to the east are encroaching on our tribal lands. They ambush our hunting parties and steal from the village by dark.\n\nShow your valor by slaying these villains and return to the Chief in Camp Narache with their belts as proof of your deeds.", sourceObjective = "Kill Bristlebacks in Brambleblade Ravine and bring 12 Bristleback Belts to Chief Hawkwind in Camp Narache.", progress = "Have you completed the Rite of Strength, {name}? I require proof of your valor against the enemy of our tribe, the Bristlebacks.", completion = "You have passed the first test of the Rites of the Earthmother. The tribe will be proud.", sourceObjectiveStatus = "unverified-source-field" }
quests[758] = { id = 758, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thunderhorn Cleansing", description = "The totem is ready, {name}.  And again, it is your task to perform the ritual of cleansing.\n\nGo to the Thunderhorn Water Well, north of the village, and use the Thunderhorn Cleansing Totem in your ritual.  After you do this, return to me.\n\nMay the spirits guide you.", sourceObjective = "Use the Thunderhorn Cleansing Totem at the Thunderhorn Water Well, then return to Mull.", progress = "The Thunderhorn Water Well is still tainted, {name}.  Please, you must perform the ritual!", completion = "Ancestors of the Thunderhorn clan spoke to me in a dream, praising you for your actions near their well.\n\nFor their gratitude, they wish to give you this...", sourceObjectiveStatus = "unverified-source-field" }
quests[759] = { id = 759, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildmane Totem", description = "There is but one water well left to cleanse, named after the Wildmane clan.  For this well to be pure, the land must offer the teeth of a fierce predator, the prairie wolf alpha.  Find the alphas to the north, then return to me when your hunt is finished.\n\nAlphas often wander around the base of our mighty city, Thunder Bluff.", sourceObjective = "Bring 8 Prairie Alpha Teeth to Mull Thunderhorn in Bloodhoof Village.", progress = "{name}.  Do you have the teeth I asked for?", completion = "Very good, {name}.  I can feel the sacrifice of the land in this offering, and my spirit swells with sadness, and pride.", sourceObjectiveStatus = "unverified-source-field" }
quests[760] = { id = 760, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildmane Cleansing", description = "Your cleansing of the Winterhoof and Thunderhorn wells is spoken among the spirits, young {name}.  The Wildmane Totem is made, and your last task lies ahead.\n\nThe Wildmane Water Well lies north of Thunder Bluff.  Perform the ritual!  Heal the land of the goblins' poisons!  Let clean water flow once again!", sourceObjective = "Use the Wildmane Cleansing Totem at the Wildmane Water Well, then return to Mull Thunderhorn.", progress = "The last water well remains fetid and poisonous, {name}.  You must not delay!", completion = "You've done it.  You have cleaned the wells, and healed our land.  Bloodhoof village is grateful, {name}.\n\nMay the wind whisper your deeds for a hundred seasons, and may the waters of Mulgore remain clean forever.", sourceObjectiveStatus = "unverified-source-field" }
quests[761] = { id = 761, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Swoop Hunting", description = "The swoop is a cunning bird, and difficult to find and hunt.  A collection of Swoop Quills is a badge of cleverness and determination for a hunter.\n\nIf you are willing to take up this task, then enter the plains and hunt the swoop.\n\nBring me their quills, and bring honor to your clan.\n\nThe swoops may be found anywhere in Mulgore, but your eyes must be sharp to spot them, and your hooves must be quick to catch them.", sourceObjective = "Bring 8 Trophy Swoop Quills to Harken Windtotem in Bloodhoof Village.", progress = "Have you found the swoops, {name}.  Do you have their quills?", completion = "I know that gathering these quills was not an easy task, {name}.  In doing this, you prove that you are a {class} of merit.  It is good to have you at Bloodhoof Village.", sourceObjectiveStatus = "unverified-source-field" }
quests[762] = { id = 762, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Ambassador of Evil", description = "Ambassador Infernus was sent to Angor Fortress by Ragnaros himself to mind the Shadowforge seeking lost artifacts in Uldaman.\n\nIt has already meant tremendous casualties for our people, but it has obviously grown worse. I hesitate to guess how many artifacts they would be able to find and use against Ironforge.\n\nOur goal is simple, {class}. Return to the Badlands and destroy Ambassador Infernus. Once the threat is eliminated, return to Advisor Belgrum with proof of your victory.\n\nIt is in your hands now.", sourceObjective = "Kill Ambassador Infernus in Angor Fortress and bring proof of his death to Advisor Belgrum in Ironforge.", progress = "Time is of the essence, {name}. Ragnaros will not wait for us to prepare.", completion = "{name}, your dedication to Ironforge and to the dwarven people cannot be refuted. I thank you for your help in this matter.\n\nI shall send word to Historian Karnik informing him that you have succeeded, and I shall also have aid sent to the Badlands as soon as possible to help recover the excavation site. Thank you again.\n\nBefore you go, there is one more thing I would ask of you in the name of King Bronzebeard.", sourceObjectiveStatus = "unverified-source-field" }
quests[763] = { id = 763, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rites of the Earthmother", description = "For you to continue with the Rites of the Earthmother you must pass two more tests. It is time for you to broaden your experience, {name}.\n\nTravel to Bloodhoof Village and seek out the Chief, Baine Bloodhoof, son of Cairne. There you may continue your journey and earn the acceptance of the elders of Thunder Bluff.\n\nTake this totem to Baine. He will recognize my carvings and help you on your path.\n\nFollow the road out of Camp Narache and travel with haste. Do not stray or you will lose your way.", sourceObjective = "Take the Totem of Hawkwind to Baine Bloodhoof in Bloodhoof Village. Follow the road out of Camp Narache.", progress = "What brings you to my village, {class}?", completion = "Word from my good friend, Chief Hawkwind! Ah, I can see by his carvings you are of a special breed.", sourceObjectiveStatus = "unverified-source-field" }
quests[764] = { id = 764, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Venture Co.", description = "This explains the buildup of Venture Co. employees and equipment we've seen in Mulgore. Those goblins... their company is expanding too quickly for their own good. It's how they say, show a goblin something, and you can hear the scales in the background.\n\nGreedy little things, they are. Unfortunately for their business enterprise, we tauren cannot allow them to conduct their operations in our lands. Go to their mine northeast of the ravaged caravan and send them a message.", sourceObjective = "Kill 14 Venture Co. Workers and 6 Venture Co. Supervisors for Morin Cloudstalker at Bloodhoof Village.", progress = "The Venture Co. was refused mining rights here in Mulgore, but it would seem that they do not take no for an answer. We {race} are not ones to mince words, however, and we have other ways of getting our message across.", completion = "I don't think there could be too much misinterpreting or ignoring of that signal, hm? The Venture Co. will know not to take the {race} lightly, or to be so arrogant as to believe we would allow them to steal the natural resources around us without protest.", sourceObjectiveStatus = "unverified-source-field" }
quests[765] = { id = 765, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supervisor Fizsprocket", description = "According to the documents you salvaged from the caravan, the Venture Co. created many plans to attempt to drive us from our lands here, so that they could have free reign to plunder our lands.\n\nThe depths that they would sink to accomplish their goals disgusts and appalls me. I want the mastermind behind their plans killed. His name is Supervisor Fizsprocket, you will find him at the Venture Co. mine east of the ravaged caravan. Bring me his clipboard, we shall see if we find out anything useful.", sourceObjective = "Kill Supervisor Fizsprocket and return his clipboard to Morin Cloudstalker at Bloodhoof Village.", progress = "I seethe with anger at the thought of the atrocities the Venture Co. is willing to perpetrate against us in the name of profit.", completion = "My anger is somewhat lessened at the news that the villain Fizsprocket is dead. I will go through his personal effects and see if there is any additional information about what the Venture Co. has planned for the future. Thank you for your efforts, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[766] = { id = 766, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mazzranache", description = "My grandfather told me stories about his battles with a strider named Mazzranache. He told me of its demonic red eyes, razor-sharp talons and venomous bite.\n\nAs fortune would have it, while traveling across the plains, I encountered it, and it took a nasty bite from my shoulder. He was as terrible as my grandfather described. I will need some hard-to-find animal parts to clean the infection from his bite: a wolf heart, cougar femur, plainstrider scale and swoop gizzard.\n\nHurry, time is of the essence.", sourceObjective = "Bring a Prairie Wolf Heart, Flatland Cougar Femur, Plainstrider Scale and Swoop Gizzard to Maur Raincaller at Bloodhoof Village.", progress = "My fever grows worse and I find my mind drifting into delirious nightmares... I should have known that I wouldn't be able to handle a beast my grandfather was unable to defeat...\n\nDo you have the ingredients for the remedy? I fear if I do not clean the infection soon, it will be the death of me.", completion = "Ah, thank you, {name}. Using the items you brought me, I will be able to create the remedy I need to stop the spread of the infection and, eventually, cure it completely. I owe you my life in thanks.\n\nBut I'll never forget that screeching call when Mazzranache came upon me, the blaze of color as its beak descended...\n\nBe wary on your travels.", sourceObjectiveStatus = "unverified-source-field" }
quests[767] = { id = 767, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rite of Vision", description = "The Rite of Vision, one of the Rites of the Earthmother, will help guide you toward earning the respect of the elders of Thunder Bluff.\n\nOur people have learned that the land is our most holy provider. In order to take part in the ritualistic vision, you must speak with the spiritual leader of the village, Zarlman Two-Moons.", sourceObjective = "Speak with Zarlman Two-Moons in Bloodhoof Village.", completion = "I sensed you would be coming to me, {class}. I can always recognize one who is trying to pass the Rites of the Earthmother.", sourceObjectiveStatus = "unverified-source-field" }
quests[768] = { id = 768, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gathering Leather", description = "Greetings, young one.  You have a gleam in your eye; I can tell you are eager to venture back to the plains for the hunt.  May you bring honor to your clan!\n\nI work with the skins of beasts, fashioning them into clothes and armor for the people of Thunder Bluff.\n\nIf you hunt beasts and bring me their skins, then I will fashion something for you.", sourceObjective = "Bring 12 pieces of Light Leather to Veren Tallstrider in Thunder Bluff.", progress = "Hello again.  Have you been hunting?  Do you have skins for me?", completion = "Ah, these are very nice pieces.  They'll make fine leather goods.\n\nHere, {name}.  Take this in trade...", sourceObjectiveStatus = "unverified-source-field" }
quests[769] = { id = 769, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kodo Hide Bag", description = "The kodo beasts of Mulgore are strong and sturdy -- traits much respected among us.  If you are skilled in leatherworking and wish the knowledge to make a Kodo Hide Bag, then bring me supplies for my trade.\n\nDo this, and I will share my knowledge with you.", sourceObjective = "Bring 4 Light Leather and 4 Coarse Thread to Veren Tallstrider in Thunder Bluff.", progress = "Do you have my supplies, {name}?", completion = "Ah, good.  Thank you, {name}.  My heart swells with pride to see youths interested in the craft of leatherworking.", sourceObjectiveStatus = "unverified-source-field" }
quests[770] = { id = 770, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Demon Scarred Cloak", description = "The ragged hide of Ghost Howl still bears a terrible wound, gained from the wolf's battles against the Burning Legion.\n\nPerhaps someone in Bloodhoof Village should know of Ghost Howl's demise....", sourceObjective = "Find someone who knows of Ghost Howl.\n\nProvided item:", completion = "I can barely believe my old eyes!  You defeated the great wolf Ghost Howl?  I look upon you with new respect, young {class}.  You are a hunter of extreme skills!\n\nLet me offer you something.  My days of hunting are over, but I would be honored if you used one of my weapons in your hunts.\n\nMay it strike true, and bring you renown.\n\nAnd let us hope that Ghost Howl's spirit has finally found peace.", sourceObjectiveStatus = "unverified-source-field" }
quests[771] = { id = 771, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rite of Vision", description = "In order to pass through the Rite of Vision, you must gather the reagents needed to make the Water of the Seers.\n\nI will need well stones, which can be found around the water wells in Mulgore. With those I will combine Ambercorn, which fall beneath the mighty trees in our land.\n\nThese reagents contain magical elements, and when brewed and consumed before the tribal fire, will cause you to encounter a vision. Follow it, and it will lead you to the next step of this holy quest.", sourceObjective = "Collect 2 Well Stones and 2 Ambercorn and bring them back to Zarlman Two-Moons in Bloodhoof Village.", progress = "Once you have gathered enough well stones from around the water wells and Ambercorn from beneath the trees, I will prepare the Water of the Seers for you.", completion = "I see you have learned to gather from our sacred land, {name}. It will take but a moment for me to brew the Water of the Seers.", sourceObjectiveStatus = "unverified-source-field" }
quests[772] = { id = 772, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rite of Vision", description = "I now present you with the Water of the Seers.\n\nWhen you are ready, consume the waters near the tribal fire. Once you have ingested the holy waters, it will take a few moments before the vision materializes before the fire.\n\nAt that point, it is up to you to follow it to your destiny....", sourceObjective = "Consume the Water of the Seers in front of the tribal fire in Bloodhoof Village and follow the vision once it appears.\n\nProvided item:", completion = "Be not afraid, {name}. You have successfully passed the Rite of Vision.", sourceObjectiveStatus = "unverified-source-field" }
quests[773] = { id = 773, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rite of Wisdom", description = "To gain acceptance amongst the elders of Thunder Bluff you must next complete the Rite of Wisdom.\n\nNow that you have passed the Rite of Vision, the ancestral spirits of Red Rocks will give you the blessing of our ancestors. Only those who have drunk from the Water of Seers can gain the blessing.\n\nTravel east of Thunder Bluff, to Red Rocks and seek out the Ancestral Spirit, {name}.", sourceObjective = "Travel to Red Rocks east of Thunder Bluff and speak with the Ancestral Spirit.", completion = "You have shown great diligence in your yearning to pass the Rites of the Earthmother, {name}.\n\nWe, the Ancestral Spirits, represent the mighty {race} who gave their lives bravely to found and protect our great city of Thunder Bluff. I hereby pass the duty of that protection over to you.\n\nYou have passed the Rite of Wisdom, young {class}. Enter Thunder Bluff with pride.", sourceObjectiveStatus = "unverified-source-field" }
quests[775] = { id = 775, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Journey into Thunder Bluff", description = "You will now be revered within our great city. Any {race} worthy of completing the Rites of the Earthmother earns that honor.\n\nFor your final quest, seek out our noble leader, Cairne Bloodhoof, who dwells atop the highest mesa in Thunder Bluff.", sourceObjective = "Speak with Cairne Bloodhoof in Thunder Bluff.", completion = "Hail, young {class}. I see you found your way to my doorstep.", sourceObjectiveStatus = "unverified-source-field" }
quests[776] = { id = 776, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rites of the Earthmother", description = "You have passed the Rites of the Earthmother and earned your place in Thunder Bluff.\n\nBut in order to maintain the spot that you strived so hard to achieve, you must continue to prove your worth to your people.\n\nWe are hunters, {name}. Down below in Mulgore there is a mighty kodo named Arra'chea. Show me your skills in the ways of tracking and hunting by bringing me the Horn of Arra'chea.", sourceObjective = "Cairne Bloodhoof in Thunder Bluff wants you to bring him the Horn of Arra'chea.", progress = "Have you tracked down Arra'chea yet?", completion = "Well done! A fine kill that was.\n\nI will send a gathering party to collect the carcass so we can retrieve the hide and meat.\n\nYou have done a great deed for your people, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[777] = { id = 777, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Is Going to Be Hard", description = "Okay, here you go.\n\nI'm going to be over here... behind cover.\n\nFeel free to join me.", sourceObjective = "Bring Cog #5 to Lotwil Veriatus.", progress = "<Without looking up from the shackles, Lotwil holds out a hand and waggles his fingers impatiently.>\n\nThe cog, {name}, the cog!", completion = "Ah, perfect. Stand back while I prepare to make more history!\n\n<Lotwil continues to work feverishly.>", sourceObjectiveStatus = "unverified-source-field" }
quests[778] = { id = 778, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Is Going to Be Hard", description = "Haha! Done! The shackles are done!\n\nIt's time, Lucien. It's time, Servo!\n\nAre you ready to bear witness to the perfect blend of alchemy, engineering, and the arcane, {name}?\n\nI shall summon forth a powerful elemental now. This is a groundbreaking day for all of us.", sourceObjective = "Defeat the Fam'retor Guardian and bring Lotwil's Shackles of Elemental Binding back to Lotwil Veriatus.", progress = "Not quite the outcome I was expecting. Could you get my shackles back?", completion = "Thank you, {name}. That was quite an ordeal, wasn't it?\n\nI'm not sure what could have gone wrong. It was a good thing my magics were here to help send the creature back to its home plane.\n\nPerhaps a little token of appreciation for all your hard work...", sourceObjectiveStatus = "unverified-source-field" }
quests[779] = { id = 779, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seal of the Earth", progress = "The Seal of the Earth lies here, with three recessed alcoves for the Amethyst Runestone, the Opal Runestone, and the Diamond Runestone.", completion = "As you place the Runestones into the matching recesses, a violent rumbling shakes the earth as the Seal is broken." }
quests[780] = { id = 780, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battleboars", description = "The Battleboars of Brambleblade Ravine to the east are encroaching on our tribal hunting grounds. They are trained to be malicious by the Bristleback Quilboars with whom we are at war.\n\nGo and slay the vile creatures and bring back some snouts and flanks so that we can make stew for our young.", sourceObjective = "Grull Hawkwind in Camp Narache wants you to kill Battleboars and bring back 8 Battleboar Snouts and 8 Battleboar Flanks.", progress = "The aggression of the Battleboars is increasing. Have you sent them a clear message and brought back some snouts and flanks yet?", completion = "Most excellent. These ingredients will make a fine stew and the loss of those boars should be a fair lesson to those vile Bristlebacks.", sourceObjectiveStatus = "unverified-source-field" }
quests[781] = { id = 781, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Attack on Camp Narache", description = "After carefully evaluating the map, you realize that what you discovered are the plans made by the Bristleback warchief for an extended siege on Camp Narache.\n\nSurely Chief Hawkwind could use this information!", sourceObjective = "Bring the Bristleback Attack Plans to Chief Hawkwind in Camp Narache.", progress = "You have a look of concern about you, {name}. What news do you bring?", completion = "This is quite alarming indeed! But with this information we can call on our brethren from Bloodhoof Village to help thwart the attack. You have saved the lives of many {race}, {name}.", sourceObjectiveStatus = "unverified-source-field" }
